// ---------- CAD-113: build slots ----------

/// A daemon with a shrunken slot config — hermetic (ServeOptions wins
/// over pm.yaml, so no host config can leak in).
fn slot_opts(build: usize, suite: usize, starve: u64, priority: &[&str]) -> daemon::ServeOptions {
    slot_opts_clock(build, suite, starve, priority, None)
}

/// `slot_opts` with an injected slot clock: a shared counter the test
/// advances instead of sleeping — starvation tests stay deterministic
/// under host load.
fn slot_opts_clock(
    build: usize,
    suite: usize,
    starve: u64,
    priority: &[&str],
    clock: Option<std::sync::Arc<std::sync::atomic::AtomicU64>>,
) -> daemon::ServeOptions {
    daemon::ServeOptions {
        slots: Some(cadence_agent::slots::SlotConfig {
            build_slots: build,
            suite_slots: suite,
            starve_secs: starve,
            priority_lanes: priority.iter().map(|s| s.to_string()).collect(),
            ..Default::default()
        }),
        slot_clock: clock.map(|c| {
            std::sync::Arc::new(move || c.load(std::sync::atomic::Ordering::Relaxed) as f64)
                as std::sync::Arc<dyn Fn() -> f64 + Send + Sync>
        }),
        ..daemon_opts()
    }
}

/// Plant `alias` as a live pty pane rooted at `pid` — the endpoint
/// facts the slot caller-identity derivation reads (CAD-113). The row
/// stays otherwise inert: registered as an actorless `inbox` pair and
/// marked `enabled=0`, so neither a register-time `set_identity` nor a
/// restart's relaunch sweep can overwrite or detach the planted facts.
/// `slot_*` RPCs derive caller identity from `SO_PEERCRED` + /proc
/// ancestry, so a test lane is only reachable from processes whose
/// ancestry includes this pid.
fn plant_pane(d: &TestDaemon, alias: &str, pid: u32) {
    // Register as an `inbox` mailbox: the pair owns no actor, so no
    // async `set_identity` can land after this plant and overwrite
    // the pid (`agent_register` on an existing alias errors —
    // idempotent on a daemon restarted over a kept state dir). And
    // `enabled=0` keeps a restarted daemon's relaunch sweep from
    // spawning a pty actor for the row — its open cannot verify a
    // planted pane and the exit-detach clears the pid the pane map
    // resolves callers by (the CAD-113 CI flake).
    let _ = d.fixture_rpc(
        "agent_register",
        json!({"alias": alias, "provider": "inbox",
               "endpoint_kind": "inbox",
               "cwd": d.dir.path().to_str().unwrap()}),
    );
    let conn = rusqlite::Connection::open(d.state.join("cadence.sqlite3")).unwrap();
    conn.execute(
        "UPDATE agents SET endpoint_kind='pty', pid=?1, pid_start=?3, enabled=0, \
            generation='planted', session_id='planted' WHERE alias=?2",
        rusqlite::params![pid as i64, alias, proc_start(pid)],
    )
    .unwrap();
}

/// `/proc/<pid>/stat` field 22 — what the daemon records as a pid's
/// `pid_start` (CAD-385), so a planted row names exactly that process.
fn proc_start(pid: u32) -> Option<i64> {
    let stat = std::fs::read_to_string(format!("/proc/{pid}/stat")).ok()?;
    stat.rsplit_once(')')?
        .1
        .split_whitespace()
        .nth(19)?
        .parse()
        .ok()
}

/// The lane every in-process `d.rpc` slot call derives: the test
/// process's own pid planted as this alias's pane.
const SELF_LANE: &str = "pane-self";

/// Plant the test process itself as `SELF_LANE`'s pane — after this,
/// `d.rpc` slot calls and `Command`-spawned cadence CLIs all run as
/// that lane (their ancestry always includes the test pid).
fn plant_self(d: &TestDaemon) {
    plant_pane(d, SELF_LANE, std::process::id());
}

/// A long-lived `bash` whose pid is planted as a lane's pane:
/// commands written to its stdin run as its children, so their
/// socket-peer identity derives that lane — the only way to get a
/// second connection identity in-process tests can't reach.
struct LaneShell {
    child: std::process::Child,
    stdin: std::process::ChildStdin,
    stdout: BufReader<std::process::ChildStdout>,
    dir: TempDir,
    seq: u64,
}

impl LaneShell {
    fn spawn(home: &Path) -> LaneShell {
        let mut child = std::process::Command::new("bash")
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null())
            .env("HOME", home)
            .envs(test_env().vars())
            .spawn()
            .unwrap();
        LaneShell {
            stdin: child.stdin.take().unwrap(),
            stdout: BufReader::new(child.stdout.take().unwrap()),
            child,
            dir: TempDir::new().unwrap(),
            seq: 0,
        }
    }

    fn pid(&self) -> u32 {
        self.child.id()
    }

    /// Run a bash fragment under this lane; answer (exit code, output).
    fn run(&mut self, cmd: &str) -> (i64, String) {
        let tag = format!("__lane_rc_{}__", self.seq);
        self.seq += 1;
        // The bare `echo` first guarantees the marker opens a fresh
        // line even when the command's output ends mid-line.
        writeln!(self.stdin, "{{ {cmd} ; }} 2>&1; rc=$?; echo; echo {tag}$rc").unwrap();
        self.stdin.flush().unwrap();
        let mut out = String::new();
        loop {
            let mut line = String::new();
            assert!(
                self.stdout.read_line(&mut line).unwrap() > 0,
                "lane shell exited while running: {cmd}"
            );
            if let Some(rc) = line.strip_prefix(&tag) {
                return (rc.trim().parse().unwrap(), out);
            }
            out.push_str(&line);
        }
    }

    /// `cadence <args>` run under this lane's identity.
    fn cadence(&mut self, state: &Path, args: &str) -> (i64, String) {
        self.run(&format!(
            "{} --state-dir {} {args}",
            env!("CARGO_BIN_EXE_cadence"),
            state.display()
        ))
    }

    /// One raw JSONL RPC under this lane's identity — the answer is
    /// the wire frame (`{"ok":…, "result"|"error":…}`).
    fn rpc(&mut self, state: &Path, method: &str, params: Value) -> Value {
        let req = self.dir.path().join(format!("req-{}.json", self.seq));
        std::fs::write(
            &req,
            cadence_agent::proto::request(method, params).to_string(),
        )
        .unwrap();
        let (rc, out) = self.run(&format!(
            "python3 -c 'import socket,sys;\
             s=socket.socket(socket.AF_UNIX);s.connect(sys.argv[1]);\
             s.sendall(open(sys.argv[2],\"rb\").read()+b\"\\n\");\
             print(s.makefile().readline())' {} {}",
            client::socket_path(state).display(),
            req.display()
        ));
        assert_eq!(rc, 0, "lane rpc failed: {out}");
        serde_json::from_str(out.trim()).unwrap()
    }
}

impl Drop for LaneShell {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

/// CAD-149 / CAD-304 S3 fleet: `pm` and `pm2` are group roots, `w1` a
/// worker in pm's group — each a planted pane whose [`LaneShell`]
/// commands derive that agent from `/proc` ancestry. The rows stay
/// inert like [`plant_pane`]'s; `w1` is planted as a claude pty so its
/// own `--next-launch model/effort` validates.
struct GuardPanes {
    pm: LaneShell,
    pm2: LaneShell,
    w1: LaneShell,
    _home: TempDir,
}

fn plant_member_pane(
    d: &TestDaemon,
    alias: &str,
    provider: &str,
    upstream: Option<&str>,
    pid: u32,
) {
    let mut req = json!({"alias": alias, "provider": "inbox",
                         "endpoint_kind": "inbox",
                         "cwd": d.dir.path().to_str().unwrap()});
    if let Some(pm) = upstream {
        req["params"] = json!(json!({"upstream": pm}).to_string());
    }
    d.fixture_rpc("agent_register", req).unwrap();
    let conn = rusqlite::Connection::open(d.state.join("cadence.sqlite3")).unwrap();
    conn.execute(
        "UPDATE agents SET provider=?1, endpoint_kind='pty', pid=?2, pid_start=?4, \
            enabled=0, generation='planted', session_id='planted' WHERE alias=?3",
        rusqlite::params![provider, pid as i64, alias, proc_start(pid)],
    )
    .unwrap();
}

fn guard_panes(d: &TestDaemon) -> GuardPanes {
    let home = TempDir::new().unwrap();
    let pm = LaneShell::spawn(home.path());
    let pm2 = LaneShell::spawn(home.path());
    let w1 = LaneShell::spawn(home.path());
    plant_member_pane(d, "pm", "inbox", None, pm.pid());
    plant_member_pane(d, "pm2", "inbox", None, pm2.pid());
    plant_member_pane(d, "w1", "claude", Some("pm"), w1.pid());
    GuardPanes {
        pm,
        pm2,
        w1,
        _home: home,
    }
}

/// One raw RPC from a process tied to no pane that is not provably the
/// operator either: its own environment carries an agent's alias (a
/// detached pane process that kept its env looks like this).
fn unprovable_rpc(d: &TestDaemon, method: &str, params: Value) -> Value {
    let out = std::process::Command::new("python3")
        .arg("-c")
        .arg(
            "import socket,sys;s=socket.socket(socket.AF_UNIX);s.connect(sys.argv[1]);\
             s.sendall(sys.argv[2].encode()+b'\\n');print(s.makefile().readline())",
        )
        .arg(client::socket_path(&d.state))
        .arg(cadence_agent::proto::request(method, params).to_string())
        .env("CADENCE_ALIAS", "detached-w1")
        .stdin(std::process::Stdio::null())
        .output()
        .unwrap();
    assert!(out.status.success(), "{out:?}");
    serde_json::from_slice(&out.stdout).unwrap()
}

fn frame_err(frame: &Value) -> String {
    frame["error"]["message"]
        .as_str()
        .unwrap_or_default()
        .to_string()
}

/// `params_updated` events on `alias`'s stream that carry a caller.
fn audited_param_updates(d: &TestDaemon, alias: &str) -> Vec<Value> {
    d.rpc("agent_events", json!({"alias": alias, "after": 0}))
        .unwrap()["events"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|e| e["kind"] == "params_updated" && !e["payload"]["by"].is_null())
        .map(|e| e["payload"].clone())
        .collect()
}

/// CAD-149: who may change which `--next-launch` key, per caller kind,
/// with the caller derived from the connection — never claimed.
#[test]
fn agent_set_caller_rule_per_caller_kind() {
    let d = TestDaemon::start();
    let _mock = d.mock_codex("ok");
    let mut p = guard_panes(&d);
    d.rpc(
        "agent_register",
        json!({"alias": "w2", "provider": "codex", "endpoint_kind": "managed",
               "cwd": d.dir.path().to_str().unwrap(),
               "params": json!({"upstream": "pm",
                                "approval_policy": "on-request"}).to_string()}),
    )
    .unwrap();
    d.wait_agent("w2", "idle", 15);
    let set = |policy: &str| {
        json!({"alias": "w2", "next_launch": true,
               "patch": {"approval_policy": policy}})
    };
    let param = |alias: &str, key: &str| {
        d.rpc("agent_show", json!({"alias": alias})).unwrap()["agent"]["params"][key].clone()
    };

    // A peer worker's pane: trust-bearing and self-service keys alike.
    let r = p.w1.rpc(&d.state, "agent_set", set("never"));
    let e = frame_err(&r);
    assert!(
        e.contains("agent 'w1' cannot change another agent") && e.contains("its PM 'pm'"),
        "{r}"
    );
    let r = p.w1.rpc(
        &d.state,
        "agent_set",
        json!({"alias": "w2", "next_launch": true, "patch": {"model": "gpt-x"}}),
    );
    assert!(frame_err(&r).contains("cannot change another agent"), "{r}");
    // Another group's PM.
    let r = p.pm2.rpc(&d.state, "agent_set", set("never"));
    assert!(
        frame_err(&r).contains("agent 'pm2' cannot change another agent"),
        "{r}"
    );
    // Tied to no pane and not provably the operator.
    let r = unprovable_rpc(&d, "agent_set", set("never"));
    assert!(frame_err(&r).contains("not provably the operator"), "{r}");
    // A claimed identity never changes who is asking: identity-shaped
    // request fields are refused, and an exported CADENCE_ALIAS of the
    // PM leaves the CLI caller the pane it runs in.
    for field in ["by", "pane", "as", "reviewer"] {
        let mut forged = set("never");
        forged[field] = json!("operator");
        let r = p.w1.rpc(&d.state, "agent_set", forged);
        assert!(
            frame_err(&r).contains(&format!("'{field}' is not accepted")),
            "{r}"
        );
    }
    let (rc, out) = p.w1.run(&format!(
        "CADENCE_ALIAS=pm {} --state-dir {} agent set w2 approval_policy=never --next-launch",
        env!("CARGO_BIN_EXE_cadence"),
        d.state.display()
    ));
    assert_ne!(rc, 0, "{out}");
    assert!(
        out.contains("agent 'w1' cannot change another agent"),
        "{out}"
    );
    assert_eq!(param("w2", "approval_policy"), "on-request");
    assert!(audited_param_updates(&d, "w2").is_empty());

    // The worker on itself: model/effort only.
    let r = p.w1.rpc(
        &d.state,
        "agent_set",
        json!({"alias": "w1", "next_launch": true,
               "patch": {"model": "opus", "effort": "high"}}),
    );
    assert_eq!(r["ok"], true, "{r}");
    assert_eq!(param("w1", "model"), "opus");
    for patch in [
        json!({"approval_policy": "never"}),
        // A mixed patch is judged by its most sensitive key — and
        // applies nothing.
        json!({"model": "sonnet", "approval_policy": "never"}),
    ] {
        let r = p.w1.rpc(
            &d.state,
            "agent_set",
            json!({"alias": "w1", "next_launch": true, "patch": patch}),
        );
        assert!(
            frame_err(&r).contains("agent 'w1' cannot make this change to itself"),
            "{r}"
        );
    }
    assert_eq!(param("w1", "model"), "opus");
    // Posture (a live key) is not self-service either.
    let r = p.w1.rpc(
        &d.state,
        "agent_set",
        json!({"alias": "w1", "patch": {"auto_stop": "off"}}),
    );
    assert!(
        frame_err(&r).contains("cannot make this change to itself"),
        "{r}"
    );
    // A PM is not its own PM.
    let r = p.pm.rpc(
        &d.state,
        "agent_set",
        json!({"alias": "pm", "next_launch": true,
               "patch": {"approval_policy": "never"}}),
    );
    assert!(
        frame_err(&r).contains("agent 'pm' cannot make this change to itself"),
        "{r}"
    );

    // The target's own PM, then the operator: accepted and recorded
    // with the derived caller and each key's old and new value.
    let r = p.pm.rpc(&d.state, "agent_set", set("never"));
    assert_eq!(r["ok"], true, "{r}");
    assert_eq!(param("w2", "approval_policy"), "never");
    d.operator_rpc("agent_set", set("untrusted")).unwrap();
    assert_eq!(param("w2", "approval_policy"), "untrusted");
    let updates = audited_param_updates(&d, "w2");
    assert_eq!(updates.len(), 2, "{updates:?}");
    assert_eq!(updates[0]["by"], "pm", "{updates:?}");
    assert_eq!(updates[0]["by_kind"], "agent", "{updates:?}");
    assert_eq!(updates[0]["target"], "w2", "{updates:?}");
    assert_eq!(updates[0]["next_launch"], true, "{updates:?}");
    assert_eq!(
        updates[0]["changes"],
        json!([{"key": "approval_policy", "old": "on-request", "new": "never"}])
    );
    assert_eq!(updates[1]["by"], "operator", "{updates:?}");
    assert_eq!(updates[1]["by_kind"], "operator", "{updates:?}");
    assert_eq!(
        updates[1]["changes"],
        json!([{"key": "approval_policy", "old": "never", "new": "untrusted"}])
    );
    let own = audited_param_updates(&d, "w1");
    assert_eq!(own.len(), 1, "{own:?}");
    assert_eq!(own[0]["by"], "w1", "{own:?}");
}

/// CAD-304 S3: `agent remove` (plain or `--force`) and `agent gc`
/// delete history — the operator's or the target's own PM's call,
/// never a peer's, another group's PM's or the agent's own.
#[test]
fn agent_remove_and_gc_caller_rule_per_caller_kind() {
    let d = TestDaemon::start();
    let mut p = guard_panes(&d);
    for w in ["w3", "w4", "w5"] {
        d.register_member(w, "pm");
    }
    d.register("w6");
    for w in ["w3", "w4", "w5", "w6"] {
        d.wait_agent(w, "idle", 10);
        d.rpc("agent_stop", json!({"alias": w})).unwrap();
        d.wait_agent(w, "stopped", 15);
    }
    let present = |alias: &str| d.rpc("agent_show", json!({"alias": alias})).is_ok();

    for force in [false, true] {
        let r = p.w1.rpc(
            &d.state,
            "agent_remove",
            json!({"alias": "w3", "force": force}),
        );
        assert!(
            frame_err(&r).contains("agent 'w1' cannot change another agent"),
            "{r}"
        );
        let r = p.pm2.rpc(
            &d.state,
            "agent_remove",
            json!({"alias": "w3", "force": force}),
        );
        assert!(
            frame_err(&r).contains("agent 'pm2' cannot change another agent"),
            "{r}"
        );
    }
    let r = p.w1.rpc(&d.state, "agent_remove", json!({"alias": "w1"}));
    assert!(
        frame_err(&r).contains("agent 'w1' cannot make this change to itself"),
        "{r}"
    );
    let r = unprovable_rpc(&d, "agent_remove", json!({"alias": "w3"}));
    assert!(frame_err(&r).contains("not provably the operator"), "{r}");
    let r =
        p.w1.rpc(&d.state, "agent_remove", json!({"alias": "w3", "by": "pm"}));
    assert!(frame_err(&r).contains("'by' is not accepted"), "{r}");
    let (rc, out) = p.w1.run(&format!(
        "CADENCE_ALIAS=pm {} --state-dir {} agent remove w3 --force",
        env!("CARGO_BIN_EXE_cadence"),
        d.state.display()
    ));
    assert_ne!(rc, 0, "{out}");
    assert!(
        out.contains("agent 'w1' cannot change another agent"),
        "{out}"
    );
    // A sweep from a worker's pane removes nothing it is not PM of.
    let r = p.w1.rpc(&d.state, "agent_gc", json!({}));
    assert_eq!(r["result"]["removed"], json!([]), "{r}");
    assert_eq!(
        r["result"]["not_permitted"],
        json!(["w3", "w4", "w5", "w6"]),
        "{r}"
    );
    let r = unprovable_rpc(&d, "agent_gc", json!({}));
    assert!(frame_err(&r).contains("not provably the operator"), "{r}");
    for w in ["w1", "w3", "w4", "w5", "w6"] {
        assert!(present(w), "{w} was removed by a refused caller");
    }

    // The target's own PM: removes its member, sweeps only its group.
    let r = p.pm.rpc(&d.state, "agent_remove", json!({"alias": "w3"}));
    assert_eq!(r["ok"], true, "{r}");
    let r = p.pm.rpc(&d.state, "agent_gc", json!({}));
    assert_eq!(r["result"]["removed"], json!(["w4", "w5"]), "{r}");
    assert_eq!(r["result"]["not_permitted"], json!(["w6"]), "{r}");
    // The operator: anything.
    d.operator_rpc("agent_remove", json!({"alias": "w6"}))
        .unwrap();
    let removals: Vec<(String, String)> = d
        .rpc("agent_events", json!({"alias": "daemon", "after": 0}))
        .unwrap()["events"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|e| e["kind"] == "agent_removed")
        .map(|e| {
            (
                e["payload"]["alias"].as_str().unwrap().to_string(),
                e["payload"]["by"].as_str().unwrap().to_string(),
            )
        })
        .collect();
    let want: Vec<(String, String)> =
        [("w3", "pm"), ("w4", "pm"), ("w5", "pm"), ("w6", "operator")]
            .iter()
            .map(|(a, b)| (a.to_string(), b.to_string()))
            .collect();
    assert_eq!(removals, want);
}

/// CAD-149 review F2, the reproduced sequence: the operator removes a
/// PM whose members survive, and the PM's alias is registered again.
/// The worker's attempt is refused outright (F3); and even a PM alias
/// the operator re-registers gains no authority over the members the
/// old PM left behind — PM authority is bound to a registration older
/// than the member, not to the name.
#[test]
fn reregistered_pm_alias_inherits_no_authority() {
    let d = TestDaemon::start();
    let mut p = guard_panes(&d);
    d.register_member("w2", "pm");
    d.wait_agent("w2", "idle", 10);
    let stall = |secs: &str| json!({"alias": "w2", "patch": {"stall_secs": secs}});
    // The real PM governs its member.
    let r = p.pm.rpc(&d.state, "agent_set", stall("600"));
    assert_eq!(r["ok"], true, "{r}");

    // The PM stops (its planted row is otherwise "live"), and the
    // operator removes it while its members survive.
    rusqlite::Connection::open(d.state.join("cadence.sqlite3"))
        .unwrap()
        .execute(
            "UPDATE agents SET endpoint=NULL, state='stopped' WHERE alias='pm'",
            [],
        )
        .unwrap();
    d.operator_rpc("agent_remove", json!({"alias": "pm"}))
        .unwrap();
    // The worker tries to take the PM's alias from its own pane.
    let r = p.w1.rpc(
        &d.state,
        "agent_register",
        json!({"alias": "pm", "provider": "inbox", "endpoint_kind": "inbox",
               "cwd": d.dir.path().to_str().unwrap()}),
    );
    assert!(
        frame_err(&r).contains("agent 'w1' may register only its own members"),
        "{r}"
    );
    assert!(d.rpc("agent_show", json!({"alias": "pm"})).is_err());
    // Re-registered (here by the operator) behind a new pane: no
    // authority over the orphaned member.
    let home = TempDir::new().unwrap();
    let mut pm_new = LaneShell::spawn(home.path());
    plant_member_pane(&d, "pm", "inbox", None, pm_new.pid());
    for (method, params) in [
        ("agent_set", stall("0")),
        ("agent_remove", json!({"alias": "w2", "force": true})),
    ] {
        let r = pm_new.rpc(&d.state, method, params);
        let e = frame_err(&r);
        assert!(
            e.contains("agent 'pm' cannot change another agent")
                && e.contains("the operator (it has no PM)"),
            "{r}"
        );
    }
    let r = pm_new.rpc(&d.state, "agent_gc", json!({}));
    assert_eq!(r["result"]["removed"], json!([]), "{r}");
    assert_eq!(
        d.rpc("agent_show", json!({"alias": "w2"})).unwrap()["agent"]["params"]["stall_secs"],
        "600"
    );
    // A member joined AFTER the new registration is the new PM's.
    let r = pm_new.rpc(
        &d.state,
        "agent_register",
        json!({"alias": "w3", "provider": "fake", "endpoint_kind": "fake",
               "cwd": d.dir.path().to_str().unwrap(),
               "params": json!({"upstream": "pm"}).to_string()}),
    );
    assert_eq!(r["ok"], true, "{r}");
    d.wait_agent("w3", "idle", 10);
    let r = pm_new.rpc(
        &d.state,
        "agent_set",
        json!({"alias": "w3", "patch": {"stall_secs": "600"}}),
    );
    assert_eq!(r["ok"], true, "{r}");
}

/// CAD-149 review F3: registration is a mutation of the new agent by
/// its caller. A worker's pane may register nothing — not an agent it
/// would own with trust-bearing params, not a member of its PM's group,
/// not a root; another group's PM may not register into this group;
/// a PM registers its own members (raw RPC and `cadence join` from its
/// pane), and the operator shell joins as before.
#[test]
fn agent_register_caller_rule() {
    let d = TestDaemon::start();
    let _mock = d.mock_codex("ok");
    let mut p = guard_panes(&d);
    let cwd = d.dir.path().to_str().unwrap().to_string();
    let codex = |alias: &str, params: Value| {
        json!({"alias": alias, "provider": "codex", "endpoint_kind": "managed",
               "cwd": cwd, "params": params.to_string()})
    };
    // The reproduced case: a worker mints an agent it would be PM of,
    // carrying a key it may not set on itself.
    let r = p.w1.rpc(
        &d.state,
        "agent_register",
        codex("wx", json!({"upstream": "w1", "approval_policy": "never"})),
    );
    let e = frame_err(&r);
    assert!(
        e.contains("agent 'w1' may register only its own members")
            && e.contains("'w1' is a worker in 'pm''s group"),
        "{r}"
    );
    for params in [json!({"upstream": "pm"}), json!({})] {
        let r = p.w1.rpc(&d.state, "agent_register", codex("wx", params));
        assert!(
            frame_err(&r).contains("may register only its own members"),
            "{r}"
        );
    }
    // Through the CLI too.
    let (rc, out) = p.w1.cadence(&d.state, "join w1 fake --alias wy --detach");
    assert_ne!(rc, 0, "{out}");
    assert!(out.contains("may register only its own members"), "{out}");
    // Another group's PM cannot register into pm's group, nor a root.
    let r = p.pm2.rpc(
        &d.state,
        "agent_register",
        codex("wx", json!({"upstream": "pm"})),
    );
    assert!(
        frame_err(&r).contains("would answer to 'pm', not to 'pm2'"),
        "{r}"
    );
    let r = p
        .pm2
        .rpc(&d.state, "agent_register", codex("wx", json!({})));
    assert!(frame_err(&r).contains("would be a group root"), "{r}");
    for alias in ["wx", "wy"] {
        assert!(d.rpc("agent_show", json!({"alias": alias})).is_err());
    }
    // An existing alias is the store's duplicate refusal — nothing to
    // authorize, and the launch verbs' reopen path keys off it.
    let r = p.w1.rpc(
        &d.state,
        "agent_register",
        json!({"alias": "pm2", "provider": "inbox", "endpoint_kind": "inbox",
               "cwd": cwd}),
    );
    assert!(!frame_err(&r).contains("caller rule"), "{r}");
    assert!(r["ok"] != true, "{r}");

    // The PM registers its own member — trust-bearing params included.
    let r = p.pm.rpc(
        &d.state,
        "agent_register",
        codex("wp", json!({"upstream": "pm", "approval_policy": "never"})),
    );
    assert_eq!(r["ok"], true, "{r}");
    d.wait_agent("wp", "idle", 15);
    let (rc, out) = p.pm.cadence(&d.state, "join pm fake --alias wj --detach");
    assert_eq!(rc, 0, "{out}");
    d.wait_agent("wj", "idle", 15);
    let (ok, _, err) = d.operator_cadence(&["join", "pm", "fake", "--alias", "wo", "--detach"]);
    assert!(ok, "{err}");
    d.wait_agent("wo", "idle", 15);
    for alias in ["wj", "wo", "wp"] {
        let show = d.rpc("agent_show", json!({"alias": alias})).unwrap();
        assert_eq!(show["agent"]["params"]["upstream"], "pm", "{show}");
    }
}

/// CAD-304 S4 / review F4, operator ruling: `--force` unassigns the
/// removed alias's open tasks in the same transaction — state, revision
/// and history kept, the PM told — so an agent registered again under
/// the alias inherits nothing, and dispatch refuses until the task is
/// reassigned, naming the remedy.
#[test]
fn agent_remove_force_unassigns_open_tasks() {
    let d = TestDaemon::start();
    d.register("pm");
    d.register_member("w1", "pm");
    d.register_member("w2", "pm");
    for a in ["pm", "w1", "w2"] {
        d.wait_agent(a, "idle", 10);
    }
    let (spec, sha) = d.spec_file("spec.md", "unassign on force");
    d.job_new("pm", "j1", &spec, &sha);
    d.rpc(
        "task_new",
        json!({"job": "j1", "task": "t1", "assignee": "w1",
               "acceptance": format!("tests pass REPORT_SHA:{SHA_A}")}),
    )
    .unwrap();
    d.rpc(
        "task_new",
        json!({"job": "j1", "task": "t2", "assignee": "w1",
               "acceptance": "later"}),
    )
    .unwrap();
    let kickoff = d.job_dispatch("t1", json!({})).unwrap()["message"]
        .as_str()
        .unwrap()
        .to_string();
    d.wait_message("w1", &kickoff, &["completed"], 15);
    d.wait_task("t1", "review", 15);
    d.rpc("agent_stop", json!({"alias": "w1"})).unwrap();
    d.wait_agent("w1", "stopped", 15);

    d.operator_rpc("agent_remove", json!({"alias": "w1", "force": true}))
        .unwrap();
    let forced = forced_removals(&d);
    assert_eq!(forced.len(), 1, "{forced:?}");
    assert_eq!(forced[0]["payload"]["unassigned"], json!(["t1", "t2"]));
    let job = d.rpc("job_show", json!({"job": "j1"})).unwrap()["job"].clone();
    let task = |id: &str| {
        job["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|t| t["id"] == id)
            .unwrap()
            .clone()
    };
    assert!(task("t1")["assignee"].is_null(), "{job}");
    assert_eq!(task("t1")["state"], "review", "{job}");
    assert_eq!(task("t1")["kickoff"]["id"], kickoff.as_str(), "{job}");
    assert!(task("t2")["assignee"].is_null(), "{job}");
    assert_eq!(task("t2")["state"], "draft", "{job}");
    // The PM hears which tasks to reassign.
    let pm_notes: Vec<String> = d.rpc("agent_show", json!({"alias": "pm"})).unwrap()["messages"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|m| m["source"] == "job_event")
        .filter_map(|m| m["body"].as_str().map(str::to_string))
        .filter(|b| b.contains("is unassigned"))
        .collect();
    assert_eq!(pm_notes.len(), 2, "{pm_notes:?}");
    assert!(
        pm_notes.iter().all(|b| b.contains("--to <worker>")),
        "{pm_notes:?}"
    );

    // Re-registered: nothing attaches to the new agent.
    d.register_member("w1", "pm");
    d.wait_agent("w1", "idle", 10);
    let list = d.rpc("agent_list", json!({})).unwrap();
    let w1 = list["agents"]
        .as_array()
        .unwrap()
        .iter()
        .find(|a| a["alias"] == "w1")
        .unwrap()
        .clone();
    assert_eq!(w1["tasks"], json!([]), "{w1}");
    // Dispatch refuses the unassigned task until it is reassigned.
    let err = d.job_dispatch("t2", json!({})).unwrap_err().to_string();
    assert!(
        err.contains("has no assignee") && err.contains("--to <worker>"),
        "{err}"
    );
    // Reassigned, it dispatches — to the new w1 as well: no
    // "unfinished task work" inherited from the old one.
    d.job_dispatch("t2", json!({"to": "w1"})).unwrap();
    assert_ne!(d.task_state("t2"), "draft");
    // And a plain removal of the new agent meets only its own work.
    d.rpc("agent_stop", json!({"alias": "w1"})).unwrap();
    d.wait_agent("w1", "stopped", 15);
    let err = d
        .operator_rpc("agent_remove", json!({"alias": "w1"}))
        .unwrap_err()
        .to_string();
    assert!(err.contains("task t2") && !err.contains("task t1"), "{err}");
}

/// CAD-304 S2: a forced removal cancels queued work through the normal
/// cancel path — the `reply_to` hears it, and the forced event names
/// who was notified and by whom.
#[test]
fn agent_remove_force_notifies_reply_to() {
    let d = TestDaemon::start();
    d.register("pm");
    d.register_member("w1", "pm");
    d.wait_agent("pm", "idle", 10);
    d.wait_agent("w1", "idle", 10);
    d.rpc("agent_stop", json!({"alias": "w1"})).unwrap();
    d.wait_agent("w1", "stopped", 15);
    d.rpc(
        "agent_send",
        json!({"alias": "w1", "text": "later", "message": "m-queued", "reply_to": "pm"}),
    )
    .unwrap();
    d.operator_rpc("agent_remove", json!({"alias": "w1", "force": true}))
        .unwrap();
    let forced = forced_removals(&d);
    assert_eq!(forced.len(), 1, "{forced:?}");
    assert_eq!(
        forced[0]["payload"]["notified"],
        json!(["pm"]),
        "{forced:?}"
    );
    assert_eq!(forced[0]["payload"]["by"], "operator", "{forced:?}");
    let notice = uuid::Uuid::new_v5(
        &uuid::Uuid::NAMESPACE_URL,
        b"cadence-notice:cancelled:m-queued",
    )
    .simple()
    .to_string();
    let m = d.wait_message("pm", &notice, &["completed", "queued", "running"], 15);
    assert_eq!(m["source"], "worker_notice", "{m}");
    assert!(
        m["body"].as_str().unwrap_or_default().contains("m-queued"),
        "{m}"
    );
}

/// `slot_acquire` with the test process's pid — alive for the whole
/// test, so the pid check never reaps a live waiter here. The lane
/// param is ignored by the daemon (identity is the connection's);
/// callers pass SELF_LANE for honesty.
fn slot_acquire(d: &TestDaemon, kind: &str, lane: &str, req: &str) -> Value {
    slot_acquire_pid(d, kind, lane, std::process::id(), req)
}

/// `slot_acquire` claiming an explicit pid — must be the test process
/// or one of its /proc ancestors, or the daemon refuses.
fn slot_acquire_pid(d: &TestDaemon, kind: &str, lane: &str, pid: u32, req: &str) -> Value {
    d.rpc(
        "slot_acquire",
        json!({"kind": kind, "lane": lane, "pid": pid,
               "request_id": req}),
    )
    .unwrap()
}

/// `slot_release` naming the holding (lane, pid) — the identity the
/// grant was bound to.
fn slot_release(d: &TestDaemon, token: &str, lane: &str, pid: u32) -> Value {
    d.rpc(
        "slot_release",
        json!({"token": token, "lane": lane, "pid": pid}),
    )
    .unwrap()
}

/// N+1 acquires: the last queues until a release, FIFO order is kept,
/// and slot events land on the caller's stream. Every call here runs
/// as `SELF_LANE` — identity is connection-derived (CAD-113).
#[test]
fn slot_acquire_queues_until_release() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let g1 = slot_acquire(&d, "build", SELF_LANE, "r1");
    assert_eq!(g1["granted"], true);
    let t1 = g1["token"].as_str().unwrap().to_string();
    assert!(t1.starts_with("slot-"), "the daemon mints the token: {t1}");
    // The next acquire queues — answered, never hung.
    let q = slot_acquire(&d, "build", SELF_LANE, "r2");
    assert_eq!(q["granted"], false);
    assert_eq!(q["position"], 1);
    let s = d.rpc("slot_status", json!({})).unwrap();
    assert_eq!(s["pools"]["build"]["held"].as_array().unwrap().len(), 1);
    // The owner sees its own token — the hold's pid is on its chain.
    assert_eq!(
        s["pools"]["build"]["held"][0]["token"], t1,
        "the holding process's own chain sees its token"
    );
    let waiting = s["waiting"].as_array().unwrap();
    assert_eq!(waiting.len(), 1);
    assert_eq!(waiting[0]["lane"], SELF_LANE);
    // A re-poll keeps the original place — same request id, same
    // position, no second slot_waited.
    let q = slot_acquire(&d, "build", SELF_LANE, "r2");
    assert_eq!(q["position"], 1);
    // Release frees the pool; the waiter's next poll grants.
    slot_release(&d, &t1, SELF_LANE, std::process::id());
    let g2 = slot_acquire(&d, "build", SELF_LANE, "r2");
    assert_eq!(g2["granted"], true);
    let t2 = g2["token"].as_str().unwrap().to_string();
    assert_ne!(t2, t1, "each grant mints a fresh token");
    // And a re-poll of a granted id returns the same token (the CLI's
    // poll loop depends on this idempotency).
    let again = slot_acquire(&d, "build", SELF_LANE, "r2");
    assert_eq!(again["token"], t2);
    let kinds = |a: &str| {
        d.events(a)
            .iter()
            .map(|e| e["kind"].as_str().unwrap().to_string())
            .collect::<Vec<_>>()
    };
    let own = kinds(SELF_LANE);
    assert!(own.contains(&"slot_acquired".to_string()));
    assert!(own.contains(&"slot_released".to_string()));
    assert_eq!(
        own.iter().filter(|k| *k == "slot_waited").count(),
        1,
        "one slot_waited for the whole wait: {own:?}"
    );
}

/// A holder whose pid dies frees its slot on the next acquire —
/// nothing kills the work, the slot just stops being owed by a corpse.
/// The hold binds to a lane shell's pid: killing the shell kills the
/// hold's owner.
#[test]
fn slot_dead_holder_is_reaped() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let mut holder = LaneShell::spawn(home.path());
    plant_pane(&d, "dev-1", holder.pid());
    // The holder's child claims its own pane — `$$` in the shell is
    // the planted pane pid itself.
    let g = holder.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "build", "pid": holder.pid(), "request_id": "r1"}),
    );
    assert_eq!(g["ok"], true, "{g}");
    let token = g["result"]["token"].as_str().unwrap().to_string();
    holder.child.kill().unwrap();
    holder.child.wait().unwrap(); // reap the zombie so kill(pid,0) answers ESRCH
    let g2 = slot_acquire(&d, "build", SELF_LANE, "r2");
    assert_eq!(g2["granted"], true, "dead holder's slot must free");
    // The reap names the cause on the dead lane's stream.
    let evs = d.events("dev-1");
    assert!(
        evs.iter()
            .any(|e| e["kind"].as_str() == Some("slot_released")
                && e["payload"]["reason"].as_str() == Some("holder died")),
        "{evs:?}"
    );
    // Releasing the dead token is a named refusal, not a silent pass
    // — and nobody can claim the dead pid anyway.
    let err = d
        .rpc(
            "slot_release",
            json!({"token": token, "pid": std::process::id()}),
        )
        .unwrap_err();
    assert!(err.to_string().contains("Unknown slot token"), "{err}");
}

/// BLOCKER: two callers sharing a request_id — the second queues, it
/// never adopts the first's hold; a same-identity re-poll does. The
/// "different pid" is the test's own parent — a second pid on the
/// connection's ancestry that may legitimately be claimed (CAD-113).
#[test]
fn slot_duplicate_request_id_different_pid_queues() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let parent = std::os::unix::process::parent_id();
    let g1 = slot_acquire_pid(&d, "build", SELF_LANE, parent, "r1");
    assert_eq!(g1["granted"], true);
    // Same request_id claiming a different pid — a different caller:
    // queued, never granted the first's hold.
    let q = slot_acquire(&d, "build", SELF_LANE, "r1");
    assert_eq!(q["granted"], false, "must not adopt another caller's hold");
    let s = d.rpc("slot_status", json!({})).unwrap();
    assert_eq!(s["waiting"].as_array().unwrap().len(), 1);
    // The true holder re-polls and still gets its own token.
    let again = slot_acquire_pid(&d, "build", SELF_LANE, parent, "r1");
    assert_eq!(again["token"], g1["token"]);
}

/// BLOCKER: release binds to the holding (lane, pid) — both derived
/// from the connection now. A foreign lane's release is a named
/// refusal; a claimed pid off the caller's own ancestry is refused
/// before the token is even looked at. The hold survives both.
#[test]
fn slot_release_foreign_caller_is_rejected() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let mut foreign = LaneShell::spawn(home.path());
    plant_pane(&d, "dev-2", foreign.pid());
    let g = slot_acquire(&d, "build", SELF_LANE, "r1");
    let token = g["token"].as_str().unwrap().to_string();
    // The foreign lane knows the token but its derived lane doesn't
    // match the hold — refused. (The `pid` claim is honest here.)
    let f = foreign.rpc(
        &d.state,
        "slot_release",
        json!({"token": token, "pid": foreign.pid()}),
    );
    assert_eq!(f["ok"], false, "{f}");
    assert!(
        f["error"]["message"]
            .as_str()
            .unwrap()
            .contains("another caller"),
        "{f}"
    );
    // A claimed pid off the caller's own chain — a sibling lane's pid
    // is a live pid the shell does not descend from — is refused
    // outright, before the token is even looked at.
    let sibling = LaneShell::spawn(home.path());
    let f = foreign.rpc(
        &d.state,
        "slot_release",
        json!({"token": token, "pid": sibling.pid()}),
    );
    assert_eq!(f["ok"], false, "{f}");
    assert!(
        f["error"]["message"]
            .as_str()
            .unwrap()
            .contains("cannot claim"),
        "{f}"
    );
    // The hold still stands — the pool stays full.
    let q = slot_acquire(&d, "build", SELF_LANE, "r2");
    assert_eq!(q["granted"], false, "failed release must not free the slot");
    // And the true holder releases normally.
    slot_release(&d, &token, SELF_LANE, std::process::id());
}

/// ACCEPTANCE: `slot_status` reveals a token only to the connection
/// whose derived identity owns the hold — two real lanes. The owner
/// sees its token; a foreign lane passing the owner's `lane` sees the
/// hold but never the token (CAD-113 identity fork, option A).
#[test]
fn slot_status_reveals_tokens_only_to_the_owner() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut owner = LaneShell::spawn(home.path());
    plant_pane(&d, "owner", owner.pid());
    plant_self(&d); // the foreign observer
    let g = owner.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "build", "pid": owner.pid(), "request_id": "r1"}),
    );
    assert_eq!(g["result"]["granted"], true, "{g}");
    let token = g["result"]["token"].as_str().unwrap().to_string();
    // The owner's own status reveals its token — via the real CLI
    // too: the cadence child derives this lane from its ancestry.
    let s = owner.rpc(&d.state, "slot_status", json!({}));
    let held = s["result"]["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held[0]["token"], token, "owner sees its own token");
    let (rc, out) = owner.cadence(&d.state, "build-slot status --json");
    assert_eq!(rc, 0, "{out}");
    let cli: Value = serde_json::from_str(&out).unwrap();
    assert_eq!(
        cli["pools"]["build"]["held"][0]["token"], token,
        "owner CLI sees its own token"
    );
    // The foreign lane's status sees the hold but not the token —
    // even naming the owner's lane in the request.
    let s = d.rpc("slot_status", json!({"lane": "owner"})).unwrap();
    let held = s["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held.len(), 1);
    assert!(
        held[0].get("token").is_none(),
        "foreign caller must not see the token: {held:?}"
    );
    assert_eq!(held[0]["lane"], "owner");
}

/// ACCEPTANCE: a `slot_acquire` whose claimed `pid` is not the socket
/// peer or one of its /proc ancestors is refused — the daemon never
/// rebinds it (CAD-113 identity fork, option A).
#[test]
fn slot_acquire_refuses_a_pid_off_the_caller_chain() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut lane = LaneShell::spawn(home.path());
    plant_pane(&d, "dev-1", lane.pid());
    // A sibling lane's pid is live but off this caller's ancestry.
    let other = LaneShell::spawn(home.path());
    let r = lane.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "build", "pid": other.pid(), "request_id": "r1"}),
    );
    assert_eq!(r["ok"], false, "{r}");
    assert!(
        r["error"]["message"]
            .as_str()
            .unwrap()
            .contains("cannot claim"),
        "{r}"
    );
    // Nothing queued or held under either identity.
    plant_self(&d);
    let s = d.rpc("slot_status", json!({})).unwrap();
    assert!(s["waiting"].as_array().unwrap().is_empty());
    assert!(s["pools"]["build"]["held"].as_array().unwrap().is_empty());
    // An honest claim — the caller's own pid — grants normally.
    let g = lane.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "build", "pid": lane.pid(), "request_id": "r2"}),
    );
    assert_eq!(g["result"]["granted"], true, "{g}");
}

/// ACCEPTANCE: a caller detached from every registered pane derives
/// no identity at all — all three slot RPCs refuse it, and nothing is
/// stamped `operator` (the PR-#71 fail-open pattern, closed here).
#[test]
fn slot_rpc_refuses_an_underivable_caller() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    // `stray` descends from the test process but nothing in its
    // ancestry is a registered pty pane — no pane is planted for it.
    let mut stray = LaneShell::spawn(home.path());
    // `observer` is a real lane so we can inspect the pools afterward.
    let mut observer = LaneShell::spawn(home.path());
    plant_pane(&d, "observer", observer.pid());
    for (method, params) in [
        (
            "slot_acquire",
            json!({"kind": "build", "pid": stray.pid(), "request_id": "r1"}),
        ),
        (
            "slot_release",
            json!({"token": "slot-x", "pid": stray.pid()}),
        ),
        ("slot_status", json!({})),
    ] {
        let r = stray.rpc(&d.state, method, params);
        assert_eq!(r["ok"], false, "{method}: {r}");
        assert!(
            r["error"]["message"]
                .as_str()
                .unwrap()
                .contains("caller identity underivable"),
            "{method} must refuse identity-less callers: {r}"
        );
    }
    // Nothing was recorded — and especially not as `operator`.
    let s = observer.rpc(&d.state, "slot_status", json!({}));
    assert_eq!(s["ok"], true, "{s}");
    assert!(s["result"]["waiting"].as_array().unwrap().is_empty());
    assert!(s["result"]["pools"]["build"]["held"]
        .as_array()
        .unwrap()
        .is_empty());
    assert!(
        !s["result"].to_string().contains("operator"),
        "no operator identity may appear: {}",
        s["result"]
    );
}

/// BLOCKER (r3): `slot_acquired` rides the victim's event stream —
/// readable by any local caller via `agent_events`. It must never
/// carry the token: token+lane+pid are the entire release credential,
/// so a peer's stream can never be mined for one. (r5: the victim is
/// a real second connection identity — a lane shell.)
#[test]
fn slot_acquired_event_cannot_release_a_peers_hold() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut victim = LaneShell::spawn(home.path());
    plant_pane(&d, "victim", victim.pid());
    plant_self(&d); // the snoop: every d.rpc runs as SELF_LANE
    let g = victim.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "build", "pid": victim.pid(), "request_id": "r1"}),
    );
    assert_eq!(g["ok"], true, "{g}");
    let token = g["result"]["token"].as_str().unwrap().to_string();
    // The peer reads the victim's stream — sees the acquisition…
    let ev = d
        .events("victim")
        .into_iter()
        .find(|e| e["kind"].as_str() == Some("slot_acquired"))
        .expect("victim emitted slot_acquired");
    assert!(
        ev["payload"].get("token").is_none() && !ev["payload"].to_string().contains(&token),
        "slot_acquired leaks the release credential: {}",
        ev["payload"]
    );
    // …but the visible fields can't release anything: a guessed token
    // is an unknown-token rejection and the hold survives.
    let err = d
        .rpc(
            "slot_release",
            json!({"token": "slot-guess", "pid": std::process::id()}),
        )
        .unwrap_err();
    assert!(err.to_string().contains("Unknown slot token"), "{err}");
    // Even the real token under a foreign identity is refused — the
    // derived lane (pane-self) is not the hold's lane, whatever the
    // request's `lane` field claims.
    let err = d
        .rpc(
            "slot_release",
            json!({"token": token, "lane": "victim", "pid": std::process::id()}),
        )
        .unwrap_err();
    assert!(err.to_string().contains("another caller"), "{err}");
    // And status passing the victim's lane still shows no token.
    let s = d.rpc("slot_status", json!({"lane": "victim"})).unwrap();
    let held = s["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held.len(), 1);
    assert!(held[0].get("token").is_none(), "foreign token hidden");
    // The owner releases normally under its own connection identity.
    let r = victim.rpc(
        &d.state,
        "slot_release",
        json!({"token": token, "pid": victim.pid()}),
    );
    assert_eq!(r["ok"], true, "{r}");
}

/// BLOCKER: holds survive a daemon restart — persisted slots.json is
/// revalidated at boot: live holders keep their slots (never
/// re-granted), dead holders are dropped with a named reason.
#[test]
fn slot_restart_revalidates_holders() {
    let state = TempDir::new().unwrap();
    let home = TempDir::new().unwrap();
    let d = TestDaemon::start_on_opts(state.path().to_path_buf(), slot_opts(2, 1, 900, &[]));
    // Two holds: one bound to a lane shell that dies before the
    // restart, one bound to the test process which outlives it.
    let mut doomed = LaneShell::spawn(home.path());
    plant_pane(&d, "dev-1", doomed.pid());
    let g = doomed.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "build", "pid": doomed.pid(), "request_id": "r0"}),
    );
    assert_eq!(g["ok"], true, "{g}");
    plant_self(&d);
    let live = slot_acquire(&d, "build", SELF_LANE, "r1");
    assert_eq!(live["granted"], true);
    let live_tok = live["token"].as_str().unwrap().to_string();
    let live_pid = std::process::id();
    doomed.child.kill().unwrap();
    doomed.child.wait().unwrap();
    drop(d); // shutdown → serve returns → state dir kept
    let d2 = TestDaemon::start_on_opts(state.path().to_path_buf(), slot_opts(2, 1, 900, &[]));
    // The agent rows persisted but a clean shutdown clears endpoint
    // fields — re-stamp the live pane's facts before deriving.
    plant_pane(&d2, SELF_LANE, live_pid);
    // The live hold survived with its token intact; the dead one's
    // slot was reaped — one held, one free.
    let s = d2.rpc("slot_status", json!({})).unwrap();
    let held = s["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held.len(), 1, "one live holder survives: {held:?}");
    assert_eq!(held[0]["token"], live_tok);
    assert_eq!(held[0]["pid"], live_pid);
    // The boot reap named the dead holder's cause on its lane.
    let evs = d2.events("dev-1");
    assert!(
        evs.iter()
            .any(|e| e["kind"].as_str() == Some("slot_released")
                && e["payload"]["reason"].as_str() == Some("holder died")),
        "{evs:?}"
    );
    // And an acquire never re-grants the survivor's slot — one free
    // slot grants once, then the pool is full again.
    let g = slot_acquire(&d2, "build", SELF_LANE, "r9");
    assert_eq!(g["granted"], true);
    let q = slot_acquire(&d2, "build", SELF_LANE, "r10");
    assert_eq!(q["granted"], false, "restarted holds keep the pool bounded");
    // The survivor still releases by its minted token.
    slot_release(&d2, &live_tok, SELF_LANE, live_pid);
}

/// Regression for CI 35542407390: a planted pane row must survive a
/// daemon restart's relaunch sweep untouched. The sweep relaunches
/// every enabled actor-owning row; an actor whose open can't verify
/// the planted pane exit-detaches it — clearing the pid/generation
/// the caller-identity pane map resolves by — or a real open's
/// `set_identity` overwrites it. Either way the next slot call fails
/// closed ("descends from no registered pane"). plant_pane's rows are
/// actorless (`inbox` pair) and `enabled=0`, so the sweep never
/// touches them: the planted facts persist through the whole window.
#[test]
fn slot_planted_pane_row_survives_restart() {
    let state = TempDir::new().unwrap();
    let live_pid = std::process::id();
    let d = TestDaemon::start_on_opts(state.path().to_path_buf(), slot_opts(2, 1, 900, &[]));
    plant_pane(&d, SELF_LANE, live_pid);
    let g = slot_acquire(&d, "build", SELF_LANE, "r1");
    assert_eq!(g["granted"], true, "{g}");
    // Canary in the pre-fix shape — an enabled (fake, pty) row the boot
    // relaunch sweep must launch. Its actor's adapter build fails
    // deterministically and the exit-detach emits `attention`. The alias
    // sorts after every other agent, so once its outcome lands the sweep
    // has spawned an actor for every earlier row.
    let conn = rusqlite::Connection::open(state.path().join("cadence.sqlite3")).unwrap();
    conn.execute(
        "INSERT INTO agents(alias,provider,endpoint_kind,role,cwd,sandbox,
            state,enabled,pid,generation,session_id,created,updated)
         VALUES('zz-canary','fake','pty','worker',?1,'read-only',
            'stopped',1,0,'planted','planted',0,0)",
        [state.path().to_str().unwrap()],
    )
    .unwrap();
    drop(conn);
    drop(d);
    let d2 = TestDaemon::start_on_opts(state.path().to_path_buf(), slot_opts(2, 1, 900, &[]));
    plant_pane(&d2, SELF_LANE, live_pid);
    // Positive window-closed signal (CAD-221): never assert absence
    // inside a window that may not have opened. The canary's `attention`
    // proves the sweep ran and an actor outcome landed on the very path
    // that would destroy a vulnerable planted row — the lane assertion
    // below is made only after that window provably closed.
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    loop {
        if d2
            .events("zz-canary")
            .iter()
            .any(|e| e["kind"].as_str() == Some("attention"))
        {
            break;
        }
        assert!(
            std::time::Instant::now() < deadline,
            "canary never detached — the relaunch sweep did not run: {:?}",
            d2.events("zz-canary")
        );
        std::thread::sleep(std::time::Duration::from_millis(25));
    }
    let conn = rusqlite::Connection::open(state.path().join("cadence.sqlite3")).unwrap();
    let p: i64 = conn
        .query_row("SELECT pid FROM agents WHERE alias=?", [SELF_LANE], |r| {
            r.get(0)
        })
        .unwrap();
    assert_eq!(p as u32, live_pid, "no actor clobbered the plant");
    assert!(
        !d2.events(SELF_LANE)
            .iter()
            .any(|e| e["kind"].as_str() == Some("attention")),
        "no actor should ever have launched: {:?}",
        d2.events(SELF_LANE)
    );
    let g = slot_acquire(&d2, "build", SELF_LANE, "r9");
    assert_eq!(g["granted"], true, "{g}");
}

/// A managed "claude" provider for the CAD-230 enrollment tests. It
/// never answers a turn; it performs slot RPCs on the test's behalf —
/// as itself (the enrolled root), from a child (a verified descendant)
/// or from a double-forked `setsid` grandchild (off the root's
/// ancestry; `detached-bare` also drops `CADENCE_ALIAS`). `exec` runs
/// an argv as a tool subprocess and lands `{rc, out, err}`. Requests
/// arrive as `<cmd_dir>/req-N.json`, answers land as `resp-N.json`; a
/// `"$PID"` pid param means the performing process.
const MOCK_ENROLL_PY: &str = r#"
import json, os, socket, subprocess, sys, threading, time

def rpc(sock_path, frame):
    params = frame.setdefault("params", {})
    if params.get("pid") == "$PID":
        params["pid"] = os.getpid()
    s = socket.socket(socket.AF_UNIX)
    s.connect(sock_path)
    s.sendall((json.dumps(frame) + "\n").encode())
    line = s.makefile().readline()
    s.close()
    return json.loads(line)

def land(path, value):
    with open(path + ".tmp", "w") as f:
        json.dump(value, f)
    os.rename(path + ".tmp", path)

def off_lineage(pid):
    p = os.getpid()
    while p > 1:
        if p == pid:
            return False
        with open("/proc/%d/status" % p) as f:
            p = int([l for l in f if l.startswith("PPid:")][0].split()[1])
    return True

if sys.argv[1] == "--child":
    sock_path, frame, out = sys.argv[2:5]
    land(out, rpc(sock_path, json.loads(frame)))
    sys.exit(0)

if sys.argv[1] == "--detached":
    sock_path, frame, out, root = sys.argv[2:6]
    if os.fork() > 0:
        os.wait()
        sys.exit(0)
    os.setsid()
    if os.fork() > 0:
        os._exit(0)
    while not off_lineage(int(root)):
        time.sleep(0.02)
    land(out, rpc(sock_path, json.loads(frame)))
    os._exit(0)

pidfile, sock_path, cmd_dir = sys.argv[1:4]
with open(pidfile + ".tmp", "w") as f:
    f.write(str(os.getpid()))
os.rename(pidfile + ".tmp", pidfile)

def serve():
    n = 0
    while True:
        req = os.path.join(cmd_dir, "req-%d.json" % n)
        if not os.path.exists(req):
            time.sleep(0.02)
            continue
        cmd = json.load(open(req))
        out = os.path.join(cmd_dir, "resp-%d.json" % n)
        if cmd["how"] == "exec":
            # A tool subprocess running a real command (CAD-276).
            r = subprocess.run(cmd["argv"], capture_output=True, text=True)
            land(out, {"rc": r.returncode, "out": r.stdout, "err": r.stderr})
            n += 1
            continue
        frame = json.dumps(cmd["frame"])
        me = sys.executable, os.path.abspath(__file__)
        if cmd["how"] == "self":
            land(out, rpc(sock_path, cmd["frame"]))
        elif cmd["how"] == "child":
            # Answer only once the child is reaped: its hold's holder
            # is then provably dead for the next reap pass.
            subprocess.run([*me, "--child", sock_path, frame, out + ".c"], check=True)
            os.rename(out + ".c", out)
        else:
            # `detached-bare`: the detach also scrubs CADENCE_ALIAS.
            env = dict(os.environ)
            if cmd["how"] == "detached-bare":
                env.pop("CADENCE_ALIAS", None)
            subprocess.run([*me, "--detached", sock_path, frame, out,
                            str(os.getpid())], check=True, env=env)
        n += 1

threading.Thread(target=serve, daemon=True).start()
for _ in sys.stdin:
    pass
"#;

/// The managed provider under test and its request channel.
struct ManagedWorker {
    pid: u32,
    cmd_dir: TempDir,
    seq: u64,
    _mock: MockClaude,
}

/// The enrollment mock installed as this test's claude command, not yet
/// registered — [`ManagedWorker::install`] before a `daemon run` process
/// exists (it takes its env at spawn), then [`Self::enroll`].
struct ManagedWorkerMock {
    cmd_dir: TempDir,
    mock: MockClaude,
}

impl ManagedWorker {
    /// Register `alias` as a managed claude endpoint running the
    /// enrollment mock and wait for the daemon to enroll it.
    fn start(d: &TestDaemon, alias: &str) -> ManagedWorker {
        Self::start_role(d, alias, "worker")
    }

    /// [`Self::start`] registering the endpoint with `role`.
    fn start_role(d: &TestDaemon, alias: &str, role: &str) -> ManagedWorker {
        Self::install(d.dir.path(), &d.state, alias).enroll_role(d, alias, role)
    }

    /// Write the enrollment mock into `dir` and install it as the claude
    /// command for a daemon serving `state`.
    fn install(dir: &Path, state: &Path, alias: &str) -> ManagedWorkerMock {
        let cmd_dir = TempDir::new().unwrap();
        let pidfile = dir.join(format!("claude-{alias}.pid"));
        let script = dir.join("claude-enroll.py");
        std::fs::write(&script, MOCK_ENROLL_PY).unwrap();
        test_env().set(
            "CADENCE_CLAUDE_COMMAND",
            format!(
                "python3 {} {} {} {}",
                script.display(),
                pidfile.display(),
                client::socket_path(state).display(),
                cmd_dir.path().display()
            ),
        );
        ManagedWorkerMock {
            cmd_dir,
            mock: MockClaude { pidfile },
        }
    }
}

impl ManagedWorkerMock {
    /// Register `alias` as a managed claude worker and wait for `d` to
    /// enroll the provider it launched.
    fn enroll(self, d: &TestDaemon, alias: &str) -> ManagedWorker {
        self.enroll_role(d, alias, "worker")
    }

    /// [`Self::enroll`] registering the endpoint with `role`.
    fn enroll_role(self, d: &TestDaemon, alias: &str, role: &str) -> ManagedWorker {
        let ManagedWorkerMock { cmd_dir, mock } = self;
        let cwd = d.dir.path().to_str().unwrap().to_string();
        d.fixture_rpc(
            "agent_register",
            json!({"alias": alias, "provider": "claude",
                   "endpoint_kind": "managed", "cwd": cwd, "role": role}),
        )
        .unwrap();
        ManagedWorkerMock { cmd_dir, mock }.enrolled(d, alias)
    }

    /// Wait for `d` to enroll the provider it launched for an `alias`
    /// someone else registered (CAD-339: `master_start`).
    fn enrolled(self, d: &TestDaemon, alias: &str) -> ManagedWorker {
        let ManagedWorkerMock { cmd_dir, mock } = self;
        // The daemon's own record of the provider it launched — the
        // mock may not even have written its pidfile yet.
        let deadline = Instant::now() + Duration::from_secs(20);
        let pid = loop {
            let enrolled = d
                .events(alias)
                .into_iter()
                .find(|e| e["kind"].as_str() == Some("slot_enrolled"));
            if let Some(e) = enrolled {
                break e["payload"]["root_pid"].as_u64().unwrap() as u32;
            }
            assert!(
                Instant::now() < deadline,
                "{alias} was never enrolled: {:?}",
                d.events(alias)
            );
            thread::sleep(Duration::from_millis(25));
        };
        ManagedWorker {
            pid,
            cmd_dir,
            seq: 0,
            _mock: mock,
        }
    }
}

impl ManagedWorker {
    /// One slot RPC performed `how` = `self` | `child` | `detached` |
    /// `detached-bare`; the answer is the wire frame.
    fn rpc(&mut self, how: &str, method: &str, params: Value) -> Value {
        self.request(
            json!({"how": how, "frame": {"method": method, "params": params}}),
            &format!("{how} {method}"),
        )
    }

    /// Run `argv` as the provider's tool subprocess — `{rc, out, err}`.
    fn exec(&mut self, argv: &[&str]) -> Value {
        self.request(
            json!({"how": "exec", "argv": argv}),
            argv.join(" ").as_str(),
        )
    }

    fn request(&mut self, cmd: Value, what: &str) -> Value {
        let n = self.send(cmd);
        self.answer(n, what)
    }

    /// Hand the worker one command without waiting — its number for
    /// [`Self::answer`]. The worker serves commands one at a time.
    fn send(&mut self, cmd: Value) -> u64 {
        let n = self.seq;
        self.seq += 1;
        let req = self.cmd_dir.path().join(format!("req-{n}.json"));
        let tmp = req.with_extension("tmp");
        std::fs::write(&tmp, cmd.to_string()).unwrap();
        std::fs::rename(&tmp, &req).unwrap();
        n
    }

    /// Wait for command `n`'s answer.
    fn answer(&self, n: u64, what: &str) -> Value {
        let resp = self.cmd_dir.path().join(format!("resp-{n}.json"));
        let deadline = Instant::now() + Duration::from_secs(20);
        while !resp.exists() {
            assert!(
                Instant::now() < deadline,
                "managed worker never answered {what}"
            );
            thread::sleep(Duration::from_millis(20));
        }
        serde_json::from_str(&std::fs::read_to_string(&resp).unwrap()).unwrap()
    }
}

/// CAD-381 ACCEPTANCE: memory resolves its caller through the one
/// identity verifier — the daemon's CAD-230 enrollment of a managed
/// provider it launched — so headless endpoints author, review and
/// finalize exactly like panes. A proposal by one managed endpoint is
/// reviewed by two others and finalized by a managed pm to `accepted`;
/// the author still cannot review its own proposal; a spoofed identity
/// param is refused; the test process and a managed tool's detached
/// grandchild have no agent identity (never the endpoint's); and an
/// owner-generation drift revokes the enrollment for
/// good — restoring the generation does not revive it.
#[test]
fn memory_managed_endpoints_authenticate_through_daemon_enrollment() {
    let tmp = TempDir::new().unwrap();
    let pm_dir = tmp.path().join("pm");
    let pm = cadence_agent::issue::Pm::init(&pm_dir).unwrap();
    std::fs::create_dir_all(pm_dir.join("demo")).unwrap();
    std::fs::write(
        pm_dir.join("demo/project.yaml"),
        "key: demo\nprefix: D\ncomponents: []\n",
    )
    .unwrap();
    pm.commit(
        &[pm_dir.join("demo/project.yaml")],
        "project fixture\n\nActor: test\n",
    )
    .unwrap();
    test_env().set("CADENCE_PM_DIR", pm_dir.to_str().unwrap());
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    let mut author = ManagedWorker::start(&d, "author");
    let mut reviewer_a = ManagedWorker::start(&d, "reviewer-a");
    let mut reviewer_b = ManagedWorker::start(&d, "reviewer-b");
    let mut lead = ManagedWorker::start_role(&d, "lead", "pm");
    for alias in ["author", "reviewer-a", "reviewer-b", "lead"] {
        d.wait_agent(alias, "idle", 25);
    }
    let ok = |r: Value, what: &str| -> Value {
        assert_eq!(r["ok"], true, "{what}: {r}");
        r["result"].clone()
    };
    let refused = |r: &Value, needle: &str, what: &str| {
        assert_eq!(r["ok"], false, "{what}: {r}");
        let msg = r["error"]["message"].as_str().unwrap_or_default();
        assert!(msg.contains(needle), "{what}: want '{needle}' in {r}");
    };
    let memory_path = pm_dir.join("demo/memory/managed-rule.md");
    let read_memory = || std::fs::read(&memory_path).unwrap();

    let proposal = json!({
        "project": "demo",
        "kind": "rule",
        "scope": {"project": true},
        "source": "CAD-381",
        "confidence": "high",
        "text": "\nmanaged endpoints carry daemon-minted identity\n\n**Why:** the enrollment is the authority.\n\n**How to apply:** trust only the daemon's record.\n",
        "id": "managed-rule"
    });
    // A self-asserted identity is refused before any PM write, even
    // from a genuinely enrolled endpoint.
    let r = author.rpc(
        "self",
        "memory_propose",
        json!({"alias": "lead", "inner": proposal.clone()}),
    );
    refused(&r, "connection-bound", "spoofed alias");
    assert!(!memory_path.exists());

    // The provider's tool subprocess (a verified descendant) proposes
    // as the endpoint.
    let proposed = ok(
        author.rpc("child", "memory_propose", proposal.clone()),
        "managed propose",
    );
    assert_eq!(proposed["status"], "proposed", "{proposed}");
    let digest = proposed["digest"].as_str().unwrap().to_string();
    let review = |verdict_evidence: &str| {
        json!({
            "slug": "managed-rule",
            "project": "demo",
            "operation": "accept",
            "verdict": "pass",
            "evidence": verdict_evidence,
            "digest": digest,
        })
    };

    let before = read_memory();
    let r = author.rpc("self", "memory_review", review("self review"));
    refused(&r, "author cannot review", "author reviews own proposal");
    assert_eq!(before, read_memory());

    // Spoofed reviewer identity from a real endpoint: refused.
    let mut spoof = review("spoofed reviewer");
    spoof["reviewer"] = json!("reviewer-b");
    let r = reviewer_a.rpc("self", "memory_review", spoof);
    refused(&r, "connection-bound", "spoofed reviewer");

    // No agent identity: the test process itself, and a managed tool's
    // setsid double-forked grandchild (off the provider's ancestry).
    let err = d
        .rpc("memory_review", review("outside every agent tree"))
        .unwrap_err();
    assert!(err.to_string().contains("has no agent identity"), "{err}");
    let r = reviewer_a.rpc("detached", "memory_review", review("detached"));
    refused(&r, "has no agent identity", "detached grandchild");
    assert_eq!(before, read_memory());

    let a = ok(
        reviewer_a.rpc("self", "memory_review", review("reviewer A checked it")),
        "reviewer A",
    );
    assert_eq!(a["quorum"]["eligible"], false, "{a}");
    let b = ok(
        reviewer_b.rpc("child", "memory_review", review("reviewer B checked it")),
        "reviewer B",
    );
    assert_eq!(b["quorum"]["eligible"], true, "{b}");
    let finalized = ok(
        lead.rpc(
            "self",
            "memory_finalize",
            json!({"slug": "managed-rule", "project": "demo",
                   "operation": "accept", "digest": digest}),
        ),
        "managed pm finalize",
    );
    assert_eq!(finalized["status"], "accepted", "{finalized}");

    let pm = cadence_agent::issue::Pm::at(&pm_dir).unwrap();
    let (_, accepted) = memory::find(&pm, Some("demo"), "managed-rule").unwrap();
    assert!(memory::retrieval_status(&accepted).0);
    let author_proof = accepted.front.author_proof.clone().unwrap();
    assert_eq!(author_proof.alias, "author");
    let agent = d.rpc("agent_show", json!({"alias": "author"})).unwrap()["agent"].clone();
    assert!(
        author_proof
            .generation
            .ends_with(&format!(":{}", author.pid)),
        "the proof carries the enrolled owner generation: {author_proof:?} {agent}"
    );
    assert_eq!(
        accepted
            .front
            .reviews
            .iter()
            .map(|r| r.reviewer.as_str())
            .collect::<Vec<_>>(),
        vec!["reviewer-a", "reviewer-b"]
    );
    assert_eq!(accepted.front.finalizations[0].finalizer.alias, "lead");

    // Owner generation drift revokes the author's enrollment: the old
    // enrollment no longer authenticates — and never falls through to
    // "no agent identity" — even once the row's generation is restored.
    let original = agent["generation"].as_str().map(str::to_string);
    let conn = rusqlite::Connection::open(d.state.join("cadence.sqlite3")).unwrap();
    conn.execute(
        "UPDATE agents SET generation='regenerated' WHERE alias='author'",
        [],
    )
    .unwrap();
    let second = json!({
        "project": "demo",
        "kind": "gotcha",
        "scope": {"project": true},
        "source": "CAD-381",
        "confidence": "low",
        "text": "stale enrollments vouch for no one\n\n**Why:** drift revokes.\n\n**How to apply:** reopen the endpoint.\n",
        "id": "stale-rule"
    });
    let r = author.rpc("self", "memory_propose", second.clone());
    refused(&r, "is revoked", "drifted enrollment");
    conn.execute(
        "UPDATE agents SET generation=?1 WHERE alias='author'",
        [original],
    )
    .unwrap();
    drop(conn);
    let r = author.rpc("child", "memory_propose", second);
    refused(&r, "is revoked", "revoked enrollment after restore");
    assert!(!pm_dir.join("demo/memory/stale-rule.md").exists());
}

/// CAD-381 review: a managed endpoint's identity outlives the build-slot
/// TTL (an `expired` enrollment still vouches — renewal is only at the
/// next open); and the ambiguous branches fail closed — two agent endpoints on one
/// ancestry, and one pid that is both a pane and an enrolled root.
#[test]
fn memory_managed_identity_survives_ttl_and_refuses_ambiguity() {
    let tmp = TempDir::new().unwrap();
    let pm_dir = tmp.path().join("pm");
    let pm = cadence_agent::issue::Pm::init(&pm_dir).unwrap();
    std::fs::create_dir_all(pm_dir.join("demo")).unwrap();
    std::fs::write(
        pm_dir.join("demo/project.yaml"),
        "key: demo\nprefix: D\ncomponents: []\n",
    )
    .unwrap();
    pm.commit(
        &[pm_dir.join("demo/project.yaml")],
        "project fixture\n\nActor: test\n",
    )
    .unwrap();
    test_env().set("CADENCE_PM_DIR", pm_dir.to_str().unwrap());
    let clock = std::sync::Arc::new(std::sync::atomic::AtomicU64::new(1_000));
    let d = TestDaemon::start_opts(slot_opts_clock(
        2,
        1,
        900,
        &[],
        Some(std::sync::Arc::clone(&clock)),
    ));
    let mut wk = ManagedWorker::start(&d, "wk");
    let mut twin = ManagedWorker::start(&d, "twin");
    for alias in ["wk", "twin"] {
        d.wait_agent(alias, "idle", 25);
    }
    let proposal = |id: &str| {
        json!({
            "project": "demo",
            "kind": "rule",
            "scope": {"project": true},
            "source": "CAD-381",
            "confidence": "high",
            "text": "identity is not a build lease\n\n**Why:** the TTL caps slots.\n\n**How to apply:** revalidate per call.\n",
            "id": id
        })
    };
    let refused = |r: &Value, needle: &str, what: &str| {
        assert_eq!(r["ok"], false, "{what}: {r}");
        let msg = r["error"]["message"].as_str().unwrap_or_default();
        assert!(msg.contains(needle), "{what}: want '{needle}' in {r}");
    };

    // Past the enrollment TTL: no new build work, identity intact.
    clock.store(
        1_000 + cadence_agent::slots::ENROLLMENT_TTL_SECS as u64 + 1,
        std::sync::atomic::Ordering::Relaxed,
    );
    let s = wk.rpc("self", "slot_status", json!({}));
    let mine = s["result"]["enrollments"]
        .as_array()
        .unwrap()
        .iter()
        .find(|e| e["owner_actor"] == "wk")
        .cloned()
        .unwrap();
    assert_eq!(mine["auth_state"], "expired", "{s}");
    // A freshly enrolled (active) endpoint alongside the expired one:
    // revalidation must still read the expired owner's row, not treat
    // it as gone (review round 3).
    let mut fresh = ManagedWorker::start(&d, "fresh");
    d.wait_agent("fresh", "idle", 25);
    let r = wk.rpc("child", "memory_propose", proposal("after-ttl"));
    assert_eq!(r["ok"], true, "expired enrollment still vouches: {r}");
    assert_eq!(r["result"]["status"], "proposed", "{r}");
    let r = fresh.rpc("self", "memory_propose", proposal("fresh-rule"));
    assert_eq!(r["ok"], true, "active enrollment vouches: {r}");

    // Real drift of the expired owner's row still revokes it.
    let conn = rusqlite::Connection::open(d.state.join("cadence.sqlite3")).unwrap();
    conn.execute(
        "UPDATE agents SET generation='regenerated' WHERE alias='wk'",
        [],
    )
    .unwrap();
    drop(conn);
    let r = wk.rpc("child", "memory_propose", proposal("drifted-rule"));
    refused(&r, "is revoked", "drifted expired owner");

    // One pid both a registered pane and an enrolled root: ambiguous.
    plant_pane(&d, "twin-pane", twin.pid);
    let r = twin.rpc("self", "memory_propose", proposal("twin-rule"));
    refused(
        &r,
        "both a registered pane and an enrolled endpoint",
        "pane==root",
    );

    // Two agent endpoints on one ancestry (the test process planted as
    // a pane above the provider): ambiguous, never nearest-wins.
    plant_self(&d);
    let r = fresh.rpc("self", "memory_propose", proposal("nested-rule"));
    refused(&r, "caller identity ambiguous", "nested endpoints");
    for id in ["drifted-rule", "twin-rule", "nested-rule"] {
        assert!(!pm_dir.join(format!("demo/memory/{id}.md")).exists());
    }
}

/// CAD-230 phase a ACCEPTANCE: the daemon enrolls a managed provider
/// it launched (no tmux pane) from the pid it recorded. A build-slot
/// acquire from that exact process, and from a verified descendant
/// (its tool subprocess), is admitted under the owner's lane whatever
/// the request claims; a double-forked detached grandchild, a pane-less
/// unrelated process and a forged alias/lane/pid are refused. Owner
/// generation drift then revokes: no new work — and no fallback to an
/// outer pane even with one registered above it — while the live hold
/// stays accounted until its exact holder releases it.
#[test]
fn slot_managed_endpoint_enrolls_and_admits_only_its_verified_processes() {
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut observer = LaneShell::spawn(home.path());
    plant_pane(&d, "observer", observer.pid());
    let mut wk = ManagedWorker::start(&d, "wk");
    let status = |observer: &mut LaneShell| {
        let s = observer.rpc(&d.state, "slot_status", json!({}));
        assert_eq!(s["ok"], true, "{s}");
        s["result"].clone()
    };
    let enrollment = status(&mut observer)["enrollments"][0].clone();
    assert_eq!(enrollment["owner_actor"], "wk");
    assert_eq!(enrollment["auth_state"], "active");
    assert_eq!(enrollment["root"]["pid"], wk.pid);
    assert_eq!(enrollment["root"], enrollment["worker"]);

    // The enrolled root itself — a forged lane in the request changes
    // nothing: the hold is the owner's.
    let g = wk.rpc(
        "self",
        "slot_acquire",
        json!({"kind": "build", "pid": "$PID", "request_id": "root-1",
               "lane": "observer"}),
    );
    assert_eq!(g["result"]["granted"], true, "{g}");
    let root_token = g["result"]["token"].as_str().unwrap().to_string();
    // A verified descendant (the provider's tool subprocess) is
    // admitted too, holding for its own pid; it exits right after, so
    // its hold is the next reap's proven death.
    let g = wk.rpc(
        "child",
        "slot_acquire",
        json!({"kind": "suite", "pid": "$PID", "request_id": "child-1"}),
    );
    assert_eq!(g["result"]["granted"], true, "{g}");
    let s = status(&mut observer);
    let held = s["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held.len(), 1, "{s}");
    assert_eq!(held[0]["lane"], "wk");
    assert_eq!(held[0]["pid"], wk.pid);
    assert_eq!(held[0]["binding"], "strict");
    assert_eq!(held[0]["auth_state"], "active");
    assert_eq!(held[0]["liveness"], "alive");
    assert_eq!(held[0]["accounting"], "held");
    assert_eq!(held[0]["owner_generation"], enrollment["owner_generation"]);
    assert!(held[0].get("token").is_none(), "the observer never sees it");
    assert!(
        s["pools"]["suite"]["held"].as_array().unwrap().is_empty(),
        "the exited descendant's hold was reaped: {s}"
    );
    assert!(d
        .events("wk")
        .iter()
        .any(|e| e["kind"] == "slot_released" && e["payload"]["reason"] == "holder died"));

    // Off the root's ancestry (setsid + double fork): refused.
    let r = wk.rpc(
        "detached",
        "slot_acquire",
        json!({"kind": "build", "pid": "$PID", "request_id": "detached-1"}),
    );
    assert_eq!(r["ok"], false, "{r}");
    assert!(
        r["error"]["message"]
            .as_str()
            .unwrap()
            .contains("caller identity underivable"),
        "{r}"
    );
    // A pane-less unrelated process claiming the alias, the lane and
    // even the root's pid: refused.
    let mut stray = LaneShell::spawn(home.path());
    let r = stray.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "build", "pid": wk.pid, "request_id": "forged-1",
               "lane": "wk", "alias": "wk"}),
    );
    assert_eq!(r["ok"], false, "{r}");
    let (rc, out) = stray.cadence(
        &d.state,
        "build-slot acquire build --pid $$ --lane wk --wait-secs 0",
    );
    assert_ne!(rc, 0, "{out}");
    assert!(out.contains("caller identity underivable"), "{out}");
    let r = stray.run(&format!(
        "CADENCE_ALIAS=wk {} --state-dir {} build-slot status",
        env!("CARGO_BIN_EXE_cadence"),
        d.state.display()
    ));
    assert_ne!(r.0, 0, "an env alias is no identity: {}", r.1);
    assert_eq!(
        status(&mut observer)["pools"]["build"]["held"]
            .as_array()
            .unwrap()
            .len(),
        1,
        "no refused caller got a hold"
    );

    // Owner generation drift: plant the test process as a pane ABOVE
    // the provider first — the strict path must not fall through to it.
    plant_self(&d);
    let conn = rusqlite::Connection::open(d.state.join("cadence.sqlite3")).unwrap();
    conn.execute(
        "UPDATE agents SET generation='drifted' WHERE alias='wk'",
        [],
    )
    .unwrap();
    drop(conn);
    let r = wk.rpc(
        "self",
        "slot_acquire",
        json!({"kind": "build", "pid": "$PID", "request_id": "root-2"}),
    );
    assert_eq!(r["ok"], false, "{r}");
    assert!(
        r["error"]["message"].as_str().unwrap().contains("revoked"),
        "{r}"
    );
    let s = status(&mut observer);
    let held = s["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held.len(), 1, "revocation frees nothing: {s}");
    assert_eq!(held[0]["auth_state"], "revoked");
    assert_eq!(held[0]["liveness"], "alive");
    // Only the exact holder's release frees it.
    let r = wk.rpc(
        "self",
        "slot_release",
        json!({"token": root_token, "pid": "$PID"}),
    );
    assert_eq!(r["result"]["released"], true, "{r}");
    assert!(status(&mut observer)["pools"]["build"]["held"]
        .as_array()
        .unwrap()
        .is_empty());
}

/// CAD-230 review BLOCKING #1: once a managed endpoint's enrollment is
/// revoked, its provider must never fall through to a pane registered
/// ABOVE it — not when it held nothing at the drift, and not after it
/// released its last hold. Each acquire is refused and no hold of any
/// binding (legacy included) appears.
#[test]
fn slot_revoked_managed_endpoint_never_falls_back_to_an_outer_pane() {
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut observer = LaneShell::spawn(home.path());
    plant_pane(&d, "observer", observer.pid());
    let mut wk = ManagedWorker::start(&d, "wk");
    // The outer pane: the test process, an ancestor of the provider.
    plant_self(&d);
    let held = |observer: &mut LaneShell| {
        let s = observer.rpc(&d.state, "slot_status", json!({}));
        assert_eq!(s["ok"], true, "{s}");
        let mut all = s["result"]["pools"]["build"]["held"]
            .as_array()
            .unwrap()
            .clone();
        all.extend(
            s["result"]["pools"]["suite"]["held"]
                .as_array()
                .unwrap()
                .clone(),
        );
        all
    };
    let drift = |generation: &str| {
        let conn = rusqlite::Connection::open(d.state.join("cadence.sqlite3")).unwrap();
        conn.execute(
            "UPDATE agents SET generation=?1 WHERE alias='wk'",
            [generation],
        )
        .unwrap();
    };
    let refused = |r: &Value, route: &str| {
        assert_eq!(r["ok"], false, "{route}: {r}");
        assert!(
            r["error"]["message"].as_str().unwrap().contains("revoked"),
            "{route}: {r}"
        );
    };

    // Route: drift while holding NOTHING — twice, as the reviewer did.
    drift("drift-1");
    for req in ["a1", "a2"] {
        let r = wk.rpc(
            "self",
            "slot_acquire",
            json!({"kind": "build", "pid": "$PID", "request_id": req}),
        );
        refused(&r, "no-hold drift");
    }
    assert!(held(&mut observer).is_empty(), "no legacy hold appeared");

    // Route: release of the last hold after revocation. A fresh
    // enrollment needs a reopen; take a new endpoint for the same
    // provider mock under another alias.
    let mut wk2 = ManagedWorker::start(&d, "wk2");
    let g = wk2.rpc(
        "self",
        "slot_acquire",
        json!({"kind": "build", "pid": "$PID", "request_id": "b1"}),
    );
    assert_eq!(g["result"]["granted"], true, "{g}");
    let token = g["result"]["token"].as_str().unwrap().to_string();
    let conn = rusqlite::Connection::open(d.state.join("cadence.sqlite3")).unwrap();
    conn.execute(
        "UPDATE agents SET generation='drift-2' WHERE alias='wk2'",
        [],
    )
    .unwrap();
    drop(conn);
    let r = wk2.rpc(
        "self",
        "slot_release",
        json!({"token": token, "pid": "$PID"}),
    );
    assert_eq!(r["result"]["released"], true, "{r}");
    for req in ["b2", "b3"] {
        let r = wk2.rpc(
            "self",
            "slot_acquire",
            json!({"kind": "build", "pid": "$PID", "request_id": req}),
        );
        refused(&r, "last-hold release");
    }
    assert!(held(&mut observer).is_empty(), "no legacy hold appeared");
    // The revoked endpoints are still listed — the tombstones that
    // keep the outer pane out.
    let s = observer.rpc(&d.state, "slot_status", json!({}));
    let revoked = s["result"]["enrollments"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|e| e["auth_state"] == "revoked")
        .count();
    assert_eq!(revoked, 2, "{s}");
}

/// CAD-230: `slot_reconcile` is operator authority — an agent's
/// connection (a pane or an enrolled endpoint) is refused, as are
/// identity-shaped request fields; and it never frees a live hold.
#[test]
fn slot_reconcile_refuses_agents_and_live_holds() {
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut pane = LaneShell::spawn(home.path());
    plant_pane(&d, "pane-1", pane.pid());
    let mut wk = ManagedWorker::start(&d, "wk");
    let g = wk.rpc(
        "self",
        "slot_acquire",
        json!({"kind": "build", "pid": "$PID", "request_id": "r1"}),
    );
    let token = g["result"]["token"].as_str().unwrap().to_string();
    let s = pane.rpc(&d.state, "slot_status", json!({}));
    let hold = s["result"]["pools"]["build"]["held"][0].clone();
    let enrollment = hold["enrollment_id"].as_str().unwrap().to_string();
    let start = s["result"]["enrollments"][0]["root"]["starttime"].clone();
    let evidence = json!({
        "owner_generation": hold["owner_generation"], "pid": wk.pid,
        "starttime": start, "uid": s["result"]["enrollments"][0]["root"]["uid"],
        "observed_at": "now", "process_read": "claimed exited",
        "command_outcome": "done", "side_effect_review": "none",
    });
    let params = json!({"enrollment_id": enrollment, "token": token,
                        "evidence": evidence});
    // A pane and the enrolled endpoint itself are agents.
    let r = pane.rpc(&d.state, "slot_reconcile", params.clone());
    assert!(
        r["error"]["message"]
            .as_str()
            .unwrap()
            .contains("operator action"),
        "{r}"
    );
    let r = wk.rpc("self", "slot_reconcile", params.clone());
    assert!(
        r["error"]["message"]
            .as_str()
            .unwrap()
            .contains("operator action"),
        "{r}"
    );
    // The operator (`operator_rpc`: no pane, no enrollment, no agent
    // ancestry) with a forged `by` is refused before anything else…
    let mut forged = params.clone();
    forged["by"] = json!("operator");
    let err = d.operator_rpc("slot_reconcile", forged).unwrap_err();
    assert!(err.to_string().contains("'by'"), "{err}");
    // …and without it still cannot free a live holder.
    let err = d.operator_rpc("slot_reconcile", params).unwrap_err();
    assert!(err.to_string().contains("is alive"), "{err}");
    let s = pane.rpc(&d.state, "slot_status", json!({}));
    assert_eq!(
        s["result"]["pools"]["build"]["held"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
}

/// CAD-276 item 1: `slot_reconcile` is the operator's only on POSITIVE
/// proof — deriving no slot identity is not enough. A `setsid` +
/// double-fork detach off a managed tool and off a registered pane
/// derives no slot identity at all, yet is refused: with
/// `CADENCE_ALIAS` still in its environment by the alias, and with the
/// alias scrubbed by its orphaned session (the session leader exited).
/// The harness's operator caller (`operator_rpc`: no pane, no endpoint,
/// no alias on its ancestry) passes the gate and meets the live-hold rule.
#[test]
fn slot_reconcile_refuses_detached_agent_processes() {
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut pane = LaneShell::spawn(home.path());
    plant_pane(&d, "pane-1", pane.pid());
    let mut wk = ManagedWorker::start(&d, "wk");
    let g = wk.rpc(
        "self",
        "slot_acquire",
        json!({"kind": "build", "pid": "$PID", "request_id": "r1"}),
    );
    let token = g["result"]["token"].as_str().unwrap().to_string();
    let s = pane.rpc(&d.state, "slot_status", json!({}));
    let hold = s["result"]["pools"]["build"]["held"][0].clone();
    let root = s["result"]["enrollments"][0]["root"].clone();
    let params = json!({
        "enrollment_id": hold["enrollment_id"], "token": token,
        "evidence": {
            "owner_generation": hold["owner_generation"], "pid": root["pid"],
            "starttime": root["starttime"], "uid": root["uid"],
            "observed_at": "now", "process_read": "claimed exited",
            "command_outcome": "done", "side_effect_review": "none",
        },
    });
    let refused = |r: &Value, route: &str, why: &str| {
        assert_eq!(r["ok"], false, "{route}: {r}");
        let msg = r["error"]["message"].as_str().unwrap_or_default();
        assert!(msg.contains("not provably the operator"), "{route}: {r}");
        assert!(msg.contains(why), "{route}: wanted '{why}': {r}");
    };

    // Off a managed tool: the provider's env carries CADENCE_ALIAS.
    let r = wk.rpc("detached", "slot_reconcile", params.clone());
    refused(&r, "managed detach", "CADENCE_ALIAS");
    let r = wk.rpc("detached-bare", "slot_reconcile", params.clone());
    refused(&r, "managed detach, alias scrubbed", "session leader");

    // Off a registered pane — the same double fork, run from the pane.
    let script = d.dir.path().join("claude-enroll.py");
    let frame = json!({"method": "slot_reconcile", "params": params}).to_string();
    assert!(
        !frame.contains('\''),
        "the frame rides a single-quoted argv"
    );
    let outs = TempDir::new().unwrap();
    for (i, (env, why)) in [
        ("CADENCE_ALIAS=pane-1", "CADENCE_ALIAS"),
        ("env -u CADENCE_ALIAS", "session leader"),
    ]
    .into_iter()
    .enumerate()
    {
        let out = outs.path().join(format!("pane-{i}.json"));
        let (rc, text) = pane.run(&format!(
            "{env} python3 {} --detached {} '{frame}' {} {}",
            script.display(),
            client::socket_path(&d.state).display(),
            out.display(),
            pane.pid()
        ));
        assert_eq!(rc, 0, "{text}");
        let deadline = Instant::now() + Duration::from_secs(20);
        while !out.exists() {
            assert!(Instant::now() < deadline, "pane detach {i} never answered");
            thread::sleep(Duration::from_millis(20));
        }
        let r: Value = serde_json::from_str(&std::fs::read_to_string(&out).unwrap()).unwrap();
        refused(&r, &format!("pane detach ({env})"), why);
    }

    // The operator passes the gate; the live holder is still refused.
    let err = d.operator_rpc("slot_reconcile", params).unwrap_err();
    assert!(err.to_string().contains("is alive"), "{err}");
    let s = pane.rpc(&d.state, "slot_status", json!({}));
    assert_eq!(
        s["result"]["pools"]["build"]["held"]
            .as_array()
            .unwrap()
            .len(),
        1,
        "no refused caller freed anything: {s}"
    );
}

/// CAD-276 item 4, end to end through the CLI a managed tool runs: a
/// manual `acquire --pid <provider root>` from the provider's tool
/// subprocess is refused (the root outlives the work), while
/// `build-slot run` — which binds its own pid and execs the command —
/// is granted, and the hold dies with the command.
#[test]
fn slot_managed_tool_cannot_bind_the_provider_root() {
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut observer = LaneShell::spawn(home.path());
    plant_pane(&d, "observer", observer.pid());
    let mut wk = ManagedWorker::start(&d, "wk");
    let cadence = env!("CARGO_BIN_EXE_cadence");
    let state = d.state.to_str().unwrap().to_string();
    let root = wk.pid.to_string();
    let r = wk.exec(&[
        cadence,
        "--state-dir",
        &state,
        "build-slot",
        "acquire",
        "build",
        "--pid",
        &root,
        "--wait-secs",
        "0",
    ]);
    assert_ne!(r["rc"], 0, "{r}");
    assert!(
        r["err"]
            .as_str()
            .unwrap()
            .contains("enrolled provider root"),
        "{r}"
    );
    let r = wk.exec(&[
        cadence,
        "--state-dir",
        &state,
        "build-slot",
        "run",
        "build",
        "--wait-secs",
        "10",
        "--",
        "sh",
        "-c",
        "echo token=$CADENCE_BUILD_SLOT_TOKEN pid=$CADENCE_BUILD_SLOT_PID pid_now=$$",
    ]);
    assert_eq!(r["rc"], 0, "{r}");
    let out = r["out"].as_str().unwrap();
    assert!(out.contains("token=slot-"), "{r}");
    // The hold bound the exec'd command's own pid.
    let pid = out.split("pid=").nth(1).unwrap().split_whitespace().next();
    let now = out
        .split("pid_now=")
        .nth(1)
        .unwrap()
        .split_whitespace()
        .next();
    assert_eq!(pid, now, "{r}");
    // The command exited: its hold is the next read's proven death.
    let s = observer.rpc(&d.state, "slot_status", json!({}));
    assert!(
        s["result"]["pools"]["build"]["held"]
            .as_array()
            .unwrap()
            .is_empty(),
        "{s}"
    );
    assert!(d.events("wk").iter().any(|e| e["kind"] == "slot_acquired"));
}

// ---------- CAD-230 phase b: exec-bound run, daemon-launched runners ----------

/// CAD-230 phase b1 ACCEPTANCE: a managed endpoint's `build-slot run`
/// holds a strict, exec-bound slot naming exactly the process it execs
/// into (`$$` of the command IS the recorded holder). While it runs, no
/// other process can release it — a pane agent naming the token and the
/// holder pid, or its own pid, is refused. An exec request claiming an
/// ancestor is refused outright. When the command exits the daemon's
/// own watcher frees the hold — observed on the event stream, with no
/// release call and no slot call from anyone.
#[test]
fn build_slot_run_exec_bound_hold_ends_with_the_command() {
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut observer = LaneShell::spawn(home.path());
    plant_pane(&d, "observer", observer.pid());
    let mut wk = ManagedWorker::start(&d, "wk");
    // `exec` must claim the requesting peer itself, never an ancestor.
    let r = wk.rpc(
        "child",
        "slot_acquire",
        json!({"kind": "build", "pid": wk.pid, "request_id": "anc", "exec": true}),
    );
    assert_eq!(r["ok"], false, "{r}");
    assert!(
        r["error"]["message"]
            .as_str()
            .unwrap()
            .contains("exec-bound"),
        "{r}"
    );
    let work = TempDir::new().unwrap();
    let tok = work.path().join("tok");
    let go = work.path().join("go");
    let script = format!(
        "echo \"$CADENCE_BUILD_SLOT_TOKEN $CADENCE_BUILD_SLOT_PID $$\" > {t}.tmp && \
         mv {t}.tmp {t}; while [ ! -e {g} ]; do sleep 0.05; done; exit 7",
        t = tok.display(),
        g = go.display()
    );
    let n = wk.send(json!({"how": "exec", "argv": [
        env!("CARGO_BIN_EXE_cadence"), "--state-dir", d.state.to_str().unwrap(),
        "build-slot", "run", "build", "--wait-secs", "10", "--", "sh", "-c", script,
    ]}));
    let deadline = Instant::now() + Duration::from_secs(20);
    while !tok.exists() {
        assert!(Instant::now() < deadline, "run never started its command");
        thread::sleep(Duration::from_millis(20));
    }
    let line = std::fs::read_to_string(&tok).unwrap();
    let f: Vec<&str> = line.split_whitespace().collect();
    let (token, holder) = (f[0].to_string(), f[1].parse::<u64>().unwrap());
    assert_eq!(f[1], f[2], "the exec'd command is the bound pid: {line}");
    let s = observer.rpc(&d.state, "slot_status", json!({}));
    let held = s["result"]["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held.len(), 1, "{s}");
    assert_eq!(held[0]["pid"], holder);
    assert_eq!(held[0]["lane"], "wk");
    assert_eq!(held[0]["binding"], "strict");
    assert_eq!(held[0]["exec_bound"], true);
    // Forged releases from another process are refused.
    let r = observer.rpc(
        &d.state,
        "slot_release",
        json!({"token": token, "pid": holder, "lane": "wk"}),
    );
    assert_eq!(r["ok"], false, "{r}");
    let r = observer.rpc(&d.state, "slot_release", json!({"token": token}));
    assert_eq!(r["ok"], false, "{r}");
    assert!(
        r["error"]["message"]
            .as_str()
            .unwrap()
            .contains("another caller"),
        "{r}"
    );
    std::fs::write(&go, "").unwrap();
    let r = wk.answer(n, "exec-bound run");
    assert_eq!(r["rc"], 7, "run exits with the command's code: {r}");
    // Freed by the daemon on its own — no slot call is made here.
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        let freed = d.events("wk").iter().any(|e| {
            e["kind"] == "slot_released"
                && e["payload"]["pid"] == holder
                && ["holder died", "holder exited"]
                    .contains(&e["payload"]["reason"].as_str().unwrap_or(""))
        });
        if freed {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "the watcher never freed the hold: {:?}",
            d.events("wk")
        );
        thread::sleep(Duration::from_millis(50));
    }
    let s = observer.rpc(&d.state, "slot_status", json!({}));
    assert!(
        s["result"]["pools"]["build"]["held"]
            .as_array()
            .unwrap()
            .is_empty(),
        "{s}"
    );
}

/// A tracker project `p` for runner tests (CAD-230b): one git repo with
/// a commit and `recipes` (YAML, already indented) under
/// `build.recipes`. This test's daemon — and every CLI and lane shell
/// spawned after this call — reads the tracker through its own
/// `CADENCE_PM_DIR`.
fn runner_project(recipes: &str) -> (TempDir, PathBuf) {
    let dir = TempDir::new().unwrap();
    let repo = dir.path().join("repo");
    std::fs::create_dir_all(&repo).unwrap();
    std::fs::write(repo.join("README"), "runner fixture\n").unwrap();
    for args in [
        &["init", "-q"][..],
        &["add", "."],
        &[
            "-c",
            "user.email=t@t",
            "-c",
            "user.name=t",
            "commit",
            "-q",
            "-m",
            "fixture",
        ],
    ] {
        let ok = std::process::Command::new("git")
            .arg("-C")
            .arg(&repo)
            .args(args)
            .status()
            .unwrap()
            .success();
        assert!(ok, "git {args:?}");
    }
    let pm = dir.path().join("pm");
    std::fs::create_dir_all(pm.join("p")).unwrap();
    std::fs::write(
        pm.join("p/project.yaml"),
        format!(
            "key: p\nprefix: P\nrepos:\n- path: {}\nbuild:\n  recipes:\n{recipes}",
            repo.display()
        ),
    )
    .unwrap();
    test_env().set("CADENCE_PM_DIR", pm.to_str().unwrap());
    (dir, repo)
}

/// One recipe line: `name` running `sh -c script` with `env` allowlisted.
fn sh_recipe(name: &str, script: &str, env: &[&str]) -> String {
    format!(
        "    {name}:\n      argv: [sh, -c, {}]\n      env: {}\n",
        serde_json::to_string(script).unwrap(),
        serde_json::to_string(env).unwrap()
    )
}

/// `text` as one single-quoted POSIX shell word.
fn shell_quote(text: &str) -> String {
    format!("'{}'", text.replace('\'', "'\\''"))
}

/// The runner id a `build-slot launch` announced on stderr.
fn launched_runner(stderr: &str) -> String {
    stderr
        .split_whitespace()
        .find(|w| w.starts_with("run-"))
        .unwrap_or_else(|| panic!("no runner id in: {stderr}"))
        .to_string()
}

/// CAD-230 phase b2 ACCEPTANCE: an authorized pane agent launches a
/// project's fixed recipe. The daemon runs it under a strict,
/// exec-bound slot held by exactly the process it spawned (the
/// recipe's `$$`), accounted to the requester's lane; the recipe's own
/// tree may read status but may not nest a slot request; the CLI
/// streams the log and exits with the recipe's code; the receipt binds
/// recipe, launch digest and source HEAD; and the exit frees the slot
/// and prunes the runner's enrollment.
#[test]
fn build_slot_launch_runs_a_fixed_recipe_under_an_exec_bound_slot() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let out = TempDir::new().unwrap();
    let cadence = env!("CARGO_BIN_EXE_cadence");
    let state = d.state.display();
    let status = out.path().join("status.json");
    let nested = out.path().join("nested.txt");
    let script = format!(
        "echo ok; echo \"pid $$\"; {cadence} --state-dir {state} build-slot status --json \
         > {}; {cadence} --state-dir {state} build-slot acquire build --pid $$ > {} 2>&1; \
         exit 3",
        status.display(),
        nested.display()
    );
    let (_proj, repo) = runner_project(&sh_recipe("ok", &script, &["PATH", "HOME"]));
    let run = cadence_at(
        home.path(),
        &d.state,
        &["build-slot", "launch", "ok", "--project", "p"],
    );
    let (stdout, stderr) = (
        String::from_utf8_lossy(&run.stdout).to_string(),
        String::from_utf8_lossy(&run.stderr).to_string(),
    );
    assert_eq!(run.status.code(), Some(3), "{stdout}\n{stderr}");
    assert!(stdout.starts_with("ok\n"), "the log streams: {stdout}");
    let id = launched_runner(&stderr);
    let r = cadence_at(home.path(), &d.state, &["build-slot", "runner", &id]);
    assert!(r.status.success(), "{}", String::from_utf8_lossy(&r.stderr));
    let receipt: Value = serde_json::from_slice(&r.stdout).unwrap();
    assert_eq!(receipt["state"], "exited", "{receipt}");
    assert_eq!(receipt["exit_code"], 3);
    assert_eq!(receipt["complete"], true);
    assert_eq!(
        (receipt["project"].as_str(), receipt["recipe"].as_str()),
        (Some("p"), Some("ok"))
    );
    assert_eq!(
        receipt["requester"],
        json!({"kind": "pane", "lane": SELF_LANE})
    );
    assert_eq!(receipt["argv"], json!(["sh", "-c", script]));
    assert_eq!(receipt["digest"].as_str().unwrap().len(), 64);
    let head = std::process::Command::new("git")
        .arg("-C")
        .arg(&repo)
        .args(["rev-parse", "HEAD"])
        .output()
        .unwrap();
    assert_eq!(
        receipt["head_sha"].as_str().unwrap(),
        String::from_utf8_lossy(&head.stdout).trim()
    );
    assert!(receipt["started"].as_f64().is_some() && receipt["ended"].as_f64().is_some());
    assert_eq!(receipt["dirty"], false);
    let pid = receipt["pid"].as_u64().unwrap();
    let log = std::fs::read_to_string(receipt["log_path"].as_str().unwrap()).unwrap();
    assert!(log.contains("ok\n"), "{log}");
    // The exec'd recipe is the enrolled process: exec kept the pid.
    assert!(log.contains(&format!("pid {pid}\n")), "{log}");
    // While it ran: one strict, exec-bound hold on the requester's lane,
    // held by exactly that process under the runner's enrollment.
    let s: Value = serde_json::from_str(&std::fs::read_to_string(&status).unwrap()).unwrap();
    let held = s["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held.len(), 1, "{s}");
    assert_eq!(held[0]["pid"], pid);
    assert_eq!(held[0]["lane"], SELF_LANE);
    assert_eq!(held[0]["binding"], "strict");
    assert_eq!(held[0]["exec_bound"], true);
    assert_eq!(held[0]["enrollment_id"], receipt["enrollment_id"]);
    assert!(s["enrollments"]
        .as_array()
        .unwrap()
        .iter()
        .any(|e| e["runner_id"] == id.as_str() && e["root"]["pid"] == pid));
    let nested = std::fs::read_to_string(&nested).unwrap();
    assert!(nested.contains("already holds its slot"), "{nested}");
    // After: the slot is free and the runner's enrollment is gone.
    let s = d.rpc("slot_status", json!({})).unwrap();
    assert!(
        s["pools"]["build"]["held"].as_array().unwrap().is_empty(),
        "{s}"
    );
    assert!(!s["enrollments"]
        .as_array()
        .unwrap()
        .iter()
        .any(|e| e["runner_id"] == id.as_str()));
    assert!(d
        .events(SELF_LANE)
        .iter()
        .any(|e| e["kind"] == "runner_finished" && e["payload"]["runner_id"] == id.as_str()));
}

/// CAD-230 phase b2 ACCEPTANCE: the refusals. An unknown recipe names
/// what the project defines; a request carrying any command-,
/// environment- or identity-shaped field is refused (the caller never
/// supplies argv, cwd or env); trailing CLI argv is refused; a caller
/// with no pane, no enrolled endpoint and no operator proof is refused
/// with the rule named; and none of it launches anything. The same
/// recipe launches for the pane agent and for an enrolled managed
/// endpoint.
#[test]
fn build_slot_launch_refuses_unknown_recipes_injection_and_unproven_callers() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let (proj, _repo) = runner_project(&sh_recipe("ok", "echo fixed", &[]));
    let mut agent = LaneShell::spawn(home.path());
    plant_pane(&d, "dev-1", agent.pid());
    let (rc, out) = agent.cadence(&d.state, "build-slot launch nope --project p");
    assert_ne!(rc, 0, "{out}");
    assert!(
        out.contains("Unknown recipe 'nope'") && out.contains("it defines: ok"),
        "{out}"
    );
    for (field, value) in [
        ("argv", json!(["sh", "-c", "echo injected"])),
        ("cmd", json!("echo injected")),
        ("env", json!({"LD_PRELOAD": "x"})),
        ("cwd", json!("/")),
        ("lane", json!("dev-1")),
        ("alias", json!("dev-1")),
        ("pid", json!(1)),
    ] {
        let mut params = json!({"recipe": "ok", "project": "p"});
        params[field] = value;
        let r = agent.rpc(&d.state, "slot_launch", params);
        assert_eq!(r["ok"], false, "{field}: {r}");
        let msg = r["error"]["message"].as_str().unwrap();
        assert!(
            msg.contains(&format!("'{field}' is refused")),
            "{field}: {msg}"
        );
    }
    let (rc, out) = agent.cadence(
        &d.state,
        "build-slot launch ok --project p -- echo injected",
    );
    assert_ne!(rc, 0, "trailing argv is refused: {out}");
    let mut stray = LaneShell::spawn(home.path());
    let r = stray.rpc(
        &d.state,
        "slot_launch",
        json!({"recipe": "ok", "project": "p"}),
    );
    assert_eq!(r["ok"], false, "{r}");
    assert!(
        r["error"]["message"]
            .as_str()
            .unwrap()
            .contains("needs a pane agent, an enrolled managed endpoint or the proven operator"),
        "{r}"
    );
    let receipts = |state: &Path| {
        std::fs::read_dir(cadence_agent::runner::runners_dir(state))
            .map(|d| {
                d.flatten()
                    .filter(|e| e.file_name().to_string_lossy().ends_with(".json"))
                    .count()
            })
            .unwrap_or(0)
    };
    assert_eq!(receipts(&d.state), 0, "no refusal launched anything");
    // The same recipe, for callers the daemon can admit.
    let (rc, out) = agent.cadence(&d.state, "build-slot launch ok --project p");
    assert_eq!(rc, 0, "{out}");
    assert!(out.contains("fixed"), "{out}");
    let mut wk = ManagedWorker::start(&d, "wk");
    let pm = proj.path().join("pm");
    let r = wk.exec(&[
        "env",
        &format!("CADENCE_PM_DIR={}", pm.display()),
        env!("CARGO_BIN_EXE_cadence"),
        "--state-dir",
        d.state.to_str().unwrap(),
        "build-slot",
        "launch",
        "ok",
        "--project",
        "p",
    ]);
    assert_eq!(r["rc"], 0, "{r}");
    assert!(r["out"].as_str().unwrap().contains("fixed"), "{r}");
    assert_eq!(receipts(&d.state), 2);
}

/// CAD-230 phase b2 (review): what of a runner's tree is contained. A
/// descendant that detaches (`setsid -f`, reparented off the runner)
/// but keeps the runner's environment is still not the operator, so it
/// cannot launch as `(operator)`; and a straggler the recipe left in its
/// process group is ended with the recipe, never left building after
/// its slot frees. A detached descendant that ALSO scrubs the runner's
/// environment is refused too, by the daemon-descendant rule under the
/// child subreaper (CAD-308) — see
/// `build_slot_launch_detached_scrubbed_descendant_is_refused`.
#[test]
fn build_slot_launch_runner_tree_is_contained() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let work = TempDir::new().unwrap();
    let req = work.path().join("req.json");
    let resp = work.path().join("resp.json");
    let straggler = work.path().join("straggler");
    std::fs::write(
        &req,
        cadence_agent::proto::request("slot_launch", json!({"recipe": "ok", "project": "p"}))
            .to_string(),
    )
    .unwrap();
    let py = format!(
        "import socket;s=socket.socket(socket.AF_UNIX);s.connect({sock:?});\
         s.sendall(open({req:?},'rb').read()+b'\\n');\
         open({out:?}+'.tmp','w').write(s.makefile().readline());\
         import os;os.rename({out:?}+'.tmp',{out:?})",
        sock = client::socket_path(&d.state).display().to_string(),
        req = req.display().to_string(),
        out = resp.display().to_string(),
    );
    let script = format!(
        "sleep 60 & echo $! > {st}; setsid -f python3 -c {py}; \
         while [ ! -e {r} ]; do sleep 0.05; done; exit 0",
        st = straggler.display(),
        py = shell_quote(&py),
        r = resp.display()
    );
    let (_proj, _repo) = runner_project(&sh_recipe("ok", &script, &["PATH"]));
    let run = cadence_at(
        home.path(),
        &d.state,
        &["build-slot", "launch", "ok", "--project", "p"],
    );
    assert_eq!(
        run.status.code(),
        Some(0),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    let answer: Value = serde_json::from_str(&std::fs::read_to_string(&resp).unwrap()).unwrap();
    assert_eq!(answer["ok"], false, "{answer}");
    let msg = answer["error"]["message"].as_str().unwrap();
    assert!(msg.contains("CADENCE_RUNNER_ID"), "{msg}");
    let pid: u32 = std::fs::read_to_string(&straggler)
        .unwrap()
        .trim()
        .parse()
        .unwrap();
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        let stat = std::fs::read_to_string(format!("/proc/{pid}/stat")).unwrap_or_default();
        let gone = stat.is_empty()
            || stat
                .rsplit_once(')')
                .is_some_and(|(_, rest)| rest.trim_start().starts_with('Z'));
        if gone {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "straggler {pid} outlived its recipe"
        );
        thread::sleep(Duration::from_millis(50));
    }
    assert_eq!(
        std::fs::read_dir(cadence_agent::runner::runners_dir(&d.state))
            .unwrap()
            .flatten()
            .filter(|e| e.file_name().to_string_lossy().ends_with(".json"))
            .count(),
        1,
        "the detached descendant launched nothing"
    );
}

/// Wait until `pid` has no `/proc` entry — REAPED, not merely exited:
/// an unreaped zombie keeps its entry (state `Z`).
fn wait_reaped(pid: u32, what: &str) {
    let deadline = Instant::now() + Duration::from_secs(15);
    while Path::new(&format!("/proc/{pid}")).exists() {
        assert!(
            Instant::now() < deadline,
            "{what} (pid {pid}) was never reaped: {}",
            std::fs::read_to_string(format!("/proc/{pid}/stat")).unwrap_or_default()
        );
        thread::sleep(Duration::from_millis(50));
    }
}

/// Wait until the daemon has no zombie child left (bounded).
fn wait_no_daemon_zombies(daemon_pid: u64) {
    let zombies = || -> Vec<u32> {
        let Ok(tasks) = std::fs::read_dir(format!("/proc/{daemon_pid}/task")) else {
            return Vec::new();
        };
        tasks
            .flatten()
            .filter_map(|t| std::fs::read_to_string(t.path().join("children")).ok())
            .flat_map(|c| {
                c.split_whitespace()
                    .filter_map(|p| p.parse::<u32>().ok())
                    .collect::<Vec<_>>()
            })
            .filter(|pid| {
                std::fs::read_to_string(format!("/proc/{pid}/stat")).is_ok_and(|s| {
                    s.rsplit_once(')')
                        .is_some_and(|(_, rest)| rest.trim_start().starts_with('Z'))
                })
            })
            .collect()
    };
    let deadline = Instant::now() + Duration::from_secs(15);
    loop {
        let left = zombies();
        if left.is_empty() {
            return;
        }
        assert!(
            Instant::now() < deadline,
            "zombie children of the daemon linger: {left:?}"
        );
        thread::sleep(Duration::from_millis(100));
    }
}

/// The `daemon run` process's pid, and that it is the child subreaper.
fn subreaper_daemon_pid(d: &TestDaemon) -> u64 {
    let health = d.rpc("health", json!({})).unwrap();
    assert_eq!(health["child_subreaper"], true, "{health}");
    health["pid"].as_u64().unwrap()
}

/// CAD-308 (flips the residual CAD-230 phase b2 pinned): a recipe
/// descendant that detaches AND scrubs the runner's environment —
/// `env -u CADENCE_RUNNER_ID -u CADENCE_RUNNER_DIGEST setsid -f …`,
/// stdio to /dev/null — re-parents to the daemon, its child subreaper,
/// instead of to init. It is still a daemon descendant, so operator
/// proof refuses it by that rule: no `(operator)` launch, no nested
/// runner. Once it exits the daemon reaps it — no zombie lingers. A
/// real `daemon run` process: only that one is the subreaper.
#[test]
fn build_slot_launch_detached_scrubbed_descendant_is_refused() {
    let dir = TempDir::new().unwrap();
    let home = TempDir::new().unwrap();
    let work = TempDir::new().unwrap();
    let req = work.path().join("req.json");
    let resp = work.path().join("resp.json");
    let pidf = work.path().join("detached.pid");
    std::fs::write(
        &req,
        cadence_agent::proto::request("slot_launch", json!({"recipe": "inner", "project": "p"}))
            .to_string(),
    )
    .unwrap();
    let py = format!(
        "import socket,os;open({pid:?},'w').write(str(os.getpid()));\
         s=socket.socket(socket.AF_UNIX);s.connect({sock:?});\
         s.sendall(open({req:?},'rb').read()+b'\\n');\
         open({out:?}+'.tmp','w').write(s.makefile().readline());\
         os.rename({out:?}+'.tmp',{out:?})",
        pid = pidf.display().to_string(),
        sock = client::socket_path(dir.path()).display().to_string(),
        req = req.display().to_string(),
        out = resp.display().to_string(),
    );
    let outer = format!(
        "env -u CADENCE_RUNNER_ID -u CADENCE_RUNNER_DIGEST setsid -f python3 -c {py} \
         </dev/null >/dev/null 2>&1; \
         while [ ! -e {r} ]; do sleep 0.05; done; exit 0",
        py = shell_quote(&py),
        r = resp.display()
    );
    let recipes = sh_recipe("outer", &outer, &["PATH"]) + &sh_recipe("inner", "echo inner", &[]);
    let (_proj, _repo) = runner_project(&recipes);
    let d = TestDaemon::start_process_in(dir);
    let _reaper = DaemonReaper::new(&d.state);
    let daemon_pid = subreaper_daemon_pid(&d);
    let mut lane = LaneShell::spawn(home.path());
    plant_pane(&d, "dev-1", lane.pid());
    let (rc, out) = lane.cadence(&d.state, "build-slot launch outer --project p");
    assert_eq!(rc, 0, "{out}");
    let answer: Value = serde_json::from_str(&std::fs::read_to_string(&resp).unwrap()).unwrap();
    assert_eq!(answer["ok"], false, "{answer}");
    let msg = answer["error"]["message"].as_str().unwrap();
    assert!(msg.contains("not provably the operator"), "{msg}");
    assert!(
        msg.contains(&format!("descends from the daemon (pid {daemon_pid})")),
        "refused by the daemon-descendant rule: {msg}"
    );
    assert_eq!(
        std::fs::read_dir(cadence_agent::runner::runners_dir(&d.state))
            .unwrap()
            .flatten()
            .filter(|e| e.file_name().to_string_lossy().ends_with(".json"))
            .count(),
        1,
        "the detached descendant launched nothing"
    );
    let pid: u32 = std::fs::read_to_string(&pidf)
        .unwrap()
        .trim()
        .parse()
        .unwrap();
    wait_reaped(pid, "the detached descendant, adopted by the daemon");
}

/// CAD-308 with the CAD-276 shape: a managed provider's tool runs
/// `env -u CADENCE_ALIAS setsid -f … build-slot reconcile` — its own
/// session leader, the alias scrubbed, stdio redirected. Without the
/// subreaper it re-parented to init and passed operator proof; under
/// `daemon run` it re-parents to the daemon, is refused by the
/// daemon-descendant rule, and is reaped by the daemon once it exits.
///
/// The same detach from a registered pane whose shell the daemon did
/// NOT launch still passes the operator gate — it reaches the
/// live-holder rule. That is the documented pane-route residual
/// (CAD-280), asserted as today's behaviour on purpose.
#[test]
fn slot_reconcile_refuses_a_managed_tools_setsid_detach() {
    let dir = TempDir::new().unwrap();
    // A hermetic tracker dir for the daemon (no host pm.yaml).
    let (_proj, _repo) = runner_project(&sh_recipe("ok", "echo ok", &[]));
    let mock = ManagedWorker::install(dir.path(), dir.path(), "wk");
    let d = TestDaemon::start_process_in(dir);
    let _reaper = DaemonReaper::new(&d.state);
    let daemon_pid = subreaper_daemon_pid(&d);
    let home = TempDir::new().unwrap();
    let mut pane = LaneShell::spawn(home.path());
    plant_pane(&d, "pane-1", pane.pid());
    let mut wk = mock.enroll(&d, "wk");
    let g = wk.rpc(
        "self",
        "slot_acquire",
        json!({"kind": "build", "pid": "$PID", "request_id": "r1"}),
    );
    let token = g["result"]["token"].as_str().unwrap().to_string();
    let s = pane.rpc(&d.state, "slot_status", json!({}));
    let hold = s["result"]["pools"]["build"]["held"][0].clone();
    let root = s["result"]["enrollments"][0]["root"].clone();
    let work = TempDir::new().unwrap();
    let evidence = work.path().join("evidence.json");
    std::fs::write(
        &evidence,
        json!({
            "owner_generation": hold["owner_generation"], "pid": root["pid"],
            "starttime": root["starttime"], "uid": root["uid"],
            "observed_at": "now", "process_read": "claimed exited",
            "command_outcome": "done", "side_effect_review": "none",
        })
        .to_string(),
    )
    .unwrap();
    // `sh detach.sh OUT`: record its pid, run the reconcile, land the
    // CLI's output and exit code at OUT.
    let script = work.path().join("detach.sh");
    std::fs::write(
        &script,
        format!(
            "echo $$ > \"$1.pid\"\n\
             {bin} --state-dir {state} build-slot reconcile {enr} {token} \
             --evidence \"$(cat {ev})\" > \"$1.tmp\" 2>&1\n\
             echo \"rc=$?\" >> \"$1.tmp\"\n\
             mv \"$1.tmp\" \"$1\"\n",
            bin = env!("CARGO_BIN_EXE_cadence"),
            state = d.state.display(),
            enr = hold["enrollment_id"].as_str().unwrap(),
            ev = evidence.display(),
        ),
    )
    .unwrap();
    let detach = |out: &Path| {
        format!(
            "env -u CADENCE_ALIAS setsid -f sh {} {} </dev/null >/dev/null 2>&1",
            script.display(),
            out.display()
        )
    };
    let landed = |out: &Path, route: &str| {
        let deadline = Instant::now() + Duration::from_secs(30);
        while !out.exists() {
            assert!(Instant::now() < deadline, "{route}: never answered");
            thread::sleep(Duration::from_millis(20));
        }
        std::fs::read_to_string(out).unwrap()
    };

    // Off a managed tool: re-parented to the daemon, refused.
    let out = work.path().join("managed.out");
    let r = wk.exec(&["sh", "-c", &detach(&out)]);
    assert_eq!(r["rc"], 0, "{r}");
    let text = landed(&out, "managed detach");
    assert!(text.contains("not provably the operator"), "{text}");
    assert!(
        text.contains(&format!("descends from the daemon (pid {daemon_pid})")),
        "refused by the daemon-descendant rule: {text}"
    );
    let pid: u32 = std::fs::read_to_string(work.path().join("managed.out.pid"))
        .unwrap()
        .trim()
        .parse()
        .unwrap();
    wait_reaped(pid, "the detached reconcile shell, adopted by the daemon");

    // Off a pane the daemon did not launch: the residual (CAD-280).
    let out = work.path().join("pane.out");
    let (rc, run) = pane.run(&detach(&out));
    assert_eq!(rc, 0, "{run}");
    let text = landed(&out, "pane detach");
    assert!(
        !text.contains("not provably the operator") && text.contains("is alive"),
        "the pane-route residual (CAD-280) passes the operator gate and meets \
         the live-holder rule (a gate refusal here means this host re-parents \
         the test's orphans to a process carrying an agent's env): {text}"
    );

    let s = pane.rpc(&d.state, "slot_status", json!({}));
    assert_eq!(
        s["result"]["pools"]["build"]["held"]
            .as_array()
            .unwrap()
            .len(),
        1,
        "no detached caller freed anything: {s}"
    );
}

/// CAD-308: a managed endpoint under the active reaper starts, runs
/// tool subprocesses and stops as it always did. Its provider is the
/// adapter's own child: the adapter collects it on stop (no `/proc`
/// entry left, no `ECHILD` anywhere), the agent reads `stopped` with no
/// error, no zombie child of the daemon lingers, and nothing the daemon
/// spawned itself is counted as adopted.
#[test]
fn subreaper_managed_endpoint_starts_and_stops_cleanly() {
    let dir = TempDir::new().unwrap();
    // A hermetic tracker dir for the daemon (no host pm.yaml).
    let (_proj, _repo) = runner_project(&sh_recipe("ok", "echo ok", &[]));
    let mock = ManagedWorker::install(dir.path(), dir.path(), "wk");
    let d = TestDaemon::start_process_in(dir);
    let _reaper = DaemonReaper::new(&d.state);
    let daemon_pid = subreaper_daemon_pid(&d);
    let mut wk = mock.enroll(&d, "wk");
    let root = wk.pid;
    for code in [0, 3] {
        let r = wk.exec(&["sh", "-c", &format!("exit {code}")]);
        assert_eq!(r["rc"], code, "{r}");
    }
    let health = d.rpc("health", json!({})).unwrap();
    assert_eq!(health["adopted_live"], 0, "the provider is owned: {health}");
    d.rpc("agent_stop", json!({"alias": "wk"})).unwrap();
    let agent = d.wait_agent("wk", "stopped", 20);
    assert!(agent["error"].is_null(), "{agent}");
    wait_reaped(root, "the managed provider, collected by its adapter");
    wait_no_daemon_zombies(daemon_pid);
    let health = d.rpc("health", json!({})).unwrap();
    assert_eq!(health["adopted_live"], 0, "{health}");
    let events = d
        .events("wk")
        .iter()
        .map(Value::to_string)
        .collect::<String>();
    let log = std::fs::read_to_string(d.dir.path().join("daemon-process.log")).unwrap();
    for text in [&events, &log] {
        assert!(!text.contains("No child processes"), "{text}");
    }
}

/// CAD-308: the reaper never takes an owned child's exit status. Under
/// `daemon run`, recipes that each leave a burst of detached children
/// exiting at once — orphans the daemon adopts and must reap — still
/// end with their own exit code on every receipt: the runner threads'
/// waits and the `git` calls around each gate all got their statuses.
/// Afterwards no zombie child of the daemon lingers, and `daemon.log`
/// says once that the daemon is the subreaper.
#[test]
fn subreaper_reaps_orphans_while_owners_keep_their_exit_statuses() {
    let dir = TempDir::new().unwrap();
    let flood = "i=0; while [ $i -lt 40 ]; do setsid -f sh -c 'exit 0' \
                 </dev/null >/dev/null 2>&1; i=$((i+1)); done; exit 7";
    let (_proj, _repo) = runner_project(&sh_recipe("flood", flood, &["PATH"]));
    let d = TestDaemon::start_process_in(dir);
    let _reaper = DaemonReaper::new(&d.state);
    let daemon_pid = subreaper_daemon_pid(&d);
    let home = TempDir::new().unwrap();
    let mut lane = LaneShell::spawn(home.path());
    plant_pane(&d, "dev-1", lane.pid());
    let launch = format!(
        "{} --state-dir {} build-slot launch flood --project p >/dev/null 2>&1",
        env!("CARGO_BIN_EXE_cadence"),
        d.state.display()
    );
    // Three at once — the default pool's three build slots — twice.
    for _ in 0..2 {
        lane.run(&format!("{launch} & {launch} & {launch} & wait"));
    }
    let receipts: Vec<_> = std::fs::read_dir(cadence_agent::runner::runners_dir(&d.state))
        .unwrap()
        .flatten()
        .filter_map(|e| {
            let name = e.file_name().to_string_lossy().to_string();
            let id = name.strip_suffix(".json")?.to_string();
            Some(cadence_agent::runner::read_receipt(&d.state, &id).unwrap())
        })
        .collect();
    assert_eq!(receipts.len(), 6, "{receipts:?}");
    for r in &receipts {
        assert_eq!(
            (r.state.as_str(), r.exit_code),
            ("exited", Some(7)),
            "every owner kept its child's status: {r:?}"
        );
    }
    // Every child of the daemon that is a zombie now must be gone soon:
    // nothing owns the adopted orphans but the reaper.
    wait_no_daemon_zombies(daemon_pid);
    let health = d.rpc("health", json!({})).unwrap();
    assert!(
        health["adopted_reaped_total"].as_u64().unwrap() >= 6 * 40,
        "every flooded orphan was adopted and reaped: {health}"
    );
    let log = std::fs::read_to_string(d.dir.path().join("daemon-process.log")).unwrap();
    assert_eq!(
        log.matches(&format!("subreaper: pid {daemon_pid} "))
            .count(),
        1,
        "{log}"
    );
}

/// CAD-230 phase b2: a launch queues like any other request — behind a
/// held slot it waits, and when its wait runs out the gate never opens:
/// the recipe never starts, the receipt says `timed_out`, and the queue
/// keeps no waiter for it.
#[test]
fn build_slot_launch_times_out_in_the_queue_without_running() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let (_proj, _repo) = runner_project(&sh_recipe("ok", "echo RAN", &[]));
    let g = slot_acquire(&d, "build", SELF_LANE, "hold");
    assert_eq!(g["granted"], true);
    let run = cadence_at(
        home.path(),
        &d.state,
        &[
            "build-slot",
            "launch",
            "ok",
            "--project",
            "p",
            "--wait-secs",
            "1",
        ],
    );
    let stderr = String::from_utf8_lossy(&run.stderr).to_string();
    assert!(!run.status.success(), "{stderr}");
    assert!(stderr.contains("timed_out"), "{stderr}");
    let id = launched_runner(&stderr);
    let receipt = cadence_agent::runner::read_receipt(&d.state, &id).unwrap();
    assert_eq!(receipt.state, "timed_out");
    assert_eq!((receipt.exit_code, receipt.started), (None, None));
    let log = std::fs::read_to_string(&receipt.log_path).unwrap();
    assert!(!log.contains("RAN"), "the gate never opened: {log}");
    let s = d.rpc("slot_status", json!({})).unwrap();
    assert!(s["waiting"].as_array().unwrap().is_empty(), "{s}");
    assert_eq!(s["pools"]["build"]["held"].as_array().unwrap().len(), 1);
}

/// CAD-230 phase b2: the launch digest names the checkout's HEAD, so a
/// checkout that moves while the runner queues is not the source it
/// bound — the gate never opens and the receipt says why. A dirty tree
/// at launch is recorded, never hidden.
#[test]
fn build_slot_launch_refuses_a_source_that_moved_while_queued() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let (_proj, repo) = runner_project(&sh_recipe("ok", "echo RAN", &[]));
    std::fs::write(repo.join("README"), "edited, uncommitted\n").unwrap();
    let hold = slot_acquire(&d, "build", SELF_LANE, "hold");
    let run = cadence_at(
        home.path(),
        &d.state,
        &["build-slot", "launch", "ok", "--project", "p", "--detach"],
    );
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    let id = String::from_utf8_lossy(&run.stdout).trim().to_string();
    let r = cadence_agent::runner::read_receipt(&d.state, &id).unwrap();
    assert!(r.dirty, "an uncommitted edit is recorded: {r:?}");
    let git = |args: &[&str]| {
        let ok = std::process::Command::new("git")
            .arg("-C")
            .arg(&repo)
            .args(["-c", "user.email=t@t", "-c", "user.name=t"])
            .args(args)
            .status()
            .unwrap()
            .success();
        assert!(ok, "git {args:?}");
    };
    git(&["commit", "-qam", "moved"]);
    slot_release(
        &d,
        hold["token"].as_str().unwrap(),
        SELF_LANE,
        std::process::id(),
    );
    let deadline = Instant::now() + Duration::from_secs(20);
    let r = loop {
        let r = cadence_agent::runner::read_receipt(&d.state, &id).unwrap();
        if r.is_terminal() {
            break r;
        }
        assert!(Instant::now() < deadline, "runner never ended: {r:?}");
        thread::sleep(Duration::from_millis(50));
    };
    assert_eq!(r.state, "refused", "{r:?}");
    assert!(r.reason.as_deref().unwrap().contains("HEAD moved"), "{r:?}");
    assert_eq!(r.started, None);
    let log = std::fs::read_to_string(&r.log_path).unwrap();
    assert!(!log.contains("RAN"), "the gate never opened: {log}");
    let s = d.rpc("slot_status", json!({})).unwrap();
    assert!(
        s["pools"]["build"]["held"].as_array().unwrap().is_empty(),
        "{s}"
    );
}

/// CAD-230 phase b2 restart semantics: a runner in flight when the
/// daemon restarts is reported `unknown` with its receipt incomplete —
/// never relaunched. Its hold stays accounted (the process lives) under
/// a revoked enrollment, until the process is proven dead.
#[test]
fn build_slot_launch_in_flight_at_restart_is_unknown_never_relaunched() {
    let state = TempDir::new().unwrap();
    let d = TestDaemon::start_on_opts(state.path().to_path_buf(), slot_opts(2, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let marks = TempDir::new().unwrap();
    let marker = marks.path().join("starts");
    let script = format!("echo start >> {}; sleep 60", marker.display());
    let (_proj, _repo) = runner_project(&sh_recipe("long", &script, &[]));
    let run = cadence_at(
        home.path(),
        &d.state,
        &["build-slot", "launch", "long", "--project", "p", "--detach"],
    );
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    let id = String::from_utf8_lossy(&run.stdout).trim().to_string();
    let deadline = Instant::now() + Duration::from_secs(20);
    let pid = loop {
        let r = cadence_agent::runner::read_receipt(&d.state, &id).unwrap();
        if r.state == "running" && marker.exists() {
            break r.pid.unwrap();
        }
        assert!(Instant::now() < deadline, "runner never ran: {r:?}");
        thread::sleep(Duration::from_millis(50));
    };
    drop(d);
    let d2 = TestDaemon::start_on_opts(state.path().to_path_buf(), slot_opts(2, 1, 900, &[]));
    plant_pane(&d2, SELF_LANE, std::process::id());
    let r = cadence_agent::runner::read_receipt(&d2.state, &id).unwrap();
    assert_eq!(r.state, "unknown", "{r:?}");
    assert!(!r.complete);
    assert_eq!(r.last_state.as_deref(), Some("running"));
    assert!(d2
        .events(SELF_LANE)
        .iter()
        .any(|e| e["kind"] == "runner_unknown" && e["payload"]["runner_id"] == id.as_str()));
    let s = d2.rpc("slot_status", json!({})).unwrap();
    let held = s["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held.len(), 1, "the live runner stays accounted: {s}");
    assert_eq!(held[0]["pid"], pid);
    assert_eq!(held[0]["liveness"], "alive");
    assert_eq!(held[0]["auth_state"], "revoked");
    thread::sleep(Duration::from_millis(1500));
    let starts = std::fs::read_to_string(&marker).unwrap();
    assert_eq!(starts.lines().count(), 1, "never relaunched: {starts}");
    // Cleanup: end the orphan; proof of its death frees the hold.
    unsafe { libc::kill(-(pid as i32), libc::SIGKILL) };
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        let s = d2.rpc("slot_status", json!({})).unwrap();
        if s["pools"]["build"]["held"].as_array().unwrap().is_empty() {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "the dead runner's hold stayed: {s}"
        );
        thread::sleep(Duration::from_millis(50));
    }
}

/// `starve_secs` promotes a long waiter ahead of a priority lane:
/// priority wins inside the window, the starved waiter wins after it.
/// The slot clock is injected — the test advances it instead of
/// sleeping, so timing stays exact under host load. The waiter lanes
/// are real connection identities — one lane shell each (CAD-113).
#[test]
fn slot_starve_promotes_long_waiter() {
    let clock = std::sync::Arc::new(std::sync::atomic::AtomicU64::new(0));
    let d = TestDaemon::start_opts(slot_opts_clock(1, 1, 3, &["qa-1"], Some(clock.clone())));
    let home = TempDir::new().unwrap();
    plant_self(&d);
    let mut dev = LaneShell::spawn(home.path());
    plant_pane(&d, "dev-2", dev.pid());
    let mut qa = LaneShell::spawn(home.path());
    plant_pane(&d, "qa-1", qa.pid());
    let h1 = slot_acquire(&d, "build", SELF_LANE, "h1")["token"]
        .as_str()
        .unwrap()
        .to_string();
    // Ordinary waiter first, priority waiter second.
    let w = dev.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "build", "pid": dev.pid(), "request_id": "w1"}),
    );
    assert_eq!(w["result"]["granted"], false, "{w}");
    let w = qa.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "test", "pid": qa.pid(), "request_id": "w2"}),
    );
    assert_eq!(w["result"]["granted"], false, "{w}");
    slot_release(&d, &h1, SELF_LANE, std::process::id());
    // Inside the starve window the reviewer lane's test wins.
    let g = qa.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "test", "pid": qa.pid(), "request_id": "w2"}),
    );
    assert_eq!(
        g["result"]["granted"], true,
        "priority lane should outrank: {g}"
    );
    let w2 = g["result"]["token"].as_str().unwrap().to_string();
    // Once w1 has waited past starve_secs it outranks even a new
    // priority request — the never-starve bound.
    clock.store(4, std::sync::atomic::Ordering::Relaxed);
    let w = qa.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "test", "pid": qa.pid(), "request_id": "w3"}),
    );
    assert_eq!(w["result"]["granted"], false, "{w}");
    let r = qa.rpc(
        &d.state,
        "slot_release",
        json!({"token": w2, "pid": qa.pid()}),
    );
    assert_eq!(r["ok"], true, "{r}");
    let g = dev.rpc(
        &d.state,
        "slot_acquire",
        json!({"kind": "build", "pid": dev.pid(), "request_id": "w1"}),
    );
    assert_eq!(
        g["result"]["granted"], true,
        "starved waiter must outrank priority: {g}"
    );
    let s = d.rpc("slot_status", json!({})).unwrap();
    let w3 = s["waiting"]
        .as_array()
        .unwrap()
        .iter()
        .find(|w| w["request_id"] == "w3")
        .expect("w3 still queued");
    assert_eq!(w3["priority"], true);
}

/// suite draws on its own pool — a full suite queue never jams the
/// build lanes, and `test` shares the build pool. The two pool users
/// claim different pids on this connection's own ancestry (CAD-113):
/// the cross-pool deadlock guard keys on `(lane, pid)`, so the same
/// process must never hold one pool while queueing the other.
#[test]
fn slot_pools_are_independent() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let me = std::process::id();
    let parent = std::os::unix::process::parent_id();
    assert_eq!(
        slot_acquire_pid(&d, "suite", SELF_LANE, me, "s1")["granted"],
        true
    );
    assert_eq!(
        slot_acquire_pid(&d, "suite", SELF_LANE, me, "s2")["granted"],
        false,
        "second suite must queue"
    );
    // The suite pool being full does not touch build.
    assert_eq!(
        slot_acquire_pid(&d, "build", SELF_LANE, parent, "b1")["granted"],
        true
    );
    // test shares the build pool — now full too.
    assert_eq!(
        slot_acquire_pid(&d, "test", SELF_LANE, parent, "t1")["granted"],
        false
    );
}

/// The CLI: `--wait-secs 0` fails fast with a named error, a free slot
/// grants a bare token, release returns it, and `status` shows the
/// pool both ways.
#[test]
fn build_slot_cli_acquire_release_status() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let t1 = slot_acquire(&d, "build", SELF_LANE, "r1")["token"]
        .as_str()
        .unwrap()
        .to_string(); // build pool full
    let me = std::process::id().to_string(); // the CLI child's parent
    let out = cadence_at(
        home.path(),
        &d.state,
        &[
            "build-slot",
            "acquire",
            "build",
            "--wait-secs",
            "0",
            "--pid",
            &me,
        ],
    );
    assert!(!out.status.success());
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(err.contains("No build slot free"), "{err}");
    // --pid is required — a bare acquire refuses rather than binding
    // a transient parent the work outlives.
    let out = cadence_at(
        home.path(),
        &d.state,
        &["build-slot", "acquire", "build", "--wait-secs", "0"],
    );
    assert!(!out.status.success());
    assert!(String::from_utf8_lossy(&out.stderr).contains("--pid"));
    // Free it through the CLI — release names the holding lane; the
    // default pid (the CLI's parent = this test) matches the hold.
    let out = cadence_at(
        home.path(),
        &d.state,
        &["build-slot", "release", &t1, "--lane", "dev-1"],
    );
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(String::from_utf8_lossy(&out.stdout).contains("released slot-"));
    let out = cadence_at(
        home.path(),
        &d.state,
        &[
            "build-slot",
            "acquire",
            "build",
            "--wait-secs",
            "0",
            "--lane",
            "dev-9",
            "--pid",
            &me,
        ],
    );
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let token = String::from_utf8_lossy(&out.stdout).trim().to_string();
    assert!(
        token.starts_with("slot-"),
        "bare minted token on stdout: {token:?}"
    );
    // The token round-trips: release by exactly what acquire printed,
    // same lane, same default pid.
    let out = cadence_at(
        home.path(),
        &d.state,
        &["build-slot", "release", &token, "--lane", "dev-9"],
    );
    assert!(out.status.success());
    // `--lane` is advisory only (CAD-113): the daemon derives the
    // caller's lane from the connection, so a release naming another
    // lane still acts on — and only on — the caller's own hold.
    let g = slot_acquire(&d, "build", SELF_LANE, "r9");
    let t9 = g["token"].as_str().unwrap().to_string();
    let out = cadence_at(
        home.path(),
        &d.state,
        &["build-slot", "release", &t9, "--lane", "dev-2"],
    );
    assert!(
        out.status.success(),
        "own hold releases whatever --lane claims: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    // status --json shows the empty pool; bad kind is a named error.
    let out = cadence_at(home.path(), &d.state, &["build-slot", "status", "--json"]);
    let s: Value = serde_json::from_slice(&out.stdout).unwrap();
    assert!(s["pools"]["build"]["held"].as_array().unwrap().is_empty());
    let out = cadence_at(
        home.path(),
        &d.state,
        &[
            "build-slot",
            "acquire",
            "bogus",
            "--wait-secs",
            "0",
            "--pid",
            &me,
        ],
    );
    assert!(!out.status.success());
    assert!(String::from_utf8_lossy(&out.stderr).contains("build, test or suite"));
}

/// `cadence status` carries the slot line — table and --json agree.
#[test]
fn status_footer_shows_slots() {
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    plant_self(&d);
    slot_acquire(&d, "build", SELF_LANE, "r1");
    slot_acquire(&d, "build", SELF_LANE, "r2");
    slot_acquire(&d, "build", SELF_LANE, "r3"); // the waiter
    let home = TempDir::new().unwrap();
    let out = cadence_at(home.path(), &d.state, &["status"]);
    let text = String::from_utf8_lossy(&out.stdout);
    assert!(out.status.success(), "{text}");
    assert!(
        text.contains("slots: 2/2 build, 0/1 suite; waiting: 1"),
        "{text}"
    );
    let out = cadence_at(home.path(), &d.state, &["status", "--json"]);
    let v: Value = serde_json::from_slice(&out.stdout).unwrap();
    assert_eq!(
        v["footer"]["slots"]["pools"]["build"]["held"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    assert_eq!(v["footer"]["slots"]["waiting"].as_array().unwrap().len(), 1);
}

/// `issue start` writes the worktree slot env: `CARGO_BUILD_JOBS` from
/// `[host] jobs_per_lane` plus the helper path — idempotent, and a
/// foreign line in an existing `.env` survives.
#[test]
fn issue_start_writes_slot_env() {
    let d = TestDaemon::start();
    let tmp = TempDir::new().unwrap();
    let (pm_dir, repo, home) = (
        tmp.path().join("pm"),
        tmp.path().join("repo"),
        tmp.path().join("home"),
    );
    for dir in [&pm_dir, &repo, &home] {
        std::fs::create_dir_all(dir).unwrap();
    }
    let git = |dir: &Path, args: &[&str]| {
        let o = std::process::Command::new("git")
            .arg("-C")
            .arg(dir)
            .args(args)
            .output()
            .unwrap();
        assert!(
            o.status.success(),
            "git {}: {}",
            args.join(" "),
            String::from_utf8_lossy(&o.stderr)
        );
    };
    git(&repo, &["init", "-b", "main"]);
    git(&repo, &["config", "user.email", "t@t"]);
    git(&repo, &["config", "user.name", "t"]);
    std::fs::write(repo.join("f"), "x").unwrap();
    git(&repo, &["add", "-A"]);
    git(&repo, &["commit", "-qm", "init"]);
    let bin_dir = Path::new(env!("CARGO_BIN_EXE_cadence"))
        .parent()
        .unwrap()
        .to_path_buf();
    let cli = |args: &[&str]| -> (bool, Value) {
        let out = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
            .arg("--state-dir")
            .arg(&d.state)
            .args(args)
            .env("CADENCE_PM_DIR", &pm_dir)
            .env("HOME", &home)
            .env(
                "PATH",
                format!(
                    "{}:{}",
                    bin_dir.display(),
                    std::env::var("PATH").unwrap_or_default()
                ),
            )
            .env_remove("CADENCE_ALIAS")
            .operator_output()
            .unwrap();
        let text = if out.stdout.is_empty() {
            String::from_utf8_lossy(&out.stderr).to_string()
        } else {
            String::from_utf8_lossy(&out.stdout).to_string()
        };
        (
            out.status.success(),
            serde_json::from_str(text.trim()).unwrap_or_else(|_| panic!("not json: {text}")),
        )
    };
    assert!(cli(&["issue", "init"]).0);
    let repo_s = repo.canonicalize().unwrap().to_str().unwrap().to_string();
    assert!(cli(&["issue", "project", "add", "demo", "--prefix", "D", "--repo", &repo_s]).0);
    assert!(cli(&["issue", "new", "One", "--project", "demo"]).0);
    // The [host] override lands before the start reads it.
    let pm_yaml = pm_dir.join("pm.yaml");
    let mut yaml = std::fs::read_to_string(&pm_yaml).unwrap();
    yaml.push_str("host:\n  jobs_per_lane: 7\n");
    std::fs::write(&pm_yaml, yaml).unwrap();
    let (ok, out) = cli(&["issue", "start", "D-1"]);
    assert!(ok, "{out}");
    let env_file = PathBuf::from(out["slot_env"]["path"].as_str().unwrap());
    assert_eq!(
        env_file,
        Path::new(out["worktree"].as_str().unwrap()).join(".env")
    );
    let text = std::fs::read_to_string(&env_file).unwrap();
    assert!(text.contains("CARGO_BUILD_JOBS=7"), "{text}");
    assert!(text.contains("CADENCE_BUILD_SLOT="), "{text}");
    assert!(text.contains("cadence"), "{text}");
    // Created 0600 — the file may hold build secrets someday.
    use std::os::unix::fs::PermissionsExt;
    assert_eq!(
        std::fs::metadata(&env_file).unwrap().permissions().mode() & 0o777,
        0o600
    );
    // A second start is idempotent and keeps foreign lines — and an
    // existing file's mode survives the atomic rewrite.
    std::fs::write(&env_file, format!("OTHER=1\n{text}")).unwrap();
    std::fs::set_permissions(&env_file, std::fs::Permissions::from_mode(0o640)).unwrap();
    let (ok, _) = cli(&["issue", "start", "D-1"]);
    assert!(ok);
    let text = std::fs::read_to_string(&env_file).unwrap();
    assert_eq!(text.matches("CARGO_BUILD_JOBS=").count(), 1, "{text}");
    assert!(text.contains("OTHER=1"), "{text}");
    assert_eq!(
        std::fs::metadata(&env_file).unwrap().permissions().mode() & 0o777,
        0o640,
        "existing mode preserved"
    );
    drop(d);
}

/// `build-slot run` binds the hold to the REAL command process: the
/// CLI acquires with its own pid then execs, so the slot's holder IS
/// the running command — its exit frees the slot.
#[test]
fn build_slot_run_binds_the_real_process() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let mut child = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(&d.state)
        .args([
            "build-slot",
            "run",
            "build",
            "--wait-secs",
            "5",
            "--",
            "sleep",
            "30",
        ])
        .env("HOME", home.path())
        .envs(test_env().vars())
        .stderr(std::process::Stdio::null())
        .spawn()
        .unwrap();
    // After exec the spawned pid IS `sleep 30` — the hold must bind
    // to exactly that process, not a wrapper that already exited.
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        let s = d.rpc("slot_status", json!({"lane": "unknown"})).unwrap();
        let held = s["pools"]["build"]["held"].as_array().unwrap();
        if held
            .iter()
            .any(|h| h["pid"].as_u64() == Some(child.id() as u64))
        {
            break;
        }
        assert!(Instant::now() < deadline, "run never held the slot: {s}");
        thread::sleep(Duration::from_millis(50));
    }
    // The command's exit frees its slot on the next read.
    child.kill().unwrap();
    child.wait().unwrap();
    let s = d.rpc("slot_status", json!({"lane": "unknown"})).unwrap();
    assert!(
        s["pools"]["build"]["held"].as_array().unwrap().is_empty(),
        "the command's exit frees its slot: {s}"
    );
    // A short command exits cleanly through run.
    let out = cadence_at(
        home.path(),
        &d.state,
        &[
            "build-slot",
            "run",
            "build",
            "--wait-secs",
            "5",
            "--",
            "true",
        ],
    );
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
}

/// The CLI's queued path: `--wait-secs > 0` polls until a release
/// frees the pool — and `--pid` binds the hold to the named holder
/// (this test process, the CLI's parent).
#[test]
fn build_slot_cli_wait_then_grant() {
    let d = TestDaemon::start_opts(slot_opts(1, 1, 900, &[]));
    plant_self(&d);
    let home = TempDir::new().unwrap();
    let t1 = slot_acquire(&d, "build", SELF_LANE, "r1")["token"]
        .as_str()
        .unwrap()
        .to_string();
    let me = std::process::id().to_string();
    let cli = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(&d.state)
        .args([
            "build-slot",
            "acquire",
            "build",
            "--wait-secs",
            "15",
            "--lane",
            "dev-9",
            "--pid",
            &me,
        ])
        .env("HOME", home.path())
        .envs(test_env().vars())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .unwrap();
    // Let it queue — the waiter shows in status, then a release
    // frees the pool and the next poll grants.
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        let s = d.rpc("slot_status", json!({"lane": "dev-9"})).unwrap();
        if !s["waiting"].as_array().unwrap().is_empty() {
            break;
        }
        assert!(Instant::now() < deadline, "CLI never queued: {s}");
        thread::sleep(Duration::from_millis(50));
    }
    slot_release(&d, &t1, SELF_LANE, std::process::id());
    let out = cli.wait_with_output().unwrap();
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let token = String::from_utf8_lossy(&out.stdout).trim().to_string();
    assert!(token.starts_with("slot-"), "minted token: {token}");
    // The explicit --pid bound the hold to the named pid — the test
    // process, still alive. The CLI's `--lane dev-9` was advisory:
    // the derived lane is this pane's alias.
    let s = d.rpc("slot_status", json!({})).unwrap();
    let held = s["pools"]["build"]["held"].as_array().unwrap();
    assert_eq!(held[0]["pid"].as_u64().unwrap() as u32, std::process::id());
    assert_eq!(held[0]["lane"], SELF_LANE);
    slot_release(&d, &token, SELF_LANE, std::process::id());
}

/// `cadence <args>` from the operator's own shell ([`OperatorOutput`]).
fn cadence_bin_operator(state: &Path, args: &[&str]) -> std::process::Output {
    std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(state)
        .args(args)
        .operator_output()
        .unwrap()
}

/// Inherited defaults, explicit override, resume stability, and a mock
/// argv that receives the resolved model. No paid provider is launched.
#[test]
fn model_defaults_register_resume_and_mock_argv() {
    let d = TestDaemon::start();
    let mock = d.mock_claude("ok", None);
    let health = d.rpc("health", json!({})).unwrap();
    assert!(health["capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(|cap| cap == "model_defaults"));
    let cwd = d.dir.path().to_str().unwrap();
    let doc_a = r#"{"expected_revision":0,"config":{"schema":1,"providers":{"claude":{"default":{"mode":"model","model":"baseline-a"},"roles":{"qa":{"mode":"model","model":"qa-model"},"dev":{"mode":"provider_default"}}}}}}"#;
    d.operator_rpc("model_defaults_set", json!({"document": doc_a}))
        .unwrap();

    let conflict = cadence_bin_operator(
        &d.state,
        &[
            "agent",
            "register",
            "nope",
            "--provider",
            "claude",
            "--endpoint",
            "managed",
            "--cwd",
            cwd,
            "--param",
            "model=sonnet",
            "--provider-default-model",
        ],
    );
    assert!(
        !conflict.status.success(),
        "explicit model and provider-default must conflict"
    );
    assert!(
        String::from_utf8_lossy(&conflict.stderr).contains("provider-default-model"),
        "{}",
        String::from_utf8_lossy(&conflict.stderr)
    );
    let unsupported = cadence_bin_operator(
        &d.state,
        &[
            "agent",
            "register",
            "d1",
            "--provider",
            "devin",
            "--endpoint",
            "pty",
            "--cwd",
            cwd,
            "--provider-default-model",
        ],
    );
    assert!(!unsupported.status.success());
    assert!(String::from_utf8_lossy(&unsupported.stderr).contains("does not accept a model"));

    d.rpc(
        "agent_register",
        json!({"alias": "pm", "provider": "fake", "endpoint_kind": "fake", "cwd": cwd, "role": "pm"}),
    )
    .unwrap();
    let joined = cadence_bin_operator(
        &d.state,
        &[
            "join",
            "pm",
            "claude",
            "--alias",
            "qa-cli",
            "--team-role",
            "qa",
            "--detach",
            "--no-bootstrap",
        ],
    );
    assert!(
        joined.status.success(),
        "{}",
        String::from_utf8_lossy(&joined.stderr)
    );
    d.wait_agent("qa-cli", "idle", 20);
    d.rpc(
        "agent_send",
        json!({"alias": "qa-cli", "text": "boot", "message": "m-qa"}),
    )
    .unwrap();
    d.wait_message("qa-cli", "m-qa", &["completed"], 20);
    let argv_file = mock.pidfile.with_extension("pid.argv");
    let argv = std::fs::read_to_string(&argv_file).unwrap();
    assert!(argv.contains("--model\nqa-model"), "{argv}");
    assert!(
        !argv.contains("team_role") && !argv.contains("devops"),
        "{argv}"
    );
    let qa = d.rpc("agent_show", json!({"alias": "qa-cli"})).unwrap()["agent"].clone();
    assert_eq!(qa["role"], "worker");
    assert_eq!(qa["team_role"], "qa");
    assert_eq!(qa["model_selection"]["source"], "role_default");
    assert_eq!(qa["model_selection"]["model"], "qa-model");
    assert_eq!(qa["model_configured"], "qa-model");
    assert_eq!(qa["model_reported"], "mock-claude");
    assert_ne!(qa["model_configured"], qa["model_reported"]);

    let explicit = cadence_bin_operator(
        &d.state,
        &[
            "agent",
            "register",
            "explicit",
            "--provider",
            "claude",
            "--endpoint",
            "managed",
            "--cwd",
            cwd,
            "--team-role",
            "qa",
            "--param",
            "model=explicit-model",
        ],
    );
    assert!(
        explicit.status.success(),
        "{}",
        String::from_utf8_lossy(&explicit.stderr)
    );
    d.wait_agent("explicit", "idle", 20);
    d.rpc(
        "agent_send",
        json!({"alias": "explicit", "text": "boot", "message": "m-ex"}),
    )
    .unwrap();
    d.wait_message("explicit", "m-ex", &["completed"], 20);
    let argv = std::fs::read_to_string(&argv_file).unwrap();
    assert!(argv.contains("--model\nexplicit-model"), "{argv}");
    let shown = d.rpc("agent_show", json!({"alias": "explicit"})).unwrap();
    assert_eq!(shown["agent"]["model_selection"]["source"], "explicit");
    assert!(shown["agent"]["model_selection"]["revision"].is_null());

    let doc_b = r#"{"expected_revision":1,"config":{"schema":1,"providers":{"claude":{"default":{"mode":"model","model":"baseline-b"},"roles":{}}}}}"#;
    d.operator_rpc("model_defaults_set", json!({"document": doc_b}))
        .unwrap();
    d.rpc("agent_stop", json!({"alias": "qa-cli"})).unwrap();
    d.rpc("agent_resume", json!({"alias": "qa-cli"})).unwrap();
    d.wait_agent("qa-cli", "idle", 20);
    d.rpc(
        "agent_send",
        json!({"alias": "qa-cli", "text": "again", "message": "m-resume"}),
    )
    .unwrap();
    d.wait_message("qa-cli", "m-resume", &["completed"], 20);
    let argv = std::fs::read_to_string(&argv_file).unwrap();
    assert!(argv.contains("--model\nqa-model"), "{argv}");
    assert!(!argv.contains("baseline-b"), "{argv}");

    d.rpc(
        "agent_register",
        json!({"alias": "fresh", "provider": "claude", "endpoint_kind": "managed", "cwd": cwd, "role": "worker"}),
    )
    .unwrap();
    d.wait_agent("fresh", "idle", 20);
    d.rpc(
        "agent_send",
        json!({"alias": "fresh", "text": "boot", "message": "m-fresh"}),
    )
    .unwrap();
    d.wait_message("fresh", "m-fresh", &["completed"], 20);
    let argv = std::fs::read_to_string(&argv_file).unwrap();
    assert!(argv.contains("--model\nbaseline-b"), "{argv}");

    d.operator_rpc(
        "agent_set",
        json!({"alias": "fresh", "next_launch": true, "patch": {"model": null}}),
    )
    .unwrap();
    let cleared = d.rpc("agent_show", json!({"alias": "fresh"})).unwrap()["agent"].clone();
    assert!(cleared["params"].get("model").is_none() || cleared["params"]["model"].is_null());
    assert_eq!(
        cleared["model_selection"]["source"],
        "explicit_provider_default"
    );
    d.rpc("agent_stop", json!({"alias": "fresh"})).unwrap();
    d.rpc("agent_resume", json!({"alias": "fresh"})).unwrap();
    d.wait_agent("fresh", "idle", 20);
    d.rpc(
        "agent_send",
        json!({"alias": "fresh", "text": "native", "message": "m-native"}),
    )
    .unwrap();
    d.wait_message("fresh", "m-native", &["completed"], 20);
    let argv = std::fs::read_to_string(&argv_file).unwrap();
    assert!(!argv.contains("--model"), "{argv}");

    d.rpc(
        "agent_register",
        json!({"alias": "box", "provider": "inbox", "endpoint_kind": "inbox", "team_role": "ops"}),
    )
    .unwrap();
    let inbox = d.rpc("agent_show", json!({"alias": "box"})).unwrap()["agent"].clone();
    assert!(inbox["model_selection"].is_null());
    assert!(inbox["model_configured"].is_null());
    assert_eq!(inbox["team_role"], "devops");
    assert_eq!(inbox["role"], "worker");

    let again = d.rpc(
        "agent_register",
        json!({"alias": "qa-cli", "provider": "claude", "endpoint_kind": "managed", "cwd": cwd, "team_role": "dev"}),
    );
    assert!(again.unwrap_err().to_string().contains("UNIQUE"));
    assert_eq!(
        d.rpc("agent_show", json!({"alias": "qa-cli"})).unwrap()["agent"]["params"]["model"],
        "qa-model"
    );
}

/// CAD-337: model defaults decide the model every agent launches with,
/// so `model_defaults_set` is operator authority on POSITIVE proof, the
/// same gate as `slot_reconcile` and approval evidence. A pane and a
/// managed agent's own process are refused naming the rule; the audit
/// attribution is the verified connection's, and a request that tries
/// to supply one is refused rather than read. Nothing refused lands.
#[test]
fn model_defaults_set_is_operator_only() {
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    let mut pane = LaneShell::spawn(home.path());
    plant_pane(&d, "pane-1", pane.pid());
    let mut wk = ManagedWorker::start(&d, "wk");
    let doc = r#"{"expected_revision":0,"config":{"schema":1,"providers":{"claude":{"default":{"mode":"model","model":"forged-model"},"roles":{}}}}}"#;
    let params = json!({"document": doc});
    let refused = |r: &Value, route: &str, who: &str| {
        assert_eq!(r["ok"], false, "{route}: {r}");
        let msg = r["error"]["message"].as_str().unwrap_or_default();
        assert!(
            msg.contains("model defaults set is an operator action") && msg.contains(who),
            "{route}: {r}"
        );
    };

    let r = pane.rpc(&d.state, "model_defaults_set", params.clone());
    refused(&r, "pane", "pane-1");
    let r = wk.rpc("self", "model_defaults_set", params.clone());
    refused(&r, "managed agent", "wk");
    // Deriving no agent identity is not operator proof: a detach off
    // the managed tool still carries its alias.
    let r = wk.rpc("detached", "model_defaults_set", params.clone());
    refused(&r, "managed detach", "not provably the operator");

    // Attribution is connection-bound: even the operator cannot name
    // who made the change.
    for field in ["attribution", "by", "actor"] {
        let mut forged = params.clone();
        forged[field] = json!("somebody-else");
        let err = d.operator_rpc("model_defaults_set", forged).unwrap_err();
        assert!(
            err.to_string().contains(&format!("'{field}'")),
            "{field}: {err}"
        );
    }
    let snap = d.rpc("model_defaults_get", json!({})).unwrap();
    assert_eq!(
        snap["revision"], 0,
        "no refused caller changed defaults: {snap}"
    );

    let snap = d.operator_rpc("model_defaults_set", params).unwrap();
    assert_eq!(snap["revision"], 1, "{snap}");
    let conn = rusqlite::Connection::open(d.state.join("cadence.sqlite3")).unwrap();
    let payloads: Vec<String> = conn
        .prepare("SELECT payload FROM events WHERE kind='model_defaults_updated'")
        .unwrap()
        .query_map([], |row| row.get(0))
        .unwrap()
        .collect::<rusqlite::Result<_>>()
        .unwrap();
    assert_eq!(payloads.len(), 1, "{payloads:?}");
    let audit: Value = serde_json::from_str(&payloads[0]).unwrap();
    assert_eq!(audit["attribution"], "operator", "{audit}");
    assert_eq!(audit["transport"], "operator-connection", "{audit}");
}

/// The wire frame is a refusal whose message names `verb` and `rule`.
fn assert_refused(frame: &Value, verb: &str, rule: &str, what: &str) {
    assert_eq!(frame["ok"], false, "{what}: {frame}");
    let msg = frame["error"]["message"].as_str().unwrap_or_default();
    assert!(
        msg.contains(verb) && msg.contains(rule),
        "{what}: expected '{verb}' + '{rule}' in {frame}"
    );
}

/// A pane's claimed identity, in every field a caller could forge.
const FORGED_IDENTITY: &[(&str, &str)] = &[
    ("pane", "operator"),
    ("by", "operator"),
    ("reviewer", "operator"),
    ("owner", "operator"),
];

/// `params` with `field` claiming `value`.
fn forged(params: &Value, field: &str, value: &str) -> Value {
    let mut p = params.clone();
    p[field] = json!(value);
    p
}

/// CAD-373 / CAD-374: `monitor stop`, `monitor dispatch`, `message
/// reconcile` and `agent unfence` are operator actions decided by the
/// CONNECTION (`operator_connection`), never by a `pane`/`by` field the
/// caller controls; `job task reopen` refuses every agent that is not
/// the job's PM (its own test below). A pane agent speaking the
/// socket directly — even the fenced worker's own PM, even forging
/// `by:"operator"` or an empty `pane` — and a managed endpoint are
/// refused naming the verb and the rule; nothing lands. The proven
/// operator still succeeds, and reconcile records `by:"operator"`.
#[test]
fn operator_verbs_refuse_agents_whatever_they_claim() {
    let d = TestDaemon::start_opts(slot_opts(2, 1, 900, &[]));
    let home = TempDir::new().unwrap();
    // `lead` is a PM pane: w2 is its member, fenced by an unknown.
    let mut lead = LaneShell::spawn(home.path());
    plant_pane(&d, "lead", lead.pid());
    d.register_member("w2", "lead");
    d.wait_agent("w2", "idle", 10);
    fence_agent(&d, "w2", "x9");
    let mut wk = ManagedWorker::start(&d, "wk");

    // A blocked task (reopen) and a monitor over it (stop, dispatch).
    d.register("pm");
    d.register_member("w1", "pm");
    d.wait_agent("w1", "idle", 10);
    let (spec, sha) = d.spec_file("spec.md", "gated verbs");
    let project = d.dir.path().to_str().unwrap().to_string();
    d.rpc(
        "job_new",
        json!({"pm": "pm", "job": "j1", "spec": spec, "spec_sha256": sha,
               "repo": project}),
    )
    .unwrap();
    d.rpc(
        "task_new",
        json!({"job": "j1", "task": "j1-t", "assignee": "w1",
               "acceptance": format!("ok REPORT_SHA:{SHA_A}")}),
    )
    .unwrap();
    d.job_dispatch("j1-t", json!({})).unwrap();
    d.wait_task("j1-t", "review", 15);
    d.job_verdict("j1-t", SHA_A, "blocked").unwrap();
    assert_eq!(d.task_state("j1-t"), "blocked");
    d.rpc(
        "monitor_register",
        json!({"monitor": "m1", "project": project, "owner": "operator",
               "tasks": ["j1-t"], "interval_secs": 60, "dispatch_enabled": true}),
    )
    .unwrap();

    let r = lead.rpc(&d.state, "task_reopen", json!({"task": "j1-t"}));
    assert_refused(&r, "job task reopen", "not job 'j1''s PM", "pane reopen");
    let r = wk.rpc("self", "task_reopen", json!({"task": "j1-t"}));
    assert_refused(&r, "job task reopen", "not job 'j1''s PM", "managed reopen");
    let calls = [
        ("monitor_stop", "monitor stop", json!({"monitor": "m1"})),
        (
            "monitor_dispatch",
            "monitor dispatch",
            json!({"monitor": "m1", "task": "j1-t"}),
        ),
        (
            "message_reconcile",
            "message reconcile",
            json!({"message": "x9", "status": "completed", "sha": SHA_B}),
        ),
        (
            "agent_unfence",
            "agent unfence",
            json!({"alias": "w2", "status": "completed"}),
        ),
    ];
    for (method, verb, params) in &calls {
        let r = lead.rpc(&d.state, method, params.clone());
        assert_refused(&r, verb, "is an operator action", &format!("pane {method}"));
        assert!(
            r["error"]["message"].as_str().unwrap().contains("'lead'"),
            "{method}: {r}"
        );
        for (field, value) in FORGED_IDENTITY {
            let r = lead.rpc(&d.state, method, forged(params, field, value));
            assert_eq!(r["ok"], false, "pane {method} forging {field}: {r}");
            assert!(
                r["error"]["message"].as_str().unwrap().contains(verb),
                "pane {method} forging {field}: {r}"
            );
        }
        let r = wk.rpc("self", method, params.clone());
        assert_refused(
            &r,
            verb,
            "is an operator action",
            &format!("managed {method}"),
        );
    }
    // Nothing a refused caller sent landed.
    assert_eq!(d.task_state("j1-t"), "blocked");
    wait_monitor_state(&d, "m1", "active", 5);
    assert_eq!(d.message_state("w2", "x9"), "unknown");
    assert_eq!(
        d.rpc("agent_show", json!({"alias": "w2"})).unwrap()["unknown"],
        1
    );

    // The proven operator still acts, and is who the record names.
    d.operator_rpc("task_reopen", json!({"task": "j1-t"}))
        .unwrap();
    assert_eq!(d.task_state("j1-t"), "draft");
    d.operator_rpc("monitor_stop", json!({"monitor": "m1"}))
        .unwrap();
    let r = d
        .operator_rpc(
            "message_reconcile",
            json!({"message": "x9", "status": "interrupted"}),
        )
        .unwrap();
    assert_eq!(r["message"]["state"], "interrupted", "{r}");
    let rec = d
        .events("w2")
        .into_iter()
        .find(|e| e["kind"] == "reconciled")
        .expect("reconciled event");
    assert_eq!(rec["payload"]["by"], "operator", "{rec}");
}

/// CAD-375 (review R1): the withholding is one filter over every answer,
/// so it covers the read paths beyond `agent_show`: job and task views
/// (the kickoff's `turn_id`), the agent's thread and its message rows
/// (a body quoting the token), events, and a pane capture showing it —
/// and it holds while the generation is cleared, as in a hot restart's
/// window before adoption restores it.
#[test]
fn turn_tokens_are_withheld_on_every_read_path() {
    let d = TestDaemon::start();
    let mock = d.mock_devin();
    d.register("pm");
    d.fixture_rpc(
        "agent_register",
        json!({"alias": "dv1", "provider": "devin", "endpoint_kind": "pty",
               "cwd": d.dir.path().to_str().unwrap(),
               "params": json!({"upstream": "pm"}).to_string()}),
    )
    .unwrap();
    d.wait_agent("dv1", "idle", 20);
    let (spec, sha) = d.spec_file("spec.md", "token reads");
    d.job_new("pm", "j1", &spec, &sha);
    d.rpc(
        "task_new",
        json!({"job": "j1", "task": "j1-t", "assignee": "dv1", "acceptance": "ok"}),
    )
    .unwrap();
    d.rpc("agent_ready", json!({"alias": "dv1"})).unwrap();
    let kickoff = d.job_dispatch("j1-t", json!({})).unwrap()["message"]
        .as_str()
        .unwrap()
        .to_string();
    let token = pty_token(&d, "dv1", &kickoff);
    // Prose quoting it: a queued chat message (row + thread entry) and the
    // pane's screen, as if the worker printed `cadence self`.
    d.rpc(
        "thread_send",
        json!({"alias": "dv1", "text": format!("report with {token}"), "message": "q1"}),
    )
    .unwrap();
    let screen = d.pane_file(&mock, "dv1", "screen");
    let shown = std::fs::read_to_string(&screen).unwrap_or_default();
    atomic_write(
        screen.clone(),
        format!("{shown}\nrunning: {kickoff} {token}\n"),
    );

    let reads = [
        ("agent_show", json!({"alias": "dv1"})),
        ("agent_list", json!({})),
        ("agent_events", json!({"alias": "dv1"})),
        ("job_show", json!({"job": "j1"})),
        ("task_show", json!({"task": "j1-t"})),
        ("thread_read", json!({"alias": "dv1"})),
        ("agent_capture", json!({"alias": "dv1"})),
    ];
    let check = |when: &str| {
        for (method, params) in &reads {
            let r = d.rpc(method, params.clone()).unwrap();
            assert!(!r.to_string().contains(&token), "{when} {method}: {r}");
        }
    };
    check("live");
    let capture = d.rpc("agent_capture", json!({"alias": "dv1"})).unwrap();
    assert!(
        capture["capture"]
            .as_str()
            .unwrap()
            .contains("[turn token withheld]"),
        "{capture}"
    );
    let thread = d.rpc("thread_read", json!({"alias": "dv1"})).unwrap();
    assert!(
        thread
            .to_string()
            .contains("report with [turn token withheld]"),
        "{thread}"
    );
    let task = d.rpc("task_show", json!({"task": "j1-t"})).unwrap();
    assert!(task["task"]["kickoff"]["turn_id"].is_null(), "{task}");

    // The restart window: no generation, the turn still running.
    let conn = rusqlite::Connection::open(d.state.join("cadence.sqlite3")).unwrap();
    let generation: String = conn
        .query_row("SELECT generation FROM agents WHERE alias='dv1'", [], |r| {
            r.get(0)
        })
        .unwrap();
    conn.execute("UPDATE agents SET generation=NULL WHERE alias='dv1'", [])
        .unwrap();
    check("no generation");
    conn.execute(
        "UPDATE agents SET generation=?1 WHERE alias='dv1'",
        [&generation],
    )
    .unwrap();
}

/// CAD-373: `job task reopen` is the proven operator's or the job's own
/// PM's (the cadence skill tells PMs to run it) — decided by the
/// connection. The task's assignee, a peer worker and another group's
/// PM are refused, forged identity fields or not; the job's PM pane
/// reopens it and is who the record names.
#[test]
fn task_reopen_is_the_operator_or_the_jobs_pm() {
    let d = TestDaemon::start();
    let home = TempDir::new().unwrap();
    let mut pm = LaneShell::spawn(home.path());
    plant_pane(&d, "pm", pm.pid());
    d.register_member("w1", "pm");
    d.wait_agent("w1", "idle", 10);
    let (spec, sha) = d.spec_file("spec.md", "reopen rule");
    d.job_new("pm", "j1", &spec, &sha);
    for task in ["j1-a", "j1-b"] {
        d.rpc(
            "task_new",
            json!({"job": "j1", "task": task, "assignee": "w1",
                   "acceptance": format!("ok REPORT_SHA:{SHA_A}")}),
        )
        .unwrap();
        d.job_dispatch(task, json!({})).unwrap();
        d.wait_task(task, "review", 15);
        d.job_verdict(task, SHA_A, "blocked").unwrap();
    }
    d.rpc("agent_stop", json!({"alias": "w1"})).unwrap();
    d.wait_agent("w1", "stopped", 15);
    let mut worker = LaneShell::spawn(home.path());
    plant_pane(&d, "w1", worker.pid());
    let mut peer = LaneShell::spawn(home.path());
    plant_pane(&d, "w9", peer.pid());
    let mut other_pm = LaneShell::spawn(home.path());
    plant_pane(&d, "pm2", other_pm.pid());

    let reopen = json!({"task": "j1-a"});
    for (shell, who, rule) in [
        (&mut worker, "assignee", "is the task's assignee"),
        (&mut peer, "peer", "is not job 'j1''s PM"),
        (&mut other_pm, "other PM", "is not job 'j1''s PM"),
    ] {
        let r = shell.rpc(&d.state, "task_reopen", reopen.clone());
        assert_refused(&r, "job task reopen", rule, who);
        for (field, value) in FORGED_IDENTITY
            .iter()
            .chain(&[("by", "pm"), ("pane", "pm")])
        {
            let r = shell.rpc(&d.state, "task_reopen", forged(&reopen, field, value));
            // Refused either for the field itself or, for a field the
            // gate does not list (`owner`), by the caller rule.
            assert_refused(
                &r,
                "job task reopen",
                "",
                &format!("{who} forging {field}={value}"),
            );
        }
    }
    // The PM itself cannot name someone else either.
    let r = pm.rpc(&d.state, "task_reopen", forged(&reopen, "by", "operator"));
    assert_refused(
        &r,
        "job task reopen",
        "'by' is not accepted",
        "pm forging by",
    );
    assert_eq!(d.task_state("j1-a"), "blocked");

    // The job's PM pane reopens, recorded as itself; so does the operator.
    let r = pm.rpc(&d.state, "task_reopen", reopen);
    assert_eq!(r["ok"], true, "{r}");
    assert_eq!(d.task_state("j1-a"), "draft");
    d.operator_rpc("task_reopen", json!({"task": "j1-b"}))
        .unwrap();
    assert_eq!(d.task_state("j1-b"), "draft");
    let by: Vec<Value> = d
        .events("pm")
        .into_iter()
        .filter(|e| e["kind"] == "task_reopened")
        .map(|e| e["payload"]["by"].clone())
        .collect();
    assert_eq!(by, vec![json!("pm"), json!("operator")], "{by:?}");
}

/// CAD-372: the verdict's reviewer is the verified connection. The
/// assignee's own pane cannot pass its task — not bare, not claiming
/// `reviewer:"operator"` or another agent, not naming a `pane` — and a
/// distinct agent's pane passes it, recorded as that agent.
#[test]
fn verdict_reviewer_is_the_verified_caller() {
    let d = TestDaemon::start();
    d.register("pm");
    d.register_member("w1", "pm");
    d.wait_agent("w1", "idle", 10);
    let (spec, sha) = d.spec_file("spec.md", "self review");
    d.job_new("pm", "j1", &spec, &sha);
    d.rpc(
        "task_new",
        json!({"job": "j1", "task": "j1-t", "assignee": "w1",
               "acceptance": format!("ok REPORT_SHA:{SHA_A}")}),
    )
    .unwrap();
    d.job_dispatch("j1-t", json!({})).unwrap();
    d.wait_task("j1-t", "review", 15);
    // The worker's pane from here on: its own processes derive `w1`.
    d.rpc("agent_stop", json!({"alias": "w1"})).unwrap();
    d.wait_agent("w1", "stopped", 15);
    let home = TempDir::new().unwrap();
    let mut worker = LaneShell::spawn(home.path());
    plant_pane(&d, "w1", worker.pid());
    let mut qa = LaneShell::spawn(home.path());
    plant_pane(&d, "qa", qa.pid());

    let pass = json!({"task": "j1-t", "sha": SHA_A, "verdict": "pass"});
    let r = worker.rpc(&d.state, "task_verdict", pass.clone());
    assert_refused(&r, "job verdict", "assignee", "assignee bare");
    for (field, value) in [
        ("reviewer", "operator"),
        ("reviewer", "qa"),
        ("pane", "qa"),
        ("by", "qa"),
    ] {
        let r = worker.rpc(&d.state, "task_verdict", forged(&pass, field, value));
        assert_refused(
            &r,
            "job verdict",
            "caller identity is connection-bound",
            &format!("assignee claiming {field}={value}"),
        );
    }
    // The CLI from the worker's pane: same refusal, nothing recorded.
    let (rc, out) = worker.cadence(
        &d.state,
        &format!("job verdict j1-t --sha {SHA_A} --pass --no-verify-worktree --no-status"),
    );
    assert_ne!(rc, 0, "{out}");
    assert!(out.contains("assignee"), "{out}");
    assert_eq!(d.task_state("j1-t"), "review");
    assert_eq!(task_verdicts(&d, "j1-t"), json!([]));

    // A distinct verified reviewer passes it, and is who is recorded.
    let r = qa.rpc(&d.state, "task_verdict", pass);
    assert_eq!(r["ok"], true, "{r}");
    assert_eq!(d.task_state("j1-t"), "verified");
    let verdicts = task_verdicts(&d, "j1-t");
    assert_eq!(verdicts[0]["reviewer"], "qa", "{verdicts}");
    let recorded = d
        .events("pm")
        .into_iter()
        .find(|e| e["kind"] == "verdict_recorded")
        .expect("verdict_recorded");
    assert_eq!(recorded["payload"]["reviewer"], "qa", "{recorded}");
    assert_eq!(recorded["payload"]["pane"], "qa", "{recorded}");
}

/// CAD-370: a brokered request is answered by the operator or the
/// requester's own PM — never by the requesting agent itself (that
/// would defeat the broker), never by a peer, whatever it claims. A
/// refused answer leaves the request pending.
#[test]
fn agent_respond_refuses_the_requester_and_its_peers() {
    let d = TestDaemon::start();
    let home = TempDir::new().unwrap();
    let mut pm = LaneShell::spawn(home.path());
    plant_pane(&d, "lead", pm.pid());
    let mut worker = LaneShell::spawn(home.path());
    plant_pane(&d, "wr", worker.pid());
    let mut peer = LaneShell::spawn(home.path());
    plant_pane(&d, "wp", peer.pid());
    let brokered = json!({"upstream": "lead", "broker_approvals": true}).to_string();
    for alias in ["wr", "wp"] {
        cad162_sql(
            &d,
            "UPDATE agents SET params=?1 WHERE alias=?2",
            &[&brokered, alias],
        );
    }
    // The requester's own connection opens its requests (CAD-376).
    let open = |worker: &mut LaneShell, handle: &str| {
        let r = worker.rpc(
            &d.state,
            "request_open",
            json!({"alias": "wr", "tool": "Bash", "input_summary": "rm -rf /tmp/x",
                   "request": handle}),
        );
        assert_eq!(r["ok"], true, "{r}");
    };
    open(&mut worker, "h1");
    let accept = json!({"alias": "wr", "request": "h1", "decision": "accept"});

    let r = worker.rpc(&d.state, "agent_respond", accept.clone());
    assert_refused(
        &r,
        "agent respond",
        "cannot answer its own request",
        "requester",
    );
    for (field, value) in FORGED_IDENTITY {
        let r = worker.rpc(&d.state, "agent_respond", forged(&accept, field, value));
        assert_eq!(r["ok"], false, "requester forging {field}: {r}");
        assert!(
            r["error"]["message"]
                .as_str()
                .unwrap()
                .contains("agent respond"),
            "requester forging {field}: {r}"
        );
    }
    let r = peer.rpc(&d.state, "agent_respond", accept.clone());
    assert_refused(
        &r,
        "agent respond",
        "cannot answer another agent's request",
        "peer",
    );
    let pending = d.rpc("agent_requests", json!({"alias": "wr"})).unwrap();
    assert_eq!(pending["requests"][0]["request"], "h1", "{pending}");

    // The requester's PM answers; so does the operator.
    let r = pm.rpc(&d.state, "agent_respond", accept);
    assert_eq!(r["ok"], true, "{r}");
    open(&mut worker, "h2");
    d.operator_rpc(
        "agent_respond",
        json!({"alias": "wr", "request": "h2", "decision": "decline"}),
    )
    .unwrap();
    let pending = d.rpc("agent_requests", json!({"alias": "wr"})).unwrap();
    assert_eq!(pending["requests"], json!([]), "{pending}");
}

/// CAD-376: a brokered request handle belongs to its agent's own
/// permission server. Another agent (even a group peer) and a
/// connection with no agent identity can neither open a request on a
/// brokered agent — nothing is parked, no `waiting_input` — nor close
/// or await one, which would retire or consume it as a denial; the
/// handle stays pending and the owner still opens, awaits and closes
/// normally.
#[test]
fn brokered_request_handles_belong_to_their_agent() {
    let d = TestDaemon::start();
    let home = TempDir::new().unwrap();
    let mut pm = LaneShell::spawn(home.path());
    plant_pane(&d, "lead", pm.pid());
    let mut owner = LaneShell::spawn(home.path());
    plant_pane(&d, "wr", owner.pid());
    let mut peer = LaneShell::spawn(home.path());
    plant_pane(&d, "wp", peer.pid());
    let brokered = json!({"upstream": "lead", "broker_approvals": true}).to_string();
    for alias in ["wr", "wp"] {
        cad162_sql(
            &d,
            "UPDATE agents SET params=?1, state='busy' WHERE alias=?2",
            &[&brokered, alias],
        );
    }
    let state = |alias: &str| {
        d.rpc("agent_show", json!({"alias": alias})).unwrap()["agent"]["state"]
            .as_str()
            .unwrap()
            .to_string()
    };
    let opened = |alias: &str| {
        d.events(alias)
            .iter()
            .filter(|e| e["kind"] == "request_opened")
            .count()
    };
    let open = |handle: &str| {
        json!({"alias": "wr", "kind": "approval", "tool": "Bash",
               "input_summary": "rm -rf /tmp/x", "request": handle})
    };

    // A fake open on the brokered agent: refused from a peer's pane,
    // with forged identity fields, and from a connection that is no
    // agent. The target stays busy with nothing pending.
    let r = peer.rpc(&d.state, "request_open", open("h1"));
    assert_refused(&r, "request_open", "cannot act on 'wr''s", "peer open");
    for (field, value) in [("by", "wr"), ("pane", "wr"), ("actor", "wr")] {
        let r = peer.rpc(&d.state, "request_open", forged(&open("h1"), field, value));
        assert_refused(&r, "request_open", "connection-bound", field);
    }
    let err = d.rpc("request_open", open("h1")).unwrap_err().to_string();
    assert!(
        err.contains("request_open refused") && err.contains("no agent identity"),
        "{err}"
    );
    assert!(d.requests("wr").is_empty());
    assert_eq!(state("wr"), "busy");
    assert_eq!(opened("wr"), 0);

    // The owner's own connection opens it and parks itself; its retry
    // of the same handle dedupes.
    let r = owner.rpc(&d.state, "request_open", open("h1"));
    assert_eq!(r["ok"], true, "{r}");
    assert_eq!(state("wr"), "waiting_input");
    let r = owner.rpc(&d.state, "request_open", open("h1"));
    assert_eq!(r["result"]["existing"], true, "{r}");
    assert_eq!(d.requests("wr").len(), 1);
    assert_eq!(opened("wr"), 1);

    // A peer's close or wait is refused and the handle stays pending;
    // so is one from a connection that is no agent.
    let h1 = json!({"request": "h1"});
    let r = peer.rpc(&d.state, "request_close", h1.clone());
    assert_refused(&r, "request_close", "cannot act on 'wr''s", "peer close");
    let r = peer.rpc(
        &d.state,
        "request_wait",
        json!({"request": "h1", "wait": 1}),
    );
    assert_refused(&r, "request_wait", "cannot act on 'wr''s", "peer wait");
    let err = d.rpc("request_close", h1.clone()).unwrap_err().to_string();
    assert!(err.contains("request_close refused"), "{err}");
    assert_eq!(d.requests("wr")[0]["request"], "h1");
    assert_eq!(state("wr"), "waiting_input");
    let closed = d.events("wr").iter().any(|e| e["kind"] == "request_closed");
    assert!(!closed, "a refused close must not retire the handle");

    // Once the PM answers, the parked answer is the owner's alone: a
    // peer can neither take it by waiting nor discard it by closing.
    let r = pm.rpc(
        &d.state,
        "agent_respond",
        json!({"alias": "wr", "request": "h1", "decision": "accept"}),
    );
    assert_eq!(r["ok"], true, "{r}");
    let r = peer.rpc(
        &d.state,
        "request_wait",
        json!({"request": "h1", "wait": 1}),
    );
    assert_refused(
        &r,
        "request_wait",
        "cannot act on 'wr''s",
        "peer takes answer",
    );
    let r = peer.rpc(&d.state, "request_close", h1.clone());
    assert_refused(
        &r,
        "request_close",
        "cannot act on 'wr''s",
        "peer drops answer",
    );
    let r = owner.rpc(
        &d.state,
        "request_wait",
        json!({"request": "h1", "wait": 1}),
    );
    assert_eq!(r["result"]["state"], "answered", "{r}");
    assert_eq!(r["result"]["answer"]["decision"], "accept", "{r}");

    // The owner retires its own abandoned request normally.
    let r = owner.rpc(&d.state, "request_open", open("h2"));
    assert_eq!(r["ok"], true, "{r}");
    assert_eq!(state("wr"), "waiting_input");
    let r = owner.rpc(&d.state, "request_close", json!({"request": "h2"}));
    assert_eq!(r["result"]["state"], "closed", "{r}");
    assert!(d.requests("wr").is_empty());
    assert_eq!(state("wr"), "busy");
    d.wait_event("wr", "request_closed", 5);
}

/// CAD-452: an answered request's handle stays its agent's until the
/// agent's wait collects the answer. `agent respond` parks the answer
/// and drops the pending entry, and handles are visible to peers
/// (`agent requests`, the `request_opened` event) — so a brokered
/// peer re-opening the handle under its own alias in that gap would
/// own it, the owner's wait would be refused, and the operator's
/// accept would reach the provider as a deny. The squat is refused
/// and records nothing; the owner's retry and wait still collect the
/// accept.
#[test]
fn an_answered_handle_cannot_be_squatted_before_its_wait() {
    let d = TestDaemon::start();
    let home = TempDir::new().unwrap();
    let mut pm = LaneShell::spawn(home.path());
    plant_pane(&d, "lead", pm.pid());
    let mut owner = LaneShell::spawn(home.path());
    plant_pane(&d, "wr", owner.pid());
    let mut peer = LaneShell::spawn(home.path());
    plant_pane(&d, "wp", peer.pid());
    let brokered = json!({"upstream": "lead", "broker_approvals": true}).to_string();
    for alias in ["wr", "wp"] {
        cad162_sql(
            &d,
            "UPDATE agents SET params=?1, state='busy' WHERE alias=?2",
            &[&brokered, alias],
        );
    }
    let open = |alias: &str| {
        json!({"alias": alias, "kind": "approval", "tool": "Bash",
               "input_summary": "rm -rf /tmp/x", "request": "h1"})
    };
    let r = owner.rpc(&d.state, "request_open", open("wr"));
    assert_eq!(r["ok"], true, "{r}");
    let r = pm.rpc(
        &d.state,
        "agent_respond",
        json!({"alias": "wr", "request": "h1", "decision": "accept"}),
    );
    assert_eq!(r["ok"], true, "{r}");
    // The handle is public: the peer read it from the owner's event.
    assert!(d
        .events("wr")
        .iter()
        .any(|e| e["kind"] == "request_opened" && e["payload"]["request"] == "h1"));

    // The squat: the peer opens the parked handle as its own request.
    let r = peer.rpc(&d.state, "request_open", open("wp"));
    assert_refused(&r, "request_open", "answer parked for 'wr'", "squat");
    assert!(d.requests("wp").is_empty());
    let wp = d.rpc("agent_show", json!({"alias": "wp"})).unwrap();
    assert_eq!(wp["agent"]["state"], "busy", "{wp}");
    assert!(!d.events("wp").iter().any(|e| e["kind"] == "request_opened"));

    // The owner's retried open of its answered handle dedupes without
    // re-pending it, and its wait collects the operator's accept.
    let r = owner.rpc(&d.state, "request_open", open("wr"));
    assert_eq!(r["result"]["existing"], true, "{r}");
    assert!(d.requests("wr").is_empty());
    let r = owner.rpc(
        &d.state,
        "request_wait",
        json!({"request": "h1", "wait": 1}),
    );
    assert_eq!(r["result"]["state"], "answered", "{r}");
    assert_eq!(r["result"]["answer"]["decision"], "accept", "{r}");
}

/// CAD-375: a running turn's token is `message_report`'s credential, so
/// the daemon shows it only to the connection that derives the owning
/// agent. A peer's (and the operator's) `agent_show`, `agent_list` and
/// `agent_events` of the agent carry no token anywhere; the agent's own
/// `cadence self` prints it and its `message ack`/`result` still work.
#[test]
fn turn_tokens_are_shown_only_to_the_owning_connection() {
    let d = TestDaemon::start();
    let home = TempDir::new().unwrap();
    let mut owner = LaneShell::spawn(home.path());
    plant_pane(&d, "wa", owner.pid());
    let mut peer = LaneShell::spawn(home.path());
    plant_pane(&d, "wb", peer.pid());
    // A pty worker's delivered turn, awaiting its report.
    cad162_sql(
        &d,
        "UPDATE agents SET provider='devin' WHERE alias IN ('wa','wb')",
        &[],
    );
    let token = "pty-planted-cad375token";
    let now = format!(
        "{}",
        SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs_f64()
    );
    cad162_sql(
        &d,
        "INSERT INTO messages(id,alias,body,reply_to,source,state,turn_id,result,created,started)
         VALUES('m-a','wa','task',NULL,'user','running',?1,
                '{\"status\":\"submitted\",\"ack\":null}',CAST(?2 AS REAL),CAST(?2 AS REAL))",
        &[token, &now],
    );
    let bin = env!("CARGO_BIN_EXE_cadence");
    let state = d.state.display().to_string();

    // The owner acks through its own pane — the token works for it.
    let (rc, out) = owner.run(&format!(
        "{bin} --state-dir {state} message ack m-a --token {token}"
    ));
    assert_eq!(rc, 0, "{out}");

    // Every read path a peer has: no token anywhere in the answer.
    let reads = [
        ("agent_show", json!({"alias": "wa"})),
        ("agent_list", json!({})),
        ("agent_events", json!({"alias": "wa"})),
    ];
    for (method, params) in &reads {
        let r = peer.rpc(&d.state, method, params.clone());
        assert_eq!(r["ok"], true, "{method}: {r}");
        assert!(!r.to_string().contains(token), "peer {method}: {r}");
        let r = d.rpc(method, params.clone()).unwrap();
        assert!(!r.to_string().contains(token), "operator {method}: {r}");
    }
    let show = peer.rpc(&d.state, "agent_show", json!({"alias": "wa"}));
    assert!(
        show["result"]["agent"]["awaiting_report"]["message"] == "m-a",
        "{show}"
    );
    assert!(
        show["result"]["agent"]["awaiting_report"]["turn_id"].is_null(),
        "{show}"
    );
    // `cadence self` naming wa from the peer's pane: refused, no token.
    let (rc, out) = peer.run(&format!("CADENCE_ALIAS=wa {bin} --state-dir {state} self"));
    assert_ne!(rc, 0, "{out}");
    assert!(out.contains("shown only to that agent's own pane"), "{out}");
    assert!(!out.contains(token), "{out}");

    // A hot restart's window: the generation is NULL while the turn
    // keeps running and becomes current again on adoption (review R1).
    // A token that is not current NOW is still withheld.
    cad162_sql(
        &d,
        "UPDATE agents SET generation=NULL WHERE alias='wa'",
        &[],
    );
    for (method, params) in &reads {
        let r = peer.rpc(&d.state, method, params.clone());
        assert!(
            !r.to_string().contains(token),
            "peer {method}, no generation: {r}"
        );
    }
    cad162_sql(
        &d,
        "UPDATE agents SET generation='planted' WHERE alias='wa'",
        &[],
    );

    // The owner still reads its own token, on every path.
    for (method, params) in &reads {
        let r = owner.rpc(&d.state, method, params.clone());
        assert!(r.to_string().contains(token), "owner {method}: {r}");
    }
    let (rc, out) = owner.run(&format!("CADENCE_ALIAS=wa {bin} --state-dir {state} self"));
    assert_eq!(rc, 0, "{out}");
    let me: Value = serde_json::from_str(out.trim()).unwrap();
    assert_eq!(me["running"][0]["id"], "m-a", "{me}");
    assert_eq!(me["running"][0]["turn_id"], token, "{me}");
    let (rc, out) = owner.run(&format!(
        "{bin} --state-dir {state} message result m-a --token {token} --text done"
    ));
    assert_eq!(rc, 0, "{out}");
    assert_eq!(d.message_state("wa", "m-a"), "completed");
}

/// Run the built CLI against `d`'s state dir.
fn launch_cli(d: &TestDaemon, args: &[&str]) -> std::process::Output {
    // The operator's shell: launches register agents (CAD-431).
    std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(&d.state)
        .args(args)
        .operator_output()
        .unwrap()
}

/// CAD-110: `--instructions-file` content reaches every provider through
/// the briefing's role-instructions section, and a later briefing
/// rewrite (`agent bootstrap`) carries it forward.
#[test]
fn instructions_file_lands_in_briefing() {
    let d = TestDaemon::start();
    let _mock = d.mock_claude("ok", None);
    d.register("pm");
    d.wait_agent("pm", "idle", 10);
    let file = d.dir.path().join("qa-role.md");
    std::fs::write(&file, "# QA role\n\nNever merge; report defects to pm.\n").unwrap();
    let file_s = file.to_str().unwrap();

    for (provider, alias) in [("fake", "w-fake"), ("claude", "w-claude")] {
        let out = launch_cli(
            &d,
            &[
                "join",
                "pm",
                provider,
                "--alias",
                alias,
                "--detach",
                "--instructions-file",
                file_s,
            ],
        );
        assert!(
            out.status.success(),
            "{provider}: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        d.wait_agent(alias, "idle", 20);
        let briefing = d.state.join(format!("briefings/pm/BRIEFING-{alias}.md"));
        let text = std::fs::read_to_string(&briefing).unwrap();
        assert!(text.contains("## Role instructions"), "{provider}: {text}");
        assert!(
            text.contains("# QA role\n\nNever merge; report defects to pm."),
            "{provider}: {text}"
        );
        // The kickoff points the agent at the section.
        let m = d.rpc("agent_show", json!({"alias": alias})).unwrap()["messages"]
            .as_array()
            .unwrap()
            .iter()
            .find(|m| m["source"] == "bootstrap")
            .cloned()
            .unwrap();
        assert!(
            m["body"].as_str().unwrap().contains("role instructions"),
            "{provider}: {m}"
        );
    }

    // `agent bootstrap` rewrites the file without the launch's
    // instructions in hand — the section survives.
    let out = launch_cli(&d, &["agent", "bootstrap", "w-fake"]);
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let text = std::fs::read_to_string(d.state.join("briefings/pm/BRIEFING-w-fake.md")).unwrap();
    assert!(
        text.contains("Never merge; report defects to pm."),
        "{text}"
    );
    assert_eq!(text.matches("## Role instructions").count(), 1, "{text}");

    // No instructions file → no section.
    let out = launch_cli(
        &d,
        &["join", "pm", "fake", "--alias", "w-plain", "--detach"],
    );
    assert!(out.status.success());
    d.wait_agent("w-plain", "idle", 15);
    let text = std::fs::read_to_string(d.state.join("briefings/pm/BRIEFING-w-plain.md")).unwrap();
    assert!(!text.contains("Role instructions"), "{text}");
}

/// CAD-110: with `--no-bootstrap` the briefing is skipped, so on every
/// provider but codex the instructions would have no delivery channel —
/// refused before anything is registered. Codex keeps its native
/// `developerInstructions` channel and still launches.
#[test]
fn instructions_file_with_no_bootstrap_refused_except_codex() {
    let d = TestDaemon::start();
    let mock = d.mock_codex_ws("ok");
    d.register("pm");
    d.wait_agent("pm", "idle", 10);
    let file = d.dir.path().join("role.md");
    std::fs::write(&file, "Role: reviewer.").unwrap();
    let file_s = file.to_str().unwrap();

    let refused: [&[&str]; 5] = [
        &["join", "pm", "fake", "--alias", "r-fake"],
        &["join", "pm", "claude", "--alias", "r-claude"],
        &["join", "pm", "devin", "--alias", "r-devin"],
        &["join", "pm", "cursor", "--alias", "r-cursor"],
        &["claude", "--alias", "r-solo"],
    ];
    for verb in refused {
        let mut args = verb.to_vec();
        args.extend(["--detach", "--no-bootstrap", "--instructions-file", file_s]);
        let out = launch_cli(&d, &args);
        assert!(!out.status.success(), "{verb:?} was accepted");
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(
            stderr.contains("--instructions-file with --no-bootstrap")
                && stderr.contains("no delivery channel"),
            "{verb:?}: {stderr}"
        );
        let alias = verb[verb.iter().position(|a| *a == "--alias").unwrap() + 1];
        assert!(
            d.rpc("agent_show", json!({"alias": alias})).is_err(),
            "{alias} was registered"
        );
    }

    let out = launch_cli(
        &d,
        &[
            "join",
            "pm",
            "codex",
            "--alias",
            "r-codex",
            "--detach",
            "--no-bootstrap",
            "--instructions-file",
            file_s,
        ],
    );
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    d.wait_agent("r-codex", "idle", 20);
    let reqs = mock_requests(&mock);
    assert_eq!(reqs[0]["method"], "thread/start", "{reqs:?}");
    assert_eq!(
        reqs[0]["params"]["developerInstructions"],
        "Role: reviewer."
    );
}

/// CAD-110: `agent show` advertises the briefing path only while the
/// file exists — a missing file is reported as missing.
#[test]
fn agent_show_reports_missing_briefing() {
    let d = TestDaemon::start();
    d.register("pm");
    d.wait_agent("pm", "idle", 10);
    let out = launch_cli(&d, &["join", "pm", "fake", "--alias", "w1", "--detach"]);
    assert!(out.status.success());
    d.wait_agent("w1", "idle", 15);
    let file = d.state.join("briefings/pm/BRIEFING-w1.md");
    let show = d.rpc("agent_show", json!({"alias": "w1"})).unwrap();
    assert_eq!(show["agent"]["briefing"], file.to_str().unwrap());
    assert!(show["agent"].get("briefing_missing").is_none(), "{show}");

    std::fs::remove_file(&file).unwrap();
    let out = launch_cli(&d, &["agent", "show", "w1"]);
    assert!(out.status.success());
    let show: Value = serde_json::from_slice(&out.stdout).unwrap();
    assert!(show["agent"]["briefing"].is_null(), "{show}");
    assert_eq!(show["agent"]["briefing_missing"], file.to_str().unwrap());

    // A --no-bootstrap worker never had one — missing, not advertised.
    let out = launch_cli(
        &d,
        &[
            "join",
            "pm",
            "fake",
            "--alias",
            "w2",
            "--detach",
            "--no-bootstrap",
        ],
    );
    assert!(out.status.success());
    d.wait_agent("w2", "idle", 15);
    let show = d.rpc("agent_show", json!({"alias": "w2"})).unwrap();
    assert!(show["agent"]["briefing"].is_null(), "{show}");
    assert_eq!(
        show["agent"]["briefing_missing"],
        d.state
            .join("briefings/pm/BRIEFING-w2.md")
            .to_str()
            .unwrap()
    );
}

/// CAD-214: email-style flags on `message send` / `send` fail with the
/// real usage line, not clap's `-- --to` value tip.
#[test]
fn send_email_flags_print_real_usage() {
    let state = TempDir::new().unwrap();
    for verb in [&["message", "send"][..], &["send"][..]] {
        let usage = format!("cadence {} <ALIAS> --text <body>", verb.join(" "));
        for flag in ["--to", "--subject", "--body", "--cc"] {
            for tail in [&[flag, "x"][..], &["pm", "--text", "hi", flag, "x"][..]] {
                let out = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
                    .arg("--state-dir")
                    .arg(state.path())
                    .args(verb)
                    .args(tail)
                    .output()
                    .unwrap();
                let stderr = String::from_utf8_lossy(&out.stderr);
                assert_eq!(out.status.code(), Some(2), "{verb:?} {tail:?}: {stderr}");
                assert!(stderr.contains(&usage), "{verb:?} {tail:?}: {stderr}");
                assert!(
                    stderr.contains(&format!("no `{flag}` flag")),
                    "{verb:?} {tail:?}: {stderr}"
                );
                assert!(!stderr.contains("-- --"), "{verb:?} {tail:?}: {stderr}");
                assert!(stderr.contains("SUBJECT:"), "{verb:?} {tail:?}: {stderr}");
            }
        }
    }
    // Other unknown flags keep clap's own error.
    let out = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(state.path())
        .args(["send", "pm", "--bogus"])
        .output()
        .unwrap();
    assert_eq!(out.status.code(), Some(2));
    assert!(String::from_utf8_lossy(&out.stderr).contains("unexpected argument '--bogus'"));
    // `--help` documents the SUBJECT convention.
    for verb in [&["message", "send"][..], &["send"][..]] {
        let out = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
            .args(verb)
            .arg("--help")
            .output()
            .unwrap();
        assert!(out.status.success());
        let help = String::from_utf8_lossy(&out.stdout);
        assert!(help.contains("SUBJECT: <topic>"), "{verb:?}: {help}");
    }
}

/// CAD-214: `--text` and `-m` carry the body on `message send`, `send`
/// and `issue comment` alike.
#[test]
fn body_flags_match_on_send_and_comment() {
    let d = TestDaemon::start();
    d.register("w1");
    d.wait_agent("w1", "idle", 10);
    let sends: [(&[&str], &str, &str); 4] = [
        (&["message", "send"], "--text", "b-ms-text"),
        (&["message", "send"], "-m", "b-ms-m"),
        (&["send"], "--text", "b-s-text"),
        (&["send"], "-m", "b-s-m"),
    ];
    for (verb, flag, id) in sends {
        let mut args = verb.to_vec();
        args.extend(["w1", flag, id, "--message", id]);
        let out = launch_cli(&d, &args);
        assert!(
            out.status.success(),
            "{args:?}: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let m = d.wait_message("w1", id, &["completed"], 15);
        assert_eq!(m["body"], id, "{args:?}");
    }

    let pm_dir = d.dir.path().join("pm");
    let home = d.dir.path().join("home");
    std::fs::create_dir_all(&home).unwrap();
    let bin_dir = Path::new(env!("CARGO_BIN_EXE_cadence")).parent().unwrap();
    let issue = |args: &[&str]| {
        let out = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
            .arg("--state-dir")
            .arg(&d.state)
            .args(args)
            .env("CADENCE_PM_DIR", &pm_dir)
            .env("HOME", &home)
            .env(
                "PATH",
                format!(
                    "{}:{}",
                    bin_dir.display(),
                    std::env::var("PATH").unwrap_or_default()
                ),
            )
            .env_remove("CADENCE_ALIAS")
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "{args:?}: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        String::from_utf8_lossy(&out.stdout).to_string()
    };
    issue(&["issue", "init"]);
    issue(&["issue", "project", "add", "demo", "--prefix", "D"]);
    issue(&["issue", "new", "One", "--project", "demo"]);
    issue(&["issue", "comment", "D-1", "-m", "comment-via-m"]);
    issue(&["issue", "comment", "D-1", "--text", "comment-via-text"]);
    let show = issue(&["issue", "show", "D-1"]);
    for want in ["comment-via-m", "comment-via-text"] {
        assert!(show.contains(want), "{want}: {show}");
    }
}

// ---------- CAD-109: pre-publish secret scan ----------

/// A synthetic token: `prefix` plus `n` letters and digits drawn from a
/// seeded SHA-256 stream. It is built at run time so this file never holds a
/// credential-shaped literal.
fn cad109_token(prefix: &str, seed: &str, n: usize) -> String {
    use sha2::{Digest, Sha256};
    const ALPHANUM: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut out = prefix.to_string();
    let mut counter = 0u32;
    while out.len() < prefix.len() + n {
        for b in Sha256::digest(format!("{seed}:{counter}").as_bytes()) {
            if out.len() < prefix.len() + n {
                out.push(ALPHANUM[b as usize % ALPHANUM.len()] as char);
            }
        }
        counter += 1;
    }
    out
}

/// `cadence --state-dir <state> secret scan <args>` with `stdin` piped in.
fn cad109_scan(state: &Path, args: &[&str], stdin: &str) -> (i32, Value, String) {
    let mut child = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(state)
        .args(["secret", "scan"])
        .args(args)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .take()
        .unwrap()
        .write_all(stdin.as_bytes())
        .unwrap();
    let out = child.wait_with_output().unwrap();
    let stdout = String::from_utf8_lossy(&out.stdout).to_string();
    let stderr = String::from_utf8_lossy(&out.stderr).to_string();
    let v = serde_json::from_str(stdout.trim())
        .unwrap_or_else(|_| panic!("not json: {stdout} / {stderr}"));
    (
        out.status.code().unwrap_or(-1),
        v,
        format!("{stdout}{stderr}"),
    )
}

/// Exit 0 when clean or warn-only, 1 on a blocking finding. A bare token
/// alone on its line is found with its rule, line and a redacted prefix, and
/// the value appears nowhere in the output. The operator allowlist in the
/// state dir drops what it names.
#[test]
fn secret_scan_exit_codes_and_redaction() {
    let tmp = TempDir::new().unwrap();
    let state = tmp.path().join("state");
    std::fs::create_dir_all(&state).unwrap();

    let (code, v, _) = cad109_scan(&state, &[], "Ran the focused tests; all green.\n");
    assert_eq!(code, 0, "{v}");
    assert_eq!(v["findings"], json!([]));

    let warn = format!(
        "config:\n  api_key = \"{}\"\n",
        cad109_token("", "warn", 24)
    );
    let (code, v, _) = cad109_scan(&state, &[], &warn);
    assert_eq!(code, 0, "{v}");
    assert_eq!(v["findings"][0]["rule"], "generic-api-key");
    assert_eq!(v["findings"][0]["severity"], "warn");

    let ant = ["sk", "-ant-", "api03-"].concat();
    let pat = ["github", "_pat_"].concat();
    for (prefix, rule) in [
        ("figd_", "cadence-figma-token"),
        (ant.as_str(), "cadence-anthropic-key"),
        (pat.as_str(), "cadence-github-fine-grained-pat"),
    ] {
        let tok = cad109_token(prefix, rule, 64);
        let (code, v, all) = cad109_scan(&state, &[], &format!("Result\n\n{tok}\n"));
        assert_eq!(code, 1, "{v}");
        let f = &v["findings"][0];
        assert_eq!(f["rule"], rule, "{v}");
        assert_eq!(
            (f["line"].as_u64(), f["column"].as_u64()),
            (Some(3), Some(1))
        );
        assert_eq!(f["severity"], "block");
        assert!(f["redacted"].as_str().unwrap().ends_with('…'), "{v}");
        assert!(!all.contains(&tok[prefix.len()..]), "{all}");
    }

    let tok = cad109_token("figd_", "file", 40);
    let file = tmp.path().join("pr-body.md");
    std::fs::write(&file, format!("# Summary\n\ntoken {tok}\n")).unwrap();
    let (code, v, all) = cad109_scan(&state, &["--file", file.to_str().unwrap()], "");
    assert_eq!(code, 1, "{v}");
    assert_eq!(v["blocking"], 1);
    assert!(!all.contains(&tok[5..]), "{all}");

    std::fs::write(
        state.join("secret-allowlist.toml"),
        "[[allow]]\nrule = \"cadence-figma-token\"\nreason = \"test fixture\"\n",
    )
    .unwrap();
    let (code, v, _) = cad109_scan(&state, &["--file", file.to_str().unwrap()], "");
    assert_eq!(code, 0, "{v}");
    assert_eq!(v["allowlisted"], 1);

    std::fs::write(state.join("secret-allowlist.toml"), "not toml [").unwrap();
    let out = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(&state)
        .args(["secret", "scan", "--file", file.to_str().unwrap()])
        .output()
        .unwrap();
    assert!(!out.status.success());
    assert!(String::from_utf8_lossy(&out.stderr).contains("Refusing to write"));
}

/// `issue comment` refuses a credential-shaped body: the error names the
/// rule, never the value, and no comment file or tracker commit is written.
/// `report` is refused the same way, both as a new issue and as `--issue`.
#[test]
fn issue_comment_and_report_refuse_credential_shaped_text() {
    let s = ReportFx::new();
    let state = s.state.to_str().unwrap().to_string();
    let env = [("CADENCE_STATE_DIR", state.as_str())];
    let (ok, out) = s.cli(&["issue", "new", "Target", "--project", "product"]);
    assert!(ok, "{out}");
    let id = out["id"].as_str().unwrap().to_string();
    let comments = s.pm_dir.join("product").join(&id).join("comments");
    let count = || std::fs::read_dir(&comments).map(|d| d.count()).unwrap_or(0);
    let log_before = s.tracker_log(1);

    let tok = cad109_token("figd_", "comment", 40);
    let body = format!("Verified locally.\n{tok}\n");
    let (ok, stderr, _) = s.cli_at_env(
        &s.product_repo,
        &["issue", "comment", &id, "-m", &body],
        &env,
    );
    assert!(!ok, "{stderr}");
    assert!(stderr.contains("rule cadence-figma-token"), "{stderr}");
    assert!(
        stderr.contains("secret_detected") || stderr.contains("refused"),
        "{stderr}"
    );
    assert!(!stderr.contains(&tok[5..]), "{stderr}");
    assert_eq!(count(), 0);
    assert_eq!(s.tracker_log(1), log_before);

    for args in [
        vec!["report", "--kind", "bug", "-m", &body],
        vec!["report", "--issue", &id, "--kind", "bug", "-m", &body],
    ] {
        let (ok, stderr, _) = s.cli_at_env(&s.product_repo, &args, &env);
        assert!(!ok, "{args:?}: {stderr}");
        assert!(stderr.contains("rule cadence-figma-token"), "{stderr}");
        assert!(!stderr.contains(&tok[5..]), "{stderr}");
    }
    assert_eq!(count(), 0);
    assert_eq!(s.tracker_log(1), log_before);

    // Clean text still goes through, and a warn-only finding rides along.
    let warn = format!(
        "config:\n  api_key = \"{}\"\n",
        cad109_token("", "warn", 24)
    );
    let (ok, stderr, (_, v)) = s.cli_at_env(
        &s.product_repo,
        &["issue", "comment", &id, "-m", &warn],
        &env,
    );
    assert!(ok, "{stderr}");
    assert_eq!(v["secret_warnings"][0]["rule"], "generic-api-key", "{v}");
    assert_eq!(count(), 1);
}

// ---- CAD-257: session gate scope, expiring acks ----

/// `cadence session start` stdout+stderr and exit code.
fn session_text(out: &std::process::Output) -> String {
    format!(
        "{}{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    )
}

/// An idle agent holding one `unknown` message — a reconcile `fail`
/// keyed `reconcile:<id>`.
fn unknown_msg_agent(alias: &str, id: &str) -> StubAgent {
    stub_agent(
        alias,
        "fake",
        "fake",
        "idle",
        60,
        (
            vec![json!({"id": id, "state": "unknown", "body": "lost turn"})],
            0,
            1,
        ),
    )
}

/// An acknowledged item warns until its expiry and fails after it —
/// the expired record is written straight into the store (no sleeps),
/// and `ack --list` keeps it, marked expired.
#[test]
fn session_start_ack_downgrades_until_expiry() {
    let tmp = TempDir::new().unwrap();
    let (state, pm, repo) = (
        tmp.path().join("state"),
        tmp.path().join("pm"),
        tmp.path().join("repo"),
    );
    seed_pm(&pm, &repo, &tmp.path().join("notes"));
    seed_repo(&repo);
    let _sd = stub_daemon(
        &state,
        cadence_agent::overview::BUILD_COMMIT,
        vec![unknown_msg_agent("w1", "m-unk")],
    );
    let host = clean_host(tmp.path());
    let start = || run_session_host(&state, &pm, &repo, &["session", "start"], &host, &[]);

    let out = start();
    let text = session_text(&out);
    assert_eq!(out.status.code(), Some(2), "unacked fails:\n{text}");
    assert!(text.contains("[reconcile:m-unk]"), "key printed:\n{text}");
    assert!(text.contains("cadence session ack <key>"), "hint:\n{text}");

    // A credential-shaped reason is refused by CAD-109's scan before
    // the store is written. The synthetic token is assembled at run
    // time so no credential-shaped literal is committed.
    let token = ["gh", "p_", "0123456789abcdefghij", "ABCDEFGHIJ012345"].concat();
    let reason = format!("token {token}");
    let out = run_session(
        &state,
        &pm,
        &repo,
        &[
            "session",
            "ack",
            "reconcile:m-unk",
            "--reason",
            &reason,
            "--expires",
            "1d",
        ],
    );
    let text = session_text(&out);
    assert!(!out.status.success(), "secret reason accepted:\n{text}");
    assert!(
        text.contains("credential-shaped") && !text.contains(&token),
        "{text}"
    );

    // Refusals: past the 14-day cap, in the past, no reason.
    for args in [
        vec![
            "session",
            "ack",
            "reconcile:m-unk",
            "--reason",
            "x",
            "--expires",
            "15d",
        ],
        vec![
            "session",
            "ack",
            "reconcile:m-unk",
            "--reason",
            "x",
            "--expires",
            "2020-01-01T00:00:00Z",
        ],
        vec![
            "session",
            "ack",
            "reconcile:m-unk",
            "--reason",
            " ",
            "--expires",
            "1d",
        ],
    ] {
        let out = run_session(&state, &pm, &repo, &args);
        assert!(
            !out.status.success(),
            "{args:?} accepted:\n{}",
            session_text(&out)
        );
    }
    assert!(
        !state.join("sessions/acks.json").exists(),
        "a refusal wrote the store"
    );

    let out = run_session(
        &state,
        &pm,
        &repo,
        &[
            "session",
            "ack",
            "reconcile:m-unk",
            "--reason",
            "known lost turn",
            "--expires",
            "2d",
        ],
    );
    assert!(out.status.success(), "{}", session_text(&out));
    let out = start();
    let text = session_text(&out);
    assert_eq!(
        out.status.code(),
        Some(1),
        "acked fail downgrades to warn:\n{text}"
    );
    assert!(
        text.contains("[reconcile:m-unk]"),
        "an ack never hides the item:\n{text}"
    );
    assert!(
        text.contains("(acknowledged until") && text.contains("known lost turn"),
        "ack reason shown:\n{text}"
    );

    // Expired: the same record with an expiry already past.
    let store = state.join("sessions/acks.json");
    let mut acks: Value = serde_json::from_str(&std::fs::read_to_string(&store).unwrap()).unwrap();
    assert_eq!(acks["acks"][0]["key"], "reconcile:m-unk");
    assert!(acks["acks"][0]["actor"]
        .as_str()
        .is_some_and(|a| !a.is_empty()));
    acks["acks"][0]["expires"] = json!("2026-01-01T00:00:00Z");
    std::fs::write(&store, acks.to_string()).unwrap();
    let out = start();
    let text = session_text(&out);
    assert_eq!(
        out.status.code(),
        Some(2),
        "expired ack fails again:\n{text}"
    );
    assert!(
        text.contains("(acknowledgement expired 2026-01-01T00:00:00Z"),
        "{text}"
    );

    let out = run_session(&state, &pm, &repo, &["session", "ack", "--list", "--json"]);
    let list: Value = serde_json::from_slice(&out.stdout).unwrap();
    assert_eq!(list["acks"].as_array().unwrap().len(), 1, "{list}");
    assert_eq!(list["acks"][0]["state"], "expired", "{list}");
}

/// Default scope is the cwd repo's project: another project's failing
/// item collapses to the `others` summary and cannot no-go the gate;
/// `--all` judges it again, and a cwd outside every project repo
/// behaves as `--all` and says so.
#[test]
fn session_start_scopes_to_cwd_project() {
    let tmp = TempDir::new().unwrap();
    let (state, pm, repo, other) = (
        tmp.path().join("state"),
        tmp.path().join("pm"),
        tmp.path().join("repo"),
        tmp.path().join("other-repo"),
    );
    seed_pm(&pm, &repo, &tmp.path().join("notes"));
    seed_repo(&repo);
    std::fs::create_dir_all(pm.join("oth")).unwrap();
    std::fs::create_dir_all(&other).unwrap();
    std::fs::write(
        pm.join("oth/project.yaml"),
        format!(
            "key: oth\nprefix: OTH\nrepos:\n- path: {}\n",
            other.display()
        ),
    )
    .unwrap();
    let _sd = stub_daemon(
        &state,
        cadence_agent::overview::BUILD_COMMIT,
        vec![unknown_msg_agent("ow", "m-oth").with_cwd(&other)],
    );
    let host = clean_host(tmp.path());

    let out = run_session_host(&state, &pm, &repo, &["session", "start"], &host, &[]);
    let text = session_text(&out);
    assert_eq!(
        out.status.code(),
        Some(1),
        "other project's fail capped at warn:\n{text}"
    );
    assert!(text.contains("scope: project tst"), "{text}");
    assert!(text.contains("others"), "summary row:\n{text}");
    assert!(
        text.contains("oth 1 (worst fail)"),
        "per-project count:\n{text}"
    );
    assert!(
        !text.contains("[reconcile:m-oth]"),
        "collapsed, not listed:\n{text}"
    );
    // The cwd project's own findings are still judged and listed.
    assert!(text.contains("tst-88-ghost"), "{text}");

    let out = run_session_host(
        &state,
        &pm,
        &repo,
        &["session", "start", "--all"],
        &host,
        &[],
    );
    let text = session_text(&out);
    assert_eq!(
        out.status.code(),
        Some(2),
        "--all judges every project:\n{text}"
    );
    assert!(text.contains("[reconcile:m-oth]"), "{text}");

    let out = run_session_host(
        &state,
        &pm,
        &repo,
        &["session", "start", "--project", "oth", "--json"],
        &host,
        &[],
    );
    let v: Value = serde_json::from_slice(&out.stdout).unwrap();
    assert_eq!(out.status.code(), Some(2), "{v}");
    assert_eq!(v["scope"]["project"], "oth");

    // Outside any project repo: fleet-wide, with the reason printed.
    let out = run_session_host(&state, &pm, tmp.path(), &["session", "start"], &host, &[]);
    let text = session_text(&out);
    assert_eq!(out.status.code(), Some(2), "{text}");
    assert!(text.contains("not inside a known project repo"), "{text}");
}

// ==== CAD-201 / CAD-202: pty lane process tree and cwd integrity ====

/// `(state, sid, start_time)` from `/proc/<pid>/stat` — `None` once the
/// pid is gone.
fn lane_stat(pid: u32) -> Option<(char, u32, u64)> {
    let text = std::fs::read_to_string(format!("/proc/{pid}/stat")).ok()?;
    let end = text.rfind(')')?;
    let f: Vec<&str> = text[end + 1..].split_whitespace().collect();
    Some((
        f.first()?.chars().next()?,
        f.get(3)?.parse().ok()?,
        f.get(19)?.parse().ok()?,
    ))
}

/// Live (non-zombie) pids whose session id is `sid`.
fn lane_session_pids(sid: u32) -> Vec<u32> {
    std::fs::read_dir("/proc")
        .unwrap()
        .flatten()
        .filter_map(|e| e.file_name().to_string_lossy().parse::<u32>().ok())
        .filter(|&pid| lane_stat(pid).is_some_and(|(state, s, _)| s == sid && state != 'Z'))
        .collect()
}

/// Test-owned `sleep` children, SIGKILLed on drop if a failed assertion
/// left them running — matched by pid + start time, never pid alone.
struct LaneSleepers(Vec<(u32, u64)>);

impl Drop for LaneSleepers {
    fn drop(&mut self) {
        for &(pid, start) in &self.0 {
            if lane_stat(pid).is_some_and(|(state, _, s)| s == start && state != 'Z') {
                unsafe { libc::kill(pid as i32, libc::SIGKILL) };
            }
        }
    }
}

fn wait_pid_file(path: &Path, secs: u64) -> u32 {
    let deadline = Instant::now() + Duration::from_secs(secs);
    loop {
        if let Some(pid) = std::fs::read_to_string(path)
            .ok()
            .and_then(|t| t.trim().parse::<u32>().ok())
        {
            return pid;
        }
        assert!(
            Instant::now() < deadline,
            "{} never appeared",
            path.display()
        );
        thread::sleep(Duration::from_millis(50));
    }
}

/// CAD-201: a pty lane records its pane root (pid + start time +
/// session id + generation) at open and `agent stop` reaps the pane's
/// session after the pane is killed: SIGTERM, a bounded drain, a
/// re-sample by identity and SIGKILL only for matching survivors.
/// The pane spawns two children into their own process groups (so
/// killing the pane's group misses them, as with real MCP servers):
/// one exits on SIGTERM, one ignores it and needs the SIGKILL. A
/// process outside the session is untouched.
#[test]
fn pty_stop_reaps_pane_session_tree() {
    let d = TestDaemon::start();
    let mock = d.mock_stub();
    test_env().set("CADENCE_PTY_DRAIN_SECS", "1.5");
    let kids = d.dir.path().join("kids");
    std::fs::create_dir_all(&kids).unwrap();
    // `set -m` gives each background job its own process group inside
    // the pane's session; the spawning shell then exits, so both
    // children are reparented — exactly the escaped-MCP-child shape.
    let spawn = format!(
        "bash -c 'set -m; sleep 600 & echo $! > {k}/term.pid; \
         (trap \"\" TERM; exec sleep 601) & echo $! > {k}/kill.pid'; \
         python3 {stub} {locks}",
        k = kids.display(),
        stub = mock.dir.join("mock-stub.py").display(),
        locks = mock.locks.display(),
    );
    test_env().set("CADENCE_STUB_COMMAND", spawn);
    // Unrelated process: the test's own child, outside the pane session.
    let mut outsider = std::process::Command::new("sleep")
        .arg("600")
        .spawn()
        .unwrap();
    let outsider_start = lane_stat(outsider.id()).unwrap().2;
    let mut guard = LaneSleepers(vec![(outsider.id(), outsider_start)]);

    d.register_stub("st", json!({}));
    let agent = d.wait_agent("st", "idle", 20);
    let root = agent["pane_root"].clone();
    assert_eq!(root["session_leader"], true, "{agent}");
    assert_eq!(root["current"], true, "{agent}");
    assert_eq!(root["generation"], agent["generation"], "{agent}");
    let sid = root["sid"].as_u64().unwrap() as u32;
    assert_eq!(root["pid"].as_u64().unwrap() as u32, sid, "{agent}");
    assert_eq!(
        lane_stat(sid).unwrap().2,
        root["start_time"].as_u64().unwrap(),
        "{agent}"
    );
    let term_pid = wait_pid_file(&kids.join("term.pid"), 10);
    let kill_pid = wait_pid_file(&kids.join("kill.pid"), 10);
    for pid in [term_pid, kill_pid] {
        let (_, s, start) = lane_stat(pid).expect("child alive");
        assert_eq!(s, sid, "child {pid} must be in the pane session");
        guard.0.push((pid, start));
    }
    let recorded = d.wait_event("st", "pane_root", 5);
    assert_eq!(recorded["payload"]["sid"], root["sid"], "{recorded}");

    d.rpc("agent_stop", json!({"alias": "st"})).unwrap();
    d.wait_agent("st", "stopped", 15);
    let intent = d.wait_event("st", "pane_tree_reap_intent", 15);
    let members: Vec<u64> = intent["payload"]["members"]
        .as_array()
        .unwrap()
        .iter()
        .map(|m| m["pid"].as_u64().unwrap())
        .collect();
    assert!(
        members.contains(&(term_pid as u64)) && members.contains(&(kill_pid as u64)),
        "{intent}"
    );
    let reaped = d.wait_event("st", "pane_tree_reaped", 20);
    let pids = |key: &str| -> Vec<u64> {
        reaped["payload"][key]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| m["pid"].as_u64().unwrap())
            .collect()
    };
    assert!(reaped["payload"]["refused"].is_null(), "{reaped}");
    assert!(pids("terminated").contains(&(term_pid as u64)), "{reaped}");
    assert!(pids("exited").contains(&(term_pid as u64)), "{reaped}");
    // Only the SIGTERM-ignoring child needed the SIGKILL.
    assert_eq!(pids("killed"), vec![kill_pid as u64], "{reaped}");
    assert!(pids("residue").is_empty(), "{reaped}");
    // Nothing from the pane's session survives the drain…
    let deadline = Instant::now() + Duration::from_secs(5);
    while !lane_session_pids(sid).is_empty() {
        assert!(
            Instant::now() < deadline,
            "session {sid} survivors: {:?}",
            lane_session_pids(sid)
        );
        thread::sleep(Duration::from_millis(50));
    }
    // …and the process outside it is untouched.
    assert!(
        lane_stat(outsider.id()).is_some_and(|(state, _, s)| s == outsider_start && state != 'Z'),
        "the outside process must survive"
    );

    // A second stop is idempotent: the tree is already reaped.
    d.rpc("agent_stop", json!({"alias": "st"})).unwrap();
    // CAD-184 kept sleep: absence window — a declined reap records
    // nothing; a started one would land on its own thread.
    thread::sleep(Duration::from_millis(300));
    let intents = d
        .events("st")
        .into_iter()
        .filter(|e| e["kind"] == "pane_tree_reap_intent")
        .count();
    assert_eq!(intents, 1);

    let _ = outsider.kill();
    let _ = outsider.wait();
    drop(guard);
    test_env().remove("CADENCE_PTY_DRAIN_SECS");
}

/// CAD-201: an agent with no recorded pane root (opened before the
/// identity was recorded) is never reaped — the stop records that the
/// tree is unowned and signals nothing beyond the pane.
#[test]
fn pty_stop_without_pane_root_records_unowned_tree() {
    let seeded = TempDir::new().unwrap();
    let state = seeded.path().to_path_buf();
    {
        let store = Store::open(&state.join("cadence.sqlite3")).unwrap();
        let cwd = state.to_str().unwrap().to_string();
        store
            .register_agent(&NewAgent {
                alias: "old",
                provider: "tui-stub",
                endpoint_kind: "pty",
                role: "worker",
                cwd: &cwd,
                sandbox: "read-only",
                instructions: None,
                params: None,
                team_role: None,
                model_policy: None,
            })
            .unwrap();
        store.set_enabled("old", false).unwrap();
        store.set_agent_state("old", "stopped", None).unwrap();
    }
    let d = TestDaemon::start_on(state);
    let _mock = d.mock_stub();
    d.rpc("agent_stop", json!({"alias": "old"})).unwrap();
    let e = d.wait_event("old", "pane_tree_unowned", 10);
    assert!(
        e["payload"]["reason"]
            .as_str()
            .unwrap_or("")
            .contains("no pane root identity"),
        "{e}"
    );
    assert!(d
        .events("old")
        .iter()
        .all(|e| e["kind"] != "pane_tree_reap_intent"));
}

/// Run the cadence CLI against `d` with a hermetic tracker/home.
fn lane_cli(d: &TestDaemon, pm_dir: &Path, home: &Path, args: &[&str]) -> (bool, Value) {
    let bin_dir = Path::new(env!("CARGO_BIN_EXE_cadence"))
        .parent()
        .unwrap()
        .to_path_buf();
    let out = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(&d.state)
        .args(args)
        .env("CADENCE_PM_DIR", pm_dir)
        .env("HOME", home)
        .env(
            "PATH",
            format!(
                "{}:{}",
                bin_dir.display(),
                std::env::var("PATH").unwrap_or_default()
            ),
        )
        .env_remove("CADENCE_ALIAS")
        .operator_output()
        .unwrap();
    let text = if out.stdout.is_empty() {
        String::from_utf8_lossy(&out.stderr).to_string()
    } else {
        String::from_utf8_lossy(&out.stdout).to_string()
    };
    (
        out.status.success(),
        serde_json::from_str(text.trim()).unwrap_or_else(|_| panic!("not json: {text}")),
    )
}

/// CAD-202: a pty pane whose cwd was deleted refuses delivery at the
/// gate with a named reason — the message stays queued, never failed —
/// and `agent show` and `status` surface `cwd_deleted`.
#[test]
fn pty_deleted_cwd_refuses_delivery_and_is_surfaced() {
    let d = TestDaemon::start();
    let _mock = d.mock_stub();
    let lane = d.dir.path().join("lane-wt");
    std::fs::create_dir_all(&lane).unwrap();
    d.rpc(
        "agent_register",
        json!({"alias": "st", "provider": "tui-stub", "endpoint_kind": "pty",
               "cwd": lane.to_str().unwrap(),
               "params": json!({"auto_ready": "verified"}).to_string()}),
    )
    .unwrap();
    let agent = d.wait_agent("st", "idle", 20);
    assert_eq!(agent["cwd_deleted"], false, "{agent}");
    assert_eq!(
        agent["pane_cwd"]["path"].as_str().unwrap(),
        lane.canonicalize().unwrap().to_str().unwrap(),
        "{agent}"
    );
    // The worktree is removed under the live pane.
    std::fs::remove_dir_all(&lane).unwrap();
    let agent = d.rpc("agent_show", json!({"alias": "st"})).unwrap()["agent"].clone();
    assert_eq!(agent["cwd_deleted"], true, "{agent}");
    assert_eq!(agent["pane_cwd"]["deleted"], true, "{agent}");

    d.rpc(
        "agent_send",
        json!({"alias": "st", "text": "work here", "message": "m1"}),
    )
    .unwrap();
    let wait = d.wait_event("st", "gate_wait", 15);
    assert!(
        wait["payload"]["reason"]
            .as_str()
            .unwrap_or("")
            .starts_with("cwd_deleted:"),
        "{wait}"
    );
    assert_eq!(d.message_state("st", "m1"), "queued");

    let tmp = TempDir::new().unwrap();
    let (pm_dir, home) = (tmp.path().join("pm"), tmp.path().join("home"));
    std::fs::create_dir_all(&home).unwrap();
    let (ok, view) = lane_cli(&d, &pm_dir, &home, &["status", "--json"]);
    assert!(ok, "{view}");
    let row = view["agents"]
        .as_array()
        .unwrap()
        .iter()
        .find(|a| a["alias"] == "st")
        .cloned()
        .unwrap();
    assert_eq!(row["cwd_deleted"], true, "{row}");
    // Still queued after the status probe — refusal, not failure.
    assert_eq!(d.message_state("st", "m1"), "queued");
}

/// CAD-202: issue dispatch to a pty lane checks the pane's cwd against
/// the issue project's repos — outside refuses by name, `--force`
/// dispatches and records the override on the issue, a deleted cwd
/// always refuses, an in-repo lane dispatches as before, and `issue
/// start --job --assignee` applies the same check.
#[test]
fn dispatch_checks_pty_lane_cwd_against_project_repos() {
    let d = TestDaemon::start();
    let _mock = d.mock_stub();
    let tmp = TempDir::new().unwrap();
    let (pm_dir, repo, home, elsewhere, gone) = (
        tmp.path().join("pm"),
        tmp.path().join("repo"),
        tmp.path().join("home"),
        tmp.path().join("elsewhere"),
        tmp.path().join("gone"),
    );
    for dir in [&pm_dir, &repo, &home, &elsewhere, &gone] {
        std::fs::create_dir_all(dir).unwrap();
    }
    let git = |dir: &Path, args: &[&str]| {
        let o = std::process::Command::new("git")
            .arg("-C")
            .arg(dir)
            .args(args)
            .output()
            .unwrap();
        assert!(o.status.success(), "git {}", args.join(" "));
    };
    git(&repo, &["init", "-b", "main"]);
    git(&repo, &["config", "user.email", "t@t"]);
    git(&repo, &["config", "user.name", "t"]);
    std::fs::write(repo.join("f"), "x").unwrap();
    git(&repo, &["add", "-A"]);
    git(&repo, &["commit", "-qm", "init"]);
    let cli = |args: &[&str]| lane_cli(&d, &pm_dir, &home, args);
    assert!(cli(&["issue", "init"]).0);
    let repo_s = repo.canonicalize().unwrap().to_str().unwrap().to_string();
    assert!(cli(&["issue", "project", "add", "demo", "--prefix", "D", "--repo", &repo_s]).0);
    for title in ["One", "Two", "Three", "Four"] {
        assert!(cli(&["issue", "new", title, "--project", "demo"]).0);
    }
    let note = tmp.path().join("kickoff.md");
    std::fs::write(&note, "# kickoff").unwrap();
    let note_s = note.canonicalize().unwrap().to_str().unwrap().to_string();
    let spec = tmp.path().join("spec.md");
    std::fs::write(&spec, "# spec").unwrap();
    let spec_s = spec.to_str().unwrap().to_string();

    d.register("pm");
    for (alias, cwd) in [("out", &elsewhere), ("inr", &repo), ("gone", &gone)] {
        d.fixture_rpc(
            "agent_register",
            json!({"alias": alias, "provider": "tui-stub", "endpoint_kind": "pty",
                   "cwd": cwd.to_str().unwrap(),
                   "params": json!({"upstream": "pm"}).to_string()}),
        )
        .unwrap();
    }
    for alias in ["pm", "out", "inr", "gone"] {
        d.wait_agent(alias, "idle", 20);
    }
    std::fs::remove_dir_all(&gone).unwrap();
    let dispatch = |issue: &str, to: &str, extra: &[&str]| {
        let mut args = vec![
            "dispatch",
            issue,
            "--to",
            to,
            "--note",
            &note_s,
            "--reply-to",
            "pm",
        ];
        args.extend_from_slice(extra);
        cli(&args)
    };

    // Outside every project repo: refused by name, nothing created.
    let (ok, err) = dispatch("D-1", "out", &[]);
    assert!(!ok, "{err}");
    assert!(
        err["error"]
            .as_str()
            .unwrap()
            .starts_with("cwd_outside_project:"),
        "{err}"
    );
    assert!(!repo.join(".cadence/wt/d-1-one").exists());
    assert!(
        d.rpc("agent_show", json!({"alias": "out"})).unwrap()["messages"]
            .as_array()
            .unwrap()
            .is_empty()
    );

    // `--force` dispatches and the override lands on the issue.
    let (ok, out) = dispatch("D-1", "out", &["--force"]);
    assert!(ok, "{out}");
    assert_eq!(out["dispatched"], true, "{out}");
    assert!(
        out["cwd_override"]
            .as_str()
            .unwrap()
            .contains("cwd_outside_project"),
        "{out}"
    );
    let issue = cli(&["issue", "show", "D-1", "--json"]).1;
    assert!(
        issue["comments"].as_array().unwrap().iter().any(|c| {
            let body = c["body"].as_str().unwrap_or("");
            body.contains("Dispatched to out") && body.contains("Dispatch override (--force")
        }),
        "{issue}"
    );

    // A deleted cwd refuses even with --force.
    let (ok, err) = dispatch("D-2", "gone", &["--force"]);
    assert!(!ok, "{err}");
    assert!(
        err["error"].as_str().unwrap().starts_with("cwd_deleted:"),
        "{err}"
    );
    assert!(!repo.join(".cadence/wt/d-2-two").exists());

    // The normal case: a lane inside the project's repo dispatches.
    let (ok, out) = dispatch("D-3", "inr", &[]);
    assert!(ok, "{out}");
    assert_eq!(out["dispatched"], true, "{out}");
    assert!(out["cwd_override"].is_null(), "{out}");

    // `issue start --job --assignee` applies the same check.
    let start = |extra: &[&str]| {
        let mut args = vec![
            "issue",
            "start",
            "D-4",
            "--job",
            "--pm",
            "pm",
            "--spec",
            &spec_s,
            "--assignee",
            "out",
        ];
        args.extend_from_slice(extra);
        cli(&args)
    };
    let (ok, err) = start(&[]);
    assert!(!ok, "{err}");
    assert!(
        err["error"]
            .as_str()
            .unwrap()
            .starts_with("cwd_outside_project:"),
        "{err}"
    );
    assert!(!repo.join(".cadence/wt/d-4-four").exists());
    let (ok, out) = start(&["--force"]);
    assert!(ok, "{out}");
    assert!(out["cwd_override"].is_string(), "{out}");
    let issue = cli(&["issue", "show", "D-4", "--json"]).1;
    assert!(
        issue["comments"]
            .as_array()
            .unwrap()
            .iter()
            .any(|c| c["body"]
                .as_str()
                .unwrap_or("")
                .contains("Dispatch override (--force")),
        "{issue}"
    );
}

// ---- CAD-199: opt-in, records-only agent-gc timer ----

/// Seed a state dir with stopped, disabled fake agents pre-aged through
/// a side connection — no clock injection, no sleeping for age.
/// `old` (30 days) is eligible; `young` (2 days) sits under the 7-day
/// floor; `unknown` (30 days) holds an unknown message and `queued`
/// (30 days) a queued one.
fn seed_agent_gc_state() -> TempDir {
    let seeded = TempDir::new().unwrap();
    let state = seeded.path();
    let db = state.join("cadence.sqlite3");
    let cwd = state.to_str().unwrap().to_string();
    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap()
        .as_secs_f64();
    {
        let store = Store::open(&db).unwrap();
        for alias in ["old", "young", "unknown", "queued"] {
            store
                .register_agent(&NewAgent {
                    alias,
                    provider: "fake",
                    endpoint_kind: "fake",
                    role: "worker",
                    cwd: &cwd,
                    sandbox: "read-only",
                    instructions: None,
                    params: None,
                    team_role: None,
                    model_policy: None,
                })
                .unwrap();
        }
        store
            .enqueue("unknown", "work", None, "m-u", "user")
            .unwrap();
        store
            .enqueue("queued", "work", None, "m-q", "user")
            .unwrap();
    }
    let conn = rusqlite::Connection::open(&db).unwrap();
    for (alias, days) in [
        ("old", 30.0),
        ("young", 2.0),
        ("unknown", 30.0),
        ("queued", 30.0),
    ] {
        conn.execute(
            "UPDATE agents SET state='stopped', enabled=0, endpoint=NULL,
             updated=? WHERE alias=?",
            rusqlite::params![now - days * 86_400.0, alias],
        )
        .unwrap();
    }
    conn.execute("UPDATE messages SET state='unknown' WHERE id='m-u'", [])
        .unwrap();
    seeded
}

fn agent_gc_removed_events(d: &TestDaemon) -> Vec<Value> {
    d.rpc("agent_events", json!({"alias": "daemon", "after": 0}))
        .unwrap()["events"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|e| e["kind"] == "agent_gc_removed")
        .cloned()
        .collect()
}

fn agent_gc_timer_status(d: &TestDaemon) -> Value {
    d.rpc("health", json!({})).unwrap()["agent_gc_timer"].clone()
}

#[test]
fn agent_gc_timer_configured_removes_old_row_with_event() {
    let seeded = seed_agent_gc_state();
    // One hour configured — below the floor, so the timer uses 7 days.
    let d = TestDaemon::start_on_opts(
        seeded.path().to_path_buf(),
        daemon::ServeOptions {
            agent_gc: Some(daemon::AgentGcSetting::older_than(3600)),
            ..daemon_opts()
        },
    );
    // The first stall tick after start sweeps; wait for its record.
    let deadline = Instant::now() + Duration::from_secs(15);
    let events = loop {
        let events = agent_gc_removed_events(&d);
        if !events.is_empty() && agent_gc_timer_status(&d)["last_sweep_at"].is_f64() {
            break events;
        }
        assert!(Instant::now() < deadline, "the agent-gc timer never swept");
        thread::sleep(Duration::from_millis(50));
    };
    assert_eq!(events.len(), 1, "{events:?}");
    let payload = &events[0]["payload"];
    assert_eq!(payload["alias"], "old", "{payload}");
    assert_eq!(payload["records_only"], true, "{payload}");
    assert_eq!(payload["older_than_secs"], 604_800.0, "{payload}");
    assert!(payload["age_secs"].as_f64().unwrap() >= 29.0 * 86_400.0);
    assert!(payload["reason"]
        .as_str()
        .unwrap()
        .contains("agent-gc timer"));
    let note = payload["note"].as_str().unwrap();
    assert!(note.contains("frees no memory and no disk"), "{note}");
    assert!(note.contains("can no longer be resumed"), "{note}");
    assert!(d.rpc("agent_show", json!({"alias": "old"})).is_err());
    // Under the floor, an unknown message, a queued message: all kept.
    for kept in ["young", "unknown", "queued"] {
        d.rpc("agent_show", json!({"alias": kept})).unwrap();
    }
    // `cadence daemon status` renders the effective setting.
    let out = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(&d.state)
        .args(["daemon", "status"])
        .output()
        .unwrap();
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let status: Value = serde_json::from_slice(&out.stdout).unwrap();
    let timer = &status["agent_gc_timer"];
    assert_eq!(timer["enabled"], true, "{status}");
    assert_eq!(timer["older_than_secs"], 604_800, "{status}");
    assert_eq!(timer["configured_secs"], 3600, "{status}");
    assert_eq!(timer["last_removed"], 1, "{status}");
    assert!(timer["warning"].as_str().unwrap().contains("7-day floor"));
    assert!(timer["note"]
        .as_str()
        .unwrap()
        .contains("frees no memory and no disk"));
}

#[test]
fn agent_gc_timer_unconfigured_never_removes() {
    let seeded = seed_agent_gc_state();
    let d = TestDaemon::start_on_opts(seeded.path().to_path_buf(), daemon_opts());
    // Wait until the timer has checked its (off) setting at least once.
    let deadline = Instant::now() + Duration::from_secs(15);
    while !agent_gc_timer_status(&d)["last_check_at"].is_f64() {
        assert!(
            Instant::now() < deadline,
            "the agent-gc timer never checked"
        );
        thread::sleep(Duration::from_millis(50));
    }
    let timer = agent_gc_timer_status(&d);
    assert_eq!(timer["enabled"], false, "{timer}");
    assert!(timer["older_than_secs"].is_null(), "{timer}");
    assert!(timer["last_sweep_at"].is_null(), "{timer}");
    for kept in ["old", "young", "unknown", "queued"] {
        d.rpc("agent_show", json!({"alias": kept})).unwrap();
    }
    assert!(agent_gc_removed_events(&d).is_empty());
}

/// Restart without a lease must fail before shutdown. The daemon pid
/// from `daemon start` is still alive afterwards.
#[test]
fn daemon_restart_without_a_lease_leaves_the_pid_unchanged() {
    let home = TempDir::new().unwrap();
    let state = TempDir::new().unwrap();
    let _reaper = DaemonReaper::new(state.path());
    let start = cadence_at(home.path(), state.path(), &["daemon", "start"]);
    assert!(
        start.status.success(),
        "start: {}",
        String::from_utf8_lossy(&start.stderr)
    );
    let v: Value = serde_json::from_slice(&start.stdout).unwrap();
    let pid = v["pid"].as_u64().unwrap();
    let restart = cadence_at(home.path(), state.path(), &["daemon", "restart"]);
    let err = format!(
        "{} {}",
        String::from_utf8_lossy(&restart.stdout),
        String::from_utf8_lossy(&restart.stderr)
    );
    assert!(!restart.status.success(), "{err}");
    assert!(
        err.contains("before shutdown") && err.contains("rollout"),
        "{err}"
    );
    assert!(
        std::path::Path::new(&format!("/proc/{pid}")).exists(),
        "daemon pid {pid} exited"
    );
    let stop = cadence_at(home.path(), state.path(), &["daemon", "stop"]);
    assert!(
        stop.status.success(),
        "{}",
        String::from_utf8_lossy(&stop.stderr)
    );
}

/// A different build cannot start without the lease. The same build can.
#[test]
fn daemon_start_refuses_a_different_build_without_a_lease() {
    let home = TempDir::new().unwrap();
    let state = TempDir::new().unwrap();
    let _reaper = DaemonReaper::new(state.path());
    let start = cadence_at(home.path(), state.path(), &["daemon", "start"]);
    assert!(
        start.status.success(),
        "{}",
        String::from_utf8_lossy(&start.stderr)
    );
    let stop = cadence_at(home.path(), state.path(), &["daemon", "stop"]);
    assert!(
        stop.status.success(),
        "{}",
        String::from_utf8_lossy(&stop.stderr)
    );
    let db = state.path().join("cadence.sqlite3");
    let conn = rusqlite::Connection::open(&db).unwrap();
    conn.execute(
        "UPDATE daemon_build SET commit_sha='deadbeefdead' WHERE id=1",
        [],
    )
    .unwrap();
    drop(conn);
    let before = sqlite_family(state.path());
    let refused = cadence_at(
        home.path(),
        state.path(),
        &["daemon", "start", "--as", "operator:test"],
    );
    let err = String::from_utf8_lossy(&refused.stderr);
    assert!(!refused.status.success(), "{err}");
    assert!(err.contains("deadbeefdead"), "{err}");
    assert_eq!(
        sqlite_family(state.path()),
        before,
        "a refused start must not rewrite the database or its sidecars"
    );
    hold_rollout_lease(home.path(), state.path());
    let start = cadence_at(
        home.path(),
        state.path(),
        &["daemon", "start", "--as", "operator:test"],
    );
    assert!(
        start.status.success(),
        "{}",
        String::from_utf8_lossy(&start.stderr)
    );
    let stop = cadence_at(home.path(), state.path(), &["daemon", "stop"]);
    assert!(
        stop.status.success(),
        "{}",
        String::from_utf8_lossy(&stop.stderr)
    );
}

/// `--when-idle` queued by the holder must not shut down if the lease
/// is released while the fleet is still busy.
#[test]
fn restart_when_idle_aborts_when_the_lease_is_released() {
    let d = TestDaemon::start();
    let _reaper = DaemonReaper::new(&d.state);
    let mock = d.mock_devin();
    d.register_devin("dv", None);
    d.wait_agent("dv", "idle", 20);
    let busy = d.pane_file(&mock, "dv", "tui-state");
    std::fs::write(
        &busy,
        "⠸ Thinking · 12s (esc twice to interrupt)\n❭ Guide Devin while it works\n",
    )
    .unwrap();
    let probe = d.rpc("agent_probe", json!({"alias": "dv"})).unwrap();
    assert_eq!(
        probe["idle"], false,
        "pane must be busy before the wait: {probe}"
    );
    let home = TempDir::new().unwrap();
    hold_rollout_lease(home.path(), &d.state);
    let started = d.rpc("daemon_info", json!({})).unwrap()["started_at"].clone();
    let mut child = std::process::Command::new(env!("CARGO_BIN_EXE_cadence"))
        .arg("--state-dir")
        .arg(&d.state)
        .args([
            "daemon",
            "restart",
            "--when-idle",
            "--timeout",
            "20",
            "--as",
            "operator:test",
        ])
        .env("HOME", home.path())
        .env_remove("CADENCE_ALIAS")
        .env_remove("CADENCE_ROLLOUT_AS")
        .envs(test_env().vars())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .unwrap();
    thread::sleep(Duration::from_millis(800));
    assert!(
        child.try_wait().unwrap().is_none(),
        "restart finished before the lease was released"
    );
    let release = cadence_at(
        home.path(),
        &d.state,
        &["rollout", "release", "--as", "operator:test"],
    );
    assert!(
        release.status.success(),
        "release: {}",
        String::from_utf8_lossy(&release.stderr)
    );
    std::fs::remove_file(&busy).unwrap();
    let out = child.wait_with_output().unwrap();
    let err = format!(
        "{} {}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(!out.status.success(), "{err}");
    assert!(err.contains("released"), "{err}");
    assert!(err.contains("before shutdown"), "{err}");
    let info = d.rpc("daemon_info", json!({})).unwrap();
    assert_eq!(info["started_at"], started, "daemon was restarted: {info}");
}

fn sqlite_family(state: &std::path::Path) -> Vec<(String, Option<Vec<u8>>)> {
    let db = state.join("cadence.sqlite3");
    ["", "-wal", "-shm"]
        .into_iter()
        .map(|suffix| {
            let path = std::path::PathBuf::from(format!("{}{suffix}", db.display()));
            let bytes = std::fs::read(&path).ok();
            (suffix.to_string(), bytes)
        })
        .collect()
}

/// A refused schema crossing on the real `daemon start` path must not
/// rewrite the database or create `-wal`/`-shm`.
#[test]
fn daemon_start_refuses_a_lower_schema_without_rewriting_the_file() {
    let home = TempDir::new().unwrap();
    let state = TempDir::new().unwrap();
    let _reaper = DaemonReaper::new(state.path());
    let start = cadence_at(home.path(), state.path(), &["daemon", "start"]);
    assert!(
        start.status.success(),
        "{}",
        String::from_utf8_lossy(&start.stderr)
    );
    let stop = cadence_at(home.path(), state.path(), &["daemon", "stop"]);
    assert!(
        stop.status.success(),
        "{}",
        String::from_utf8_lossy(&stop.stderr)
    );
    let db = state.path().join("cadence.sqlite3");
    let conn = rusqlite::Connection::open(&db).unwrap();
    conn.execute_batch(
        "DROP TABLE IF EXISTS rollout_leases;
         DROP TABLE IF EXISTS daemon_build;
         UPDATE schema_version SET version=11;
         PRAGMA wal_checkpoint(TRUNCATE);",
    )
    .unwrap();
    drop(conn);
    for suffix in ["-wal", "-shm"] {
        let path = std::path::PathBuf::from(format!("{}{suffix}", db.display()));
        let _ = std::fs::remove_file(path);
    }
    let before = sqlite_family(state.path());
    let refused = cadence_at(home.path(), state.path(), &["daemon", "start"]);
    assert!(
        !refused.status.success(),
        "{}",
        String::from_utf8_lossy(&refused.stdout)
    );
    let log = std::fs::read_to_string(state.path().join("daemon.log")).unwrap_or_default();
    let err = format!("{} {}", String::from_utf8_lossy(&refused.stderr), log);
    assert!(
        err.contains("refusing to migrate") || err.contains("rollout"),
        "{err}"
    );
    assert_eq!(sqlite_family(state.path()), before);
    let version: i64 = rusqlite::Connection::open(&db)
        .unwrap()
        .query_row("SELECT version FROM schema_version", [], |row| row.get(0))
        .unwrap();
    assert_eq!(version, 11);
}

